// Standards Question Bank: Algebra I (8th Accelerated). GENERATED by tools/stdbank/build.py from tools/stdbank/alg1.py.
// Do not hand-edit; change the .py file and build again. Standards codes are checked against data/standards.js.
// Fields: id, std (Alabama code), part (letter), q, a, lvl (1 on-ramp, 2 on level, 3 stretch), choices, also (other right answers), steps (Vault Raid step help).
export default {"cls": "8th-acc","label": "Algebra I (8th Accelerated)","items": [{"id": "AlgI.1-01","std": "Alg I.1","q": "Write 9^{{1/2}} another way and evaluate it.","a": "√9 = 3","lvl": 1,"also": ["3"],"steps": ["A power of {1/2} means square root: 9^{{1/2}} = √9.","What number times itself is 9?"]},{"id": "AlgI.1-02","std": "Alg I.1","q": "Evaluate: 8^{{1/3}}","a": "2","lvl": 1,"steps": ["A power of {1/3} means cube root: 8^{{1/3}} = ∛8.","What number times itself 3 times is 8?"]},{"id": "AlgI.1-03","std": "Alg I.1","q": "Evaluate: 16^{{3/4}}","a": "8","lvl": 2,"steps": ["Split the power: 16^{{3/4}} = (∜16)³.","Find ∜16: what number to the 4th power is 16?","Now cube that number."]},{"id": "AlgI.1-04","std": "Alg I.1","q": "Write ∛x as a power of x.","a": "x^{{1/3}}","lvl": 1,"also": ["x^(1/3)","x^1/3"],"steps": ["A cube root is the same as a power of {1/3}.","Write x with that power."]},{"id": "AlgI.1-05","std": "Alg I.1","q": "Why does 5^{{1/2}} = √5? Use (5^{{1/2}})².","a": "(5^{{1/2}})² = 5¹ = 5, so 5^{{1/2}} is the number whose square is 5","lvl": 3,"also": ["√5"],"steps": ["Power to a power: multiply the exponents.","{1/2} × 2 = 1, so (5^{{1/2}})² = 5¹ = 5.","So 5^{{1/2}} is a number whose square is 5. What other symbol means that?"]},{"id": "AlgI.1-06","std": "Alg I.1","q": "Evaluate: 27^{{2/3}}","a": "9","lvl": 2,"steps": ["Split the power: 27^{{2/3}} = (∛27)².","∛27 = 3, because 3 × 3 × 3 = 27.","Now square it."]},{"id": "AlgI.1-07","std": "Alg I.1","q": "Evaluate: 25^{−{1/2}}","a": "{1/5}","lvl": 3,"also": ["0.2"],"steps": ["A negative power means 1 over it: 25^{−{1/2}} = {1/√25}.","Find √25, then write the fraction."]},{"id": "AlgI.2-01","std": "Alg I.2","q": "Simplify: √50","a": "5√2","lvl": 1,"steps": ["Find the biggest perfect square that goes into 50: 25 × 2 = 50.","√50 = √25 × √2. Take √25."]},{"id": "AlgI.2-02","std": "Alg I.2","q": "Simplify: √72","a": "6√2","lvl": 2,"steps": ["Find the biggest perfect square that goes into 72: 36 × 2 = 72.","√72 = √36 × √2. Take √36."]},{"id": "AlgI.2-03","std": "Alg I.2","q": "Simplify: √(x⁶)","a": "x³","lvl": 2,"also": ["x^3"],"steps": ["A square root cuts the exponent in half.","What is half of 6?"]},{"id": "AlgI.2-04","std": "Alg I.2","q": "Write x^{{3/2}} as a radical.","a": "√(x³)","lvl": 2,"also": ["(√x)³","x√x"],"steps": ["The bottom of the fraction power is the root. A 2 means square root.","The top of the fraction power is the power inside the root."]},{"id": "AlgI.2-05","std": "Alg I.2","q": "Simplify: x^{{1/2}} · x^{{3/2}}","a": "x²","lvl": 2,"also": ["x^2"],"steps": ["Same base, multiplying: add the exponents.","{1/2} + {3/2} = {4/2}. Simplify."]},{"id": "AlgI.2-06","std": "Alg I.2","q": "Simplify: (x^{{2/3}})³","a": "x²","lvl": 2,"also": ["x^2"],"steps": ["Power to a power: multiply the exponents.","{2/3} × 3 = ?"]},{"id": "AlgI.2-07","std": "Alg I.2","q": "Simplify: √12 + √27","a": "5√3","lvl": 3,"steps": ["Simplify each root. √12 = √4 × √3 = 2√3.","√27 = √9 × √3 = 3√3.","Both are √3 terms. Add the numbers in front."]},{"id": "AlgI.2-08","std": "Alg I.2","q": "Simplify: ∛54","a": "3∛2","lvl": 3,"steps": ["Find the biggest perfect cube that goes into 54: 27 × 2 = 54.","∛54 = ∛27 × ∛2. Take ∛27."]},{"id": "AlgI.3-01","std": "Alg I.3","q": "What is i²?","a": "−1","lvl": 1,"steps": ["i means √(−1).","Squaring a square root undoes it. What is (√(−1))²?"]},{"id": "AlgI.3-02","std": "Alg I.3","q": "Write √(−25) using i.","a": "5i","lvl": 1,"steps": ["Split it: √(−25) = √25 × √(−1).","√(−1) = i. Find √25."]},{"id": "AlgI.3-03","std": "Alg I.3","q": "Write √(−7) using i.","a": "i√7","lvl": 2,"also": ["√7i","√7 i"],"steps": ["Split it: √(−7) = √7 × √(−1).","√(−1) = i. 7 isn't a perfect square, so √7 stays."]},{"id": "AlgI.3-04","std": "Alg I.3","q": "Simplify: i³","a": "−i","lvl": 2,"steps": ["Break it up: i³ = i² × i.","Use i² = −1, then multiply."]},{"id": "AlgI.3-05","std": "Alg I.3","q": "Simplify: i⁴","a": "1","lvl": 2,"steps": ["Break it up: i⁴ = i² × i².","Use i² = −1, then multiply."]},{"id": "AlgI.3-06","std": "Alg I.3","q": "Simplify: √(−36) + √(−4)","a": "8i","lvl": 3,"steps": ["Write each with i: √(−36) = 6i.","√(−4) = 2i. Add the like terms."]},{"id": "AlgI.3-07","std": "Alg I.3","q": "Is √(−9) a real number?","a": "No (it is 3i)","lvl": 1,"also": ["no"],"steps": ["No real number times itself gives a negative.","√(−9) = 3i. Is i a real number?"]},{"id": "AlgI.4-01","std": "Alg I.4","q": "In 1,000(1.05)^t, what does 1.05 mean?","a": "The amount grows 5% each year","lvl": 1,"also": ["5% growth"],"steps": ["In a(b)^{t}, b is what you multiply by each year.","1.05 = 1 + 0.05. Write 0.05 as a percent. Is it growing or shrinking?"]},{"id": "AlgI.4-02","std": "Alg I.4","q": "In 1,000(1.05)^t, what does 1,000 mean?","a": "The starting amount","lvl": 1,"also": ["initial amount","starting value"],"steps": ["Put t = 0: 1,000(1.05)⁰ = 1,000 × 1.","So 1,000 is the amount at time 0. What is that called?"]},{"id": "AlgI.4-03","std": "Alg I.4","q": "A phone plan costs 25 + 0.10t for t texts. What does 0.10 mean?","a": "§0.10 per text","lvl": 1,"also": ["10 cents per text"],"steps": ["In 25 + 0.10t, the 0.10 is multiplied by t, the number of texts.","So each text adds how much?"]},{"id": "AlgI.4-04","std": "Alg I.4","q": "In 500(0.8)^t, is the amount growing or decaying? By what percent?","a": "Decaying by 20% each period","lvl": 2,"also": ["decay 20%","decaying"],"steps": ["0.8 is less than 1, so you keep less each period. Growing or decaying?","Find the part lost: 1 − 0.8 = 0.2. Write 0.2 as a percent."]},{"id": "AlgI.4-05","std": "Alg I.4","q": "The area of a garden is (x + 3)(x + 2). What do x + 3 and x + 2 stand for?","a": "The length and width","lvl": 2,"also": ["length and width"],"steps": ["Area of a rectangle = length × width.","So what do the two factors stand for?"]},{"id": "AlgI.4-06","std": "Alg I.4","q": "h = −16t² + 64t + 5 gives a ball's height. What does 5 mean?","a": "The ball starts 5 ft above the ground","lvl": 2,"also": ["starting height","5 ft"],"steps": ["Put t = 0 for the start: h = −16(0)² + 64(0) + 5.","So 5 is the height at the very start. Where is the ball then?"]},{"id": "AlgI.4-07","std": "Alg I.4","q": "P(1 + r)^t: if r = 0.03, what is the growth factor?","a": "1.03","lvl": 2,"steps": ["The growth factor is 1 + r.","Put in r = 0.03."]},{"id": "AlgI.5-01","std": "Alg I.5","q": "Factor: x² − 49","a": "(x + 7)(x − 7)","lvl": 1,"also": ["(x − 7)(x + 7)"],"steps": ["This is a difference of squares: a² − b² = (a + b)(a − b).","x² is x squared and 49 is 7². So a = x and b = 7."]},{"id": "AlgI.5-02","std": "Alg I.5","q": "Factor: x⁴ − 16 completely.","a": "(x² + 4)(x + 2)(x − 2)","lvl": 3,"steps": ["x⁴ = (x²)² and 16 = 4². So x⁴ − 16 = (x² + 4)(x² − 4).","x² − 4 is a difference of squares too. Factor it again.","x² + 4 doesn't factor with real numbers. Keep it as it is."]},{"id": "AlgI.5-03","std": "Alg I.5","q": "Factor: 4x² − 9","a": "(2x + 3)(2x − 3)","lvl": 2,"also": ["(2x − 3)(2x + 3)"],"steps": ["4x² = (2x)² and 9 = 3².","Use a² − b² = (a + b)(a − b) with a = 2x and b = 3."]},{"id": "AlgI.5-04","std": "Alg I.5","q": "Rewrite x² + 6x + 9 as a square.","a": "(x + 3)²","lvl": 2,"steps": ["9 is a perfect square: 9 = 3².","Check the middle: 2 × x × 3 = 6x. So it's (x + ?)²."]},{"id": "AlgI.5-05","std": "Alg I.5","q": "Factor out the GCF: 6x³ + 9x²","a": "3x²(2x + 3)","lvl": 1,"steps": ["The GCF of 6 and 9 is 3. The GCF of x³ and x² is x².","Pull out 3x²: divide each term by 3x²."]},{"id": "AlgI.5-06","std": "Alg I.5","q": "Find 51² − 49² using a difference of squares.","a": "200","lvl": 3,"steps": ["Use a² − b² = (a + b)(a − b) with a = 51 and b = 49.","51 + 49 = 100 and 51 − 49 = 2. Multiply."]},{"id": "AlgI.5-07","std": "Alg I.5","q": "Factor: x² − 10x + 25","a": "(x − 5)²","lvl": 2,"steps": ["25 is a perfect square: 25 = 5². Check the middle: 2 × x × 5 = 10x.","The middle term is minus, so it's (x − ?)²."]},{"id": "AlgI.6-01","std": "Alg I.6","q": "Factor y = x² − 5x + 6 to find the zeros.","a": "x = 2 and x = 3","lvl": 2,"also": ["2, 3","2 and 3"],"steps": ["Find two numbers that multiply to 6 and add to −5: −2 and −3.","So y = (x − 2)(x − 3). Set each factor equal to 0."]},{"id": "AlgI.6-02","std": "Alg I.6","q": "Complete the square: y = x² + 4x + 1. What is the vertex?","a": "(−2, −3)","lvl": 3,"steps": ["Half of 4 is 2, and 2² = 4. Add and subtract 4: y = x² + 4x + 4 − 4 + 1.","Now it's y = (x + 2)² − 3.","In y = (x − h)² + k the vertex is (h, k). x + 2 means h = −2."]},{"id": "AlgI.6-03","std": "Alg I.6","q": "y = (x − 3)² + 4. What is the minimum value?","a": "4","lvl": 1,"steps": ["(x − 3)² is never negative. Its smallest value is 0.","When (x − 3)² = 0, what is y?"]},{"id": "AlgI.6-04","std": "Alg I.6","q": "Rewrite 1.2^t as a monthly rate: 1.2^t = (1.2^{{1/12}})^{12t}. About what is the monthly growth factor? Round to 3 decimals.","a": "1.015","lvl": 3,"steps": ["The monthly factor is 1.2^{{1/12}}, the 12th root of 1.2.","On a calculator, type 1.2, the power key, then (1 ÷ 12). Round to 3 decimals."]},{"id": "AlgI.6-05","std": "Alg I.6","q": "y = (x + 1)(x − 7). Where is the axis of symmetry?","a": "x = 3","lvl": 2,"steps": ["The zeros are where each factor is 0: x = −1 and x = 7.","The axis of symmetry is halfway between the zeros: (−1 + 7) ÷ 2."]},{"id": "AlgI.6-06","std": "Alg I.6","q": "Which form shows the zeros of a quadratic: standard, vertex, or factored?","a": "Factored","lvl": 1,"choices": ["Standard","Vertex","Factored"],"steps": ["Factored form looks like y = a(x − p)(x − q).","Setting each factor to 0 gives the zeros. Which form lets you read them right away?"]},{"id": "AlgI.6-07","std": "Alg I.6","q": "Which form shows the vertex of a quadratic: standard, vertex, or factored?","a": "Vertex","lvl": 1,"choices": ["Standard","Vertex","Factored"],"steps": ["Vertex form looks like y = a(x − h)² + k.","In that form you can read (h, k) right off. Which form is that?"]},{"id": "AlgI.6-08","std": "Alg I.6","q": "Find the zeros of y = x² + 2x − 15 by factoring.","a": "x = −5 and x = 3","lvl": 2,"also": ["−5, 3","−5 and 3"],"steps": ["Find two numbers that multiply to −15 and add to 2: 5 and −3.","So y = (x + 5)(x − 3). Set each factor equal to 0."]},{"id": "AlgI.7-01","std": "Alg I.7","q": "Add: (3x² + 2x − 5) + (x² − 4x + 7)","a": "4x² − 2x + 2","lvl": 1,"steps": ["Group like terms: (3x² + x²) + (2x − 4x) + (−5 + 7).","Add each group."]},{"id": "AlgI.7-02","std": "Alg I.7","q": "Subtract: (5x² − 3x + 1) − (2x² + x − 4)","a": "3x² − 4x + 5","lvl": 2,"steps": ["The minus goes to every term in the second group: 5x² − 3x + 1 − 2x² − x + 4.","Group like terms and combine."]},{"id": "AlgI.7-03","std": "Alg I.7","q": "Multiply: (x + 4)(x − 2)","a": "x² + 2x − 8","lvl": 1,"steps": ["Multiply each term by each term: x · x, x · (−2), 4 · x, 4 · (−2).","That gives x² − 2x + 4x − 8. Combine the x terms."]},{"id": "AlgI.7-04","std": "Alg I.7","q": "Multiply: (2x − 3)(x + 5)","a": "2x² + 7x − 15","lvl": 2,"steps": ["Multiply each term by each term: 2x · x, 2x · 5, −3 · x, −3 · 5.","That gives 2x² + 10x − 3x − 15. Combine the x terms."]},{"id": "AlgI.7-05","std": "Alg I.7","q": "Multiply: (x − 6)²","a": "x² − 12x + 36","lvl": 2,"steps": ["Write it twice: (x − 6)(x − 6).","Multiply each pair: x² − 6x − 6x + 36. Combine the x terms."]},{"id": "AlgI.7-06","std": "Alg I.7","q": "Multiply: 3x(x² − 2x + 4)","a": "3x³ − 6x² + 12x","lvl": 1,"steps": ["Multiply 3x by each term: 3x · x², 3x · (−2x), 3x · 4.","Same base, multiplying: add the exponents. x · x² = x³."]},{"id": "AlgI.7-07","std": "Alg I.7","q": "Multiply: (x + 1)(x² − x + 1)","a": "x³ + 1","lvl": 3,"steps": ["Multiply x by each term: x³ − x² + x.","Multiply 1 by each term: x² − x + 1.","Add the two rows. Some terms cancel."]},{"id": "AlgI.7-08","std": "Alg I.7","q": "Is the product of two polynomials always a polynomial?","a": "Yes (polynomials are closed under multiplication)","lvl": 2,"choices": ["Yes (polynomials are closed under multiplication)","No"],"steps": ["Multiplying polynomials gives terms like a number times x to a whole-number power.","Can that ever make a negative or fraction exponent?"]},{"id": "AlgI.7-09","std": "Alg I.7","q": "What is the degree of 4x³ − x⁵ + 2?","a": "5","lvl": 1,"steps": ["The degree is the highest exponent.","Look at every term: 4x³, −x⁵ and 2. Which exponent is biggest?"]},{"id": "AlgI.8-01","std": "Alg I.8","q": "Solve: |x − 3| = 7","a": "x = 10 or x = −4","lvl": 1,"also": ["10, −4","−4, 10"],"steps": ["The inside is 7 or −7: x − 3 = 7 or x − 3 = −7.","Add 3 to both sides of each."]},{"id": "AlgI.8-02","std": "Alg I.8","q": "Solve: |2x + 1| = 9","a": "x = 4 or x = −5","lvl": 2,"also": ["4, −5","−5, 4"],"steps": ["The inside is 9 or −9: 2x + 1 = 9 or 2x + 1 = −9.","Subtract 1, then divide by 2, in each one."]},{"id": "AlgI.8-03","std": "Alg I.8","q": "Solve: |x + 5| = −2","a": "No solution (an absolute value cannot be negative)","lvl": 1,"also": ["no solution"],"steps": ["An absolute value is a distance from 0.","Can a distance be negative?"]},{"id": "AlgI.8-04","std": "Alg I.8","q": "Solve: |x| + 4 = 10","a": "x = 6 or x = −6","lvl": 1,"also": ["±6"],"steps": ["Get the absolute value alone: subtract 4. Now |x| = 6.","Which numbers are 6 away from 0?"]},{"id": "AlgI.8-05","std": "Alg I.8","q": "Solve and check: |x − 1| = 2x + 4","a": "x = −1 (x = −5 is extraneous)","lvl": 3,"also": ["−1","x = −1"],"steps": ["Case 1: x − 1 = 2x + 4. That gives x = −5.","Case 2: x − 1 = −(2x + 4). That gives 3x = −3, so x = −1.","Check x = −5: |−6| = 6, but 2(−5) + 4 = −6. Does it work?"]},{"id": "AlgI.8-06","std": "Alg I.8","q": "Why must you check answers to |x + 2| = x − 4?","a": "Splitting into two cases can give a value that makes x − 4 negative, and an absolute value cannot equal a negative number, so that value is extraneous","lvl": 2,"steps": ["Try the case x + 2 = −(x − 4). That gives x = 1.","Put x = 1 back in: |1 + 2| = 3, but 1 − 4 = −3.","Can an absolute value equal a negative number?"]},{"id": "AlgI.8-07","std": "Alg I.8","q": "Solve and check: |3x| = x + 8","a": "x = 4 or x = −2","lvl": 3,"also": ["4, −2","−2, 4"],"steps": ["Case 1: 3x = x + 8. Solve for x.","Case 2: 3x = −(x + 8), so 4x = −8. Solve for x.","Check both in |3x| = x + 8."]},{"id": "AlgI.9-01","std": "Alg I.9","q": "Solve by inspection: x² = 49","a": "x = ±7","lvl": 1,"part": "b","also": ["±7","7 and −7"],"steps": ["What number squared is 49?","A negative number squared is positive too. Use ±."]},{"id": "AlgI.9-02","std": "Alg I.9","q": "Solve: (x − 2)² = 25","a": "x = 7 or x = −3","lvl": 2,"part": "b","also": ["7, −3","−3, 7"],"steps": ["Take the square root of both sides: x − 2 = 5 or x − 2 = −5.","Add 2 to each."]},{"id": "AlgI.9-03","std": "Alg I.9","q": "Solve by factoring: x² + 5x + 6 = 0","a": "x = −2 or x = −3","lvl": 2,"part": "b","also": ["−2, −3","−3, −2"],"steps": ["Find two numbers that multiply to 6 and add to 5: 2 and 3.","So (x + 2)(x + 3) = 0. Set each factor equal to 0."]},{"id": "AlgI.9-04","std": "Alg I.9","q": "Solve: x² − 4x − 12 = 0","a": "x = 6 or x = −2","lvl": 2,"part": "b","also": ["6, −2","−2, 6"],"steps": ["Find two numbers that multiply to −12 and add to −4: −6 and 2.","So (x − 6)(x + 2) = 0. Set each factor equal to 0."]},{"id": "AlgI.9-05","std": "Alg I.9","q": "Complete the square: x² + 6x = 7. Write it as (x + p)² = q.","a": "(x + 3)² = 16","lvl": 2,"part": "a","steps": ["Half of 6 is 3, and 3² = 9.","Add 9 to both sides: x² + 6x + 9 = 16.","The left side is a perfect square: (x + ?)²."]},{"id": "AlgI.9-06","std": "Alg I.9","q": "Complete the square to solve: x² − 8x + 3 = 0","a": "x = 4 ± √13","lvl": 3,"part": "a","also": ["4 ± √13"],"steps": ["Move the 3: x² − 8x = −3.","Half of −8 is −4, and (−4)² = 16. Add 16 to both sides: (x − 4)² = 13.","Take the square root of both sides, then add 4."]},{"id": "AlgI.9-07","std": "Alg I.9","q": "Solve with the quadratic formula: 2x² + 3x − 2 = 0","a": "x = {1/2} or x = −2","lvl": 3,"part": "b","also": ["1/2, −2","0.5, −2"],"steps": ["a = 2, b = 3, c = −2. Use x = {−b ± √(b² − 4ac)/2a}.","b² − 4ac = 9 − 4(2)(−2) = 25, and √25 = 5.","x = {−3 ± 5/4}. Find one answer with + and one with −."]},{"id": "AlgI.9-08","std": "Alg I.9","q": "Solve: x² + 9 = 0","a": "x = ±3i (no real solutions)","lvl": 3,"part": "b","also": ["±3i","no real solution"],"steps": ["Subtract 9: x² = −9.","Take the square root: x = ±√(−9). Use √(−1) = i."]},{"id": "AlgI.9-09","std": "Alg I.9","q": "What is the discriminant of x² + 2x + 5? How many real solutions?","a": "−16; no real solutions","lvl": 3,"part": "b","also": ["−16"],"steps": ["The discriminant is b² − 4ac. Here a = 1, b = 2, c = 5.","2² − 4(1)(5) = 4 − 20.","A negative discriminant means no real solutions."]},{"id": "AlgI.9-10","std": "Alg I.9","q": "Solve: 3x² = 48","a": "x = ±4","lvl": 1,"part": "b","also": ["±4"],"steps": ["Divide both sides by 3: x² = 16.","Take the square root. Remember ±."]},{"id": "AlgI.10-01","std": "Alg I.10","q": "Solve by elimination: x + y = 10 and x − y = 4","a": "(7, 3)","lvl": 1,"part": "a","steps": ["Add the equations. The y's cancel: 2x = 14.","Solve for x, then put it into x + y = 10."]},{"id": "AlgI.10-02","std": "Alg I.10","q": "Solve by elimination: 2x + 3y = 12 and 2x − y = 4","a": "(3, 2)","lvl": 2,"part": "a","steps": ["Subtract the second equation from the first. The 2x's cancel: 4y = 8.","Solve for y, then put it into 2x − y = 4."]},{"id": "AlgI.10-03","std": "Alg I.10","q": "Solve: 3x + 2y = 16 and x − 2y = 0","a": "(4, 2)","lvl": 2,"part": "a","steps": ["Add the equations. The 2y's cancel: 4x = 16.","Solve for x, then put it into x − 2y = 0."]},{"id": "AlgI.10-04","std": "Alg I.10","q": "Solve: 4x + 3y = 5 and 2x + y = 1","a": "(−1, 3)","lvl": 3,"part": "a","steps": ["Multiply the second equation by 2: 4x + 2y = 2.","Subtract it from the first: y = 3.","Put y = 3 into 2x + y = 1 and solve for x."]},{"id": "AlgI.10-05","std": "Alg I.10","q": "Which method is faster for y = 3x − 1 and 2x + y = 9: substitution or elimination?","a": "Substitution (y is already alone)","lvl": 1,"part": "a","also": ["substitution"],"steps": ["Look at y = 3x − 1. Is y already by itself?","When a letter is alone, you can put it right into the other equation. Which method does that?"]},{"id": "AlgI.10-06","std": "Alg I.10","q": "Solve y = 3x − 1 and 2x + y = 9.","a": "(2, 5)","lvl": 2,"part": "a","steps": ["y is alone, so substitute: 2x + (3x − 1) = 9.","Combine: 5x − 1 = 9. Solve for x.","Put x into y = 3x − 1. Write it as (x, y)."]},{"id": "AlgI.10-07","std": "Alg I.10","q": "A table for y = 2x + 1 and y = −x + 7 shows the same y at x = 2. What is the solution?","a": "(2, 5)","lvl": 2,"part": "b","steps": ["At x = 2, both give y = 2(2) + 1.","The solution is where both have the same x and y. Write it as (x, y)."]},{"id": "AlgI.10-08","std": "Alg I.10","q": "Elimination gives 0 = 6. What does that mean?","a": "No solution","lvl": 2,"part": "b","choices": ["One solution","No solution","Infinitely many solutions"],"steps": ["0 = 6 is never true.","If no x and y make it true, how many solutions are there?"]},{"id": "AlgI.11-01","std": "Alg I.11","q": "You have §60 and spend §4 a day. Write and solve an inequality for the days d until you have less than §20.","a": "60 − 4d < 20, so d > 10","lvl": 2,"also": ["d > 10"],"steps": ["Start at 60 and take away 4 each day: 60 − 4d.","Less than 20: 60 − 4d < 20.","Subtract 60: −4d < −40. Dividing by a negative flips the sign."]},{"id": "AlgI.11-02","std": "Alg I.11","q": "Solve: 3x − 7 ≥ 11","a": "x ≥ 6","lvl": 1,"steps": ["Add 7 to both sides: 3x ≥ 18.","Divide both sides by 3."]},{"id": "AlgI.11-03","std": "Alg I.11","q": "Solve: −2x + 5 < 13","a": "x > −4","lvl": 1,"steps": ["Subtract 5 from both sides: −2x < 8.","Divide by −2. Dividing by a negative flips the sign."]},{"id": "AlgI.11-04","std": "Alg I.11","q": "Solve: −3 ≤ 2x + 1 < 9","a": "−2 ≤ x < 4","lvl": 2,"steps": ["Do the same thing to all three parts. Subtract 1: −4 ≤ 2x < 8.","Divide all three parts by 2."]},{"id": "AlgI.11-05","std": "Alg I.11","q": "Solve: |x − 4| < 3","a": "1 < x < 7","lvl": 2,"steps": ["Less than means between: −3 < x − 4 < 3.","Add 4 to all three parts."]},{"id": "AlgI.11-06","std": "Alg I.11","q": "Solve: |x + 2| ≥ 5","a": "x ≤ −7 or x ≥ 3","lvl": 3,"steps": ["Greater than means outside: x + 2 ≤ −5 or x + 2 ≥ 5.","Subtract 2 from each."]},{"id": "AlgI.11-07","std": "Alg I.11","q": "A rectangle's length is 3 more than its width. Its area is 40. Write and solve an equation for the width.","a": "w(w + 3) = 40, w = 5","lvl": 3,"also": ["5","w = 5"],"steps": ["The width is w, so the length is w + 3. Area: w(w + 3) = 40.","Expand: w² + 3w − 40 = 0. Factor: (w + 8)(w − 5) = 0.","A width can't be negative. Which one works?"]},{"id": "AlgI.11-08","std": "Alg I.11","q": "A population of 200 doubles every year. Write an equation for when it reaches 3,200 and solve it.","a": "200 · 2^t = 3,200, t = 4 years","lvl": 3,"also": ["4","t = 4"],"steps": ["Doubling each year: 200 · 2^{t} = 3,200.","Divide both sides by 200: 2^{t} = 16.","What power of 2 is 16? Count: 2, 4, 8, 16."]},{"id": "AlgI.11-09","std": "Alg I.11","q": "Your test scores are 82 and 91. What score x on the 3rd test gives an average of at least 88?","a": "x ≥ 91","lvl": 2,"also": ["91"],"steps": ["Average of 3 tests: {82 + 91 + x/3} ≥ 88.","Multiply both sides by 3: 173 + x ≥ 264.","Subtract 173 from both sides."]},{"id": "AlgI.12-01","std": "Alg I.12","q": "Hot dogs cost §3 and drinks cost §2. You spend §24. Write an equation.","a": "3h + 2d = 24","lvl": 1,"steps": ["Each hot dog is §3, so h hot dogs cost 3h.","Each drink is §2, so d drinks cost 2d. Together they equal 24."]},{"id": "AlgI.12-02","std": "Alg I.12","q": "A plant is 4 cm tall and grows 1.5 cm a week. Write an equation for height h after w weeks.","a": "h = 1.5w + 4","lvl": 1,"steps": ["It grows 1.5 cm each week, so after w weeks it grew 1.5w.","Add the starting height, 4 cm."]},{"id": "AlgI.12-03","std": "Alg I.12","q": "A car worth §20,000 loses 15% of its value each year. Write an equation for its value v after t years.","a": "v = 20,000(0.85)^t","lvl": 2,"also": ["v = 20000(0.85)^t"],"steps": ["Losing 15% means you keep 85% each year: 1 − 0.15 = 0.85.","Start at 20,000 and multiply by 0.85 each year. Use t as the power."]},{"id": "AlgI.12-04","std": "Alg I.12","q": "Using 3h + 2d = 24, if you buy 4 hot dogs, how many drinks?","a": "6","lvl": 1,"steps": ["Put h = 4 in: 3(4) + 2d = 24, so 12 + 2d = 24.","Subtract 12, then divide by 2."]},{"id": "AlgI.12-05","std": "Alg I.12","q": "A ball's height is h = −16t² + 48t. When does it land?","a": "t = 3 seconds","lvl": 3,"also": ["3"],"steps": ["It lands when h = 0: −16t² + 48t = 0.","Factor: −16t(t − 3) = 0. Set each factor to 0.","t = 0 is when it's thrown. Which time is the landing?"]},{"id": "AlgI.12-06","std": "Alg I.12","q": "Using v = 20,000(0.85)^t, predict the value after 2 years.","a": "§14,450.00","lvl": 2,"also": ["14450","14,450"],"steps": ["Put t = 2 in: v = 20,000(0.85)².","0.85² = 0.7225. Multiply by 20,000."]},{"id": "AlgI.12-07","std": "Alg I.12","q": "When you graph h = 1.5w + 4, what labels go on the axes?","a": "Weeks on the x-axis, height in cm on the y-axis","lvl": 1,"steps": ["The input goes on the x-axis. Here the input is w, the weeks.","The output goes on the y-axis. What is the output, and what is its unit?"]},{"id": "AlgI.13-01","std": "Alg I.13","q": "You can spend at most §50 on shirts (§10) and hats (§5). Write the constraint.","a": "10s + 5h ≤ 50","lvl": 1,"steps": ["Shirts cost §10 each: 10s. Hats cost §5 each: 5h.","At most §50 means the total is less than or equal to 50."]},{"id": "AlgI.13-02","std": "Alg I.13","q": "Using 10s + 5h ≤ 50, is buying 3 shirts and 5 hats viable?","a": "No (§55 is over §50)","lvl": 2,"also": ["no"],"steps": ["Put s = 3 and h = 5 in: 10(3) + 5(5).","Is the total less than or equal to 50?"]},{"id": "AlgI.13-03","std": "Alg I.13","q": "Using 10s + 5h ≤ 50, is (2.5, 4) a viable answer?","a": "No (you cannot buy half a shirt)","lvl": 2,"also": ["no"],"steps": ["(2.5, 4) means 2.5 shirts and 4 hats.","Can you buy half of a shirt?"]},{"id": "AlgI.13-04","std": "Alg I.13","q": "A system: x + y ≤ 8, x ≥ 2, y ≥ 0. Is (3, 4) a solution?","a": "Yes","lvl": 1,"choices": ["Yes","No"],"steps": ["Use x = 3 and y = 4. Check x + y ≤ 8: 3 + 4 = 7.","Check x ≥ 2 and y ≥ 0.","A solution has to make all three true. Does it?"]},{"id": "AlgI.13-05","std": "Alg I.13","q": "A system: x + y ≤ 8, x ≥ 2, y ≥ 0. Is (1, 5) a solution?","a": "No (x must be at least 2)","lvl": 1,"also": ["no"],"steps": ["Check x ≥ 2 with x = 1.","A solution has to make every inequality true."]},{"id": "AlgI.13-06","std": "Alg I.13","q": "Solve the system: y = x² and y = 4","a": "(2, 4) and (−2, 4)","lvl": 3,"steps": ["Both equal y, so set them equal: x² = 4.","x = 2 or x = −2. Find y for each, then write both points."]},{"id": "AlgI.13-07","std": "Alg I.13","q": "A field trip needs at least 60 seats. Vans hold 8 and cars hold 4. Write the constraint.","a": "8v + 4c ≥ 60","lvl": 2,"steps": ["Vans hold 8 each: 8v. Cars hold 4 each: 4c.","At least 60 means the seats are greater than or equal to 60."]},{"id": "AlgI.13-08","std": "Alg I.13","q": "In a problem about tickets sold, is −3 a viable solution?","a": "No (you cannot sell negative tickets)","lvl": 1,"also": ["no"],"steps": ["−3 would mean selling −3 tickets.","Can you sell a negative number of tickets?"]},{"id": "AlgI.14-01","std": "Alg I.14","q": "Is (2, 7) on the graph of y = 3x + 1?","a": "Yes (3(2) + 1 = 7)","lvl": 1,"also": ["yes"],"steps": ["Put x = 2 in: y = 3(2) + 1.","Does it give y = 7?"]},{"id": "AlgI.14-02","std": "Alg I.14","q": "Is (−1, 3) on the graph of y = x² + 1?","a": "No (y would be 2)","lvl": 1,"also": ["no"],"steps": ["Put x = −1 in: y = (−1)² + 1.","Does it give y = 3?"]},{"id": "AlgI.14-03","std": "Alg I.14","q": "The graph of 2x + y = 6 crosses the y-axis where?","a": "(0, 6)","lvl": 1,"steps": ["On the y-axis, x = 0. Put it in: 2(0) + y = 6.","Solve for y. Write it as a point."]},{"id": "AlgI.14-04","std": "Alg I.14","q": "Find k so that (3, k) is on the graph of y = 2x − 5.","a": "k = 1","lvl": 2,"steps": ["Put x = 3 in: k = 2(3) − 5.","Multiply, then subtract."]},{"id": "AlgI.14-05","std": "Alg I.14","q": "What does the graph of an equation in two variables show?","a": "Every solution (x, y) of the equation","lvl": 1,"steps": ["Each point on the graph is an (x, y) pair.","Does every point on the graph make the equation true?"]},{"id": "AlgI.14-06","std": "Alg I.14","q": "Is (4, −2) on the graph of y = |x − 6|?","a": "No (y would be 2)","lvl": 2,"also": ["no"],"steps": ["Put x = 4 in: y = |4 − 6| = |−2|.","An absolute value is never negative. Can it equal −2?"]},{"id": "AlgI.14-07","std": "Alg I.14","q": "Find the x-intercept of 3x − 4y = 12.","a": "(4, 0)","lvl": 2,"steps": ["On the x-axis, y = 0. Put it in: 3x − 4(0) = 12.","Solve for x. Write it as a point."]},{"id": "AlgI.15-01","std": "Alg I.15","q": "f(x) = 2x² − 3. Find f(−2).","a": "5","lvl": 1,"steps": ["Put −2 in for x: f(−2) = 2(−2)² − 3.","Square first: (−2)² = 4. Then multiply by 2 and subtract 3."]},{"id": "AlgI.15-02","std": "Alg I.15","q": "f(x) = 3(2)^x. Find f(3).","a": "24","lvl": 1,"steps": ["Put 3 in for x: f(3) = 3(2)³.","Do the power first: 2³ = 8. Then multiply by 3."]},{"id": "AlgI.15-03","std": "Alg I.15","q": "f(x) = |x − 5|. Find f(1).","a": "4","lvl": 1,"steps": ["Put 1 in for x: f(1) = |1 − 5| = |−4|.","Absolute value is the distance from 0."]},{"id": "AlgI.15-04","std": "Alg I.15","q": "f(x) = 4x − 7. Solve f(x) = 13.","a": "x = 5","lvl": 2,"steps": ["Set 4x − 7 = 13.","Add 7, then divide by 4."]},{"id": "AlgI.15-05","std": "Alg I.15","q": "C(n) = 15n + 40 is the cost of n people at a party. What does C(10) = 190 mean?","a": "10 people cost §190","lvl": 2,"steps": ["C(10) means n = 10 people.","190 is the cost C. Put that in words."]},{"id": "AlgI.15-06","std": "Alg I.15","q": "What is the domain of {(1, 3), (2, 5), (4, 3)}?","a": "{1, 2, 4}","lvl": 1,"steps": ["The domain is the inputs, the x-values.","Read the first number from each pair. List each one once."]},{"id": "AlgI.15-07","std": "Alg I.15","q": "What is the range of {(1, 3), (2, 5), (4, 3)}?","a": "{3, 5}","lvl": 1,"steps": ["The range is the outputs, the y-values.","Read the second number from each pair. List each one once."]},{"id": "AlgI.15-08","std": "Alg I.15","q": "A function gives the height of a ball for 0 ≤ t ≤ 4 seconds. What is a sensible domain?","a": "0 ≤ t ≤ 4","lvl": 2,"steps": ["The height is only known from t = 0 to t = 4.","Write that as an inequality for t."]},{"id": "AlgI.15-09","std": "Alg I.15","q": "What is the range of f(x) = x² + 2?","a": "y ≥ 2","lvl": 3,"also": ["f(x) ≥ 2"],"steps": ["x² is never negative. Its smallest value is 0.","So the smallest x² + 2 can be is 0 + 2. Can it go higher?"]},{"id": "AlgI.16-01","std": "Alg I.16","q": "Is y = 3x − 2 a function?","a": "Yes","lvl": 1,"choices": ["Yes","No"],"steps": ["A function gives each x exactly one y.","Put any x into 3x − 2. Do you ever get two answers?"]},{"id": "AlgI.16-02","std": "Alg I.16","q": "Is x² + y² = 25 a function?","a": "No (most x values have two y values)","lvl": 2,"also": ["no"],"steps": ["Try x = 0: y² = 25, so y = 5 or y = −5.","One input with two outputs. Is that a function?"]},{"id": "AlgI.16-03","std": "Alg I.16","q": "Table x: 1, 2, 3, 1 and y: 5, 6, 7, 8. Function or not?","a": "Not a function (x = 1 has two outputs)","lvl": 1,"also": ["no","not a function"],"steps": ["Look for an x that shows up twice.","x = 1 goes with y = 5 and y = 8. Is that allowed in a function?"]},{"id": "AlgI.16-04","std": "Alg I.16","q": "Is y = |x| a function?","a": "Yes","lvl": 1,"choices": ["Yes","No"],"steps": ["Put any x in. |x| gives one value.","Does any x give two outputs?"]},{"id": "AlgI.16-05","std": "Alg I.16","q": "Is x = 4 (a vertical line) a function?","a": "No","lvl": 2,"choices": ["Yes","No"],"steps": ["On x = 4 the points are (4, 0), (4, 1), (4, 2) and so on.","One input with many outputs. Use the vertical line test."]},{"id": "AlgI.16-06","std": "Alg I.16","q": "Every function is a relation. Is every relation a function?","a": "No","lvl": 1,"choices": ["Yes","No"],"steps": ["A relation is any set of pairs. A function has one output for each input.","Can a relation have one input with two outputs? Is that a function?"]},{"id": "AlgI.16-07","std": "Alg I.16","q": "Is y² = x a function of x?","a": "No","lvl": 3,"choices": ["Yes","No"],"steps": ["Try x = 4: y² = 4, so y = 2 or y = −2.","One input with two outputs. Is that a function?"]},{"id": "AlgI.17-01","std": "Alg I.17","q": "f(x) = 2x + 3 and g(x) = x². Find (f + g)(2).","a": "11","lvl": 1,"part": "a","steps": ["(f + g)(2) = f(2) + g(2).","f(2) = 2(2) + 3 and g(2) = 2². Add them."]},{"id": "AlgI.17-02","std": "Alg I.17","q": "f(x) = 2x + 3 and g(x) = x². Find (f − g)(3).","a": "0","lvl": 2,"part": "a","steps": ["(f − g)(3) = f(3) − g(3).","f(3) = 2(3) + 3 and g(3) = 3². Subtract."]},{"id": "AlgI.17-03","std": "Alg I.17","q": "f(x) = 2x + 3 and g(x) = x². Find f(g(2)).","a": "11","lvl": 2,"part": "b","steps": ["Work from the inside out. g(2) = 2² = 4.","Now find f(4) = 2(4) + 3."]},{"id": "AlgI.17-04","std": "Alg I.17","q": "f(x) = 2x + 3 and g(x) = x². Find g(f(2)).","a": "49","lvl": 2,"part": "b","steps": ["Work from the inside out. f(2) = 2(2) + 3 = 7.","Now find g(7) = 7²."]},{"id": "AlgI.17-05","std": "Alg I.17","q": "Water flows in at 5 gal per min: I(t) = 5t. It evaporates at 0.5 gal per min: E(t) = 0.5t. Write W(t) for the water in the tank.","a": "W(t) = 4.5t","lvl": 2,"part": "a","steps": ["Water in the tank = water in − water out.","W(t) = 5t − 0.5t. Combine like terms."]},{"id": "AlgI.17-06","std": "Alg I.17","q": "T(h) = 70 + 2h gives temperature after h hours. S(T) = 3T − 50 gives sales at temperature T. Find S(T(5)).","a": "190","lvl": 3,"part": "b","steps": ["Inside first: T(5) = 70 + 2(5) = 80.","Now find S(80) = 3(80) − 50."]},{"id": "AlgI.17-07","std": "Alg I.17","q": "f(x) = x − 4 and g(x) = 3x. Write f(g(x)).","a": "3x − 4","lvl": 2,"part": "b","steps": ["f(g(x)) means g(x) goes into f.","f takes 4 away from whatever goes in. Here 3x goes in."]},{"id": "AlgI.17-08","std": "Alg I.17","q": "f(x) = x + 1 and g(x) = x − 1. Find f(x) · g(x).","a": "x² − 1","lvl": 2,"part": "a","steps": ["Multiply: (x + 1)(x − 1).","That's x² − x + x − 1. Combine the middle terms."]},{"id": "AlgI.18-01","std": "Alg I.18","q": "Solve: y = x² and y = x + 2","a": "(2, 4) and (−1, 1)","lvl": 2,"steps": ["Both equal y, so set them equal: x² = x + 2.","Move it all to one side: x² − x − 2 = 0. Factor: (x − 2)(x + 1) = 0.","Find each x, then find y with y = x + 2."]},{"id": "AlgI.18-02","std": "Alg I.18","q": "Solve: y = x² − 1 and y = 3","a": "(2, 3) and (−2, 3)","lvl": 1,"steps": ["Set them equal: x² − 1 = 3.","Add 1: x² = 4. Take the square root, ±.","Write both points. y is 3 for both."]},{"id": "AlgI.18-03","std": "Alg I.18","q": "How many solutions can a system of a line and a parabola have?","a": "0, 1 or 2","lvl": 1,"also": ["0, 1, or 2"],"steps": ["Sketch a parabola and a line. Can the line miss it?","Can it touch at one point? Cross at two? Can it ever cross at three?"]},{"id": "AlgI.18-04","std": "Alg I.18","q": "Solve: y = x² + 1 and y = 2x","a": "(1, 2)","lvl": 3,"steps": ["Set them equal: x² + 1 = 2x.","Move it all to one side: x² − 2x + 1 = 0. That's (x − 1)² = 0.","Find x, then y = 2x."]},{"id": "AlgI.18-05","std": "Alg I.18","q": "Does y = x² + 3 meet y = 1?","a": "No (x² + 3 is always at least 3)","lvl": 2,"also": ["no"],"steps": ["x² is never negative, so x² + 3 is always at least 3.","Can it ever equal 1?"]},{"id": "AlgI.18-06","std": "Alg I.18","q": "Solve: y = x² − 4x and y = −4","a": "(2, −4)","lvl": 2,"steps": ["Set them equal: x² − 4x = −4.","Add 4: x² − 4x + 4 = 0. That's (x − 2)² = 0.","Find x. y is −4."]},{"id": "AlgI.19-01","std": "Alg I.19","q": "The graphs of y = 2x + 1 and y = 7 cross at x = 3. What does x = 3 solve?","a": "2x + 1 = 7","lvl": 1,"steps": ["Where the graphs cross, both have the same y.","So 2x + 1 equals what? Write that equation."]},{"id": "AlgI.19-02","std": "Alg I.19","q": "Use a table: for which whole x is 2^x = x + 2? Try x = 0, 1, 2, 3.","a": "x = 2","lvl": 2,"steps": ["Try each x. x = 0: 2⁰ = 1 and 0 + 2 = 2. Not equal.","x = 1: 2¹ = 2 and 1 + 2 = 3. Not equal.","Keep going with x = 2 and x = 3. Where are they equal?"]},{"id": "AlgI.19-03","std": "Alg I.19","q": "f(x) = x² and g(x) = 9. Where do the graphs meet? What equation does that solve?","a": "x = 3 and x = −3; x² = 9","lvl": 2,"also": ["±3"],"steps": ["They meet where x² = 9.","What numbers squared are 9? There are two."]},{"id": "AlgI.19-04","std": "Alg I.19","q": "Graphs of y = |x − 1| and y = 3 cross at what x-values?","a": "x = 4 and x = −2","lvl": 2,"also": ["4, −2"],"steps": ["Set |x − 1| = 3. So x − 1 = 3 or x − 1 = −3.","Add 1 to each."]},{"id": "AlgI.19-05","std": "Alg I.19","q": "Why are the x-coordinates where y = f(x) and y = g(x) cross the solutions of f(x) = g(x)?","a": "At those x-values the two outputs are equal","lvl": 2,"steps": ["Where the graphs cross, the points have the same x and the same y.","Same y means f(x) and g(x) are what?"]},{"id": "AlgI.19-06","std": "Alg I.19","q": "Estimate the solution to 2^x = 5 between two whole numbers.","a": "Between 2 and 3","lvl": 3,"also": ["2 and 3"],"steps": ["Try whole numbers: 2² = 4 and 2³ = 8.","5 is between 4 and 8. So x is between which two numbers?"]},{"id": "AlgI.20-01","std": "Alg I.20","q": "Is (1, 1) a solution of y > 2x − 3?","a": "Yes (1 > −1)","lvl": 1,"also": ["yes"],"steps": ["Put (1, 1) in: is 1 > 2(1) − 3?","2(1) − 3 = −1. Is 1 > −1?"]},{"id": "AlgI.20-02","std": "Alg I.20","q": "For y < x + 2, is the boundary line solid or dashed?","a": "Dashed","lvl": 1,"choices": ["Solid","Dashed"],"steps": ["Solid means points on the line count. Dashed means they don't.","Does < include the line?"]},{"id": "AlgI.20-03","std": "Alg I.20","q": "For y ≥ −x + 4, do you shade above or below the line?","a": "Above","lvl": 1,"choices": ["Above","Below"],"steps": ["y ≥ means y is bigger than the line.","Bigger y values are higher up. Above or below?"]},{"id": "AlgI.20-04","std": "Alg I.20","q": "Is (0, 0) a solution of 3x + 2y ≥ 6?","a": "No","lvl": 2,"choices": ["Yes","No"],"steps": ["Put (0, 0) in: 3(0) + 2(0) ≥ 6.","Is 0 ≥ 6?"]},{"id": "AlgI.20-05","std": "Alg I.20","q": "Is (2, 3) in the solution of y > x and y < 5?","a": "Yes","lvl": 2,"choices": ["Yes","No"],"steps": ["Check y > x: is 3 > 2?","Check y < 5: is 3 < 5? Both have to be true."]},{"id": "AlgI.20-06","std": "Alg I.20","q": "Write the inequality: boundary y = 2x + 1, dashed, shaded below.","a": "y < 2x + 1","lvl": 2,"steps": ["Dashed means < or >, not ≤ or ≥.","Shaded below means y is less than the line."]},{"id": "AlgI.20-07","std": "Alg I.20","q": "Is (4, 0) a solution of x + y ≤ 3 and y ≥ 0?","a": "No (4 + 0 is more than 3)","lvl": 2,"also": ["no"],"steps": ["Check x + y ≤ 3: 4 + 0 = 4. Is 4 ≤ 3?","Both have to be true. Is it?"]},{"id": "AlgI.21-01","std": "Alg I.21","q": "f(x) = x² + 3. g has a minimum of 1 on its graph. Which has the smaller minimum?","a": "g","lvl": 2,"steps": ["x² is at least 0, so the minimum of f(x) = x² + 3 is 3.","g's minimum is 1. Which is smaller?"]},{"id": "AlgI.21-02","std": "Alg I.21","q": "f(x) = 2(3)^x. Table for g: x 0, 1, 2 and y 2, 5, 8. Which grows faster as x increases?","a": "f","lvl": 2,"also": ["f(x)"],"steps": ["f: 2, 6, 18. It multiplies by 3 each time.","g: 2, 5, 8. It adds 3 each time. Which grows faster as x gets big?"]},{"id": "AlgI.21-03","std": "Alg I.21","q": "f(x) = −(x − 2)² + 6. g(x) has a maximum of 9. Which has the greater maximum?","a": "g","lvl": 2,"steps": ["−(x − 2)² is never more than 0, so f's maximum is 6.","g's maximum is 9. Which is greater?"]},{"id": "AlgI.21-04","std": "Alg I.21","q": "f(x) = |x| + 1 and g(x) = 2x + 1. What is the same about them at x = 0?","a": "Both equal 1 (same y-intercept)","lvl": 1,"also": ["1"],"steps": ["Find f(0) = |0| + 1 and g(0) = 2(0) + 1.","Both are the same number. Where on the graph is x = 0?"]},{"id": "AlgI.21-05","std": "Alg I.21","q": "f(x) = 3x + 2. g goes through (0, 4) and (2, 8). Which has the greater slope?","a": "f (3 vs 2)","lvl": 1,"also": ["f"],"steps": ["f(x) = 3x + 2 has slope 3.","g's slope is {8 − 4/2 − 0}. Find it and compare."]},{"id": "AlgI.21-06","std": "Alg I.21","q": "f(x) = x² − 4 has zeros at ±2. g(x) = (x − 1)(x + 5). Which has the zero farther from 0?","a": "g (at x = −5)","lvl": 2,"also": ["g"],"steps": ["f has zeros at 2 and −2.","For g, set x − 1 = 0 and x + 5 = 0. Its zeros are 1 and −5.","Which zero is the farthest from 0?"]},{"id": "AlgI.22-01","std": "Alg I.22","q": "Find the next term: 3, 7, 11, 15, …","a": "19","lvl": 1,"part": "a","steps": ["Find the difference: 7 − 3 = 4 and 11 − 7 = 4.","Add 4 to the last term."]},{"id": "AlgI.22-02","std": "Alg I.22","q": "Write an explicit formula: 3, 7, 11, 15, …","a": "aₙ = 4n − 1","lvl": 2,"part": "a","also": ["4n − 1"],"steps": ["It starts at 3 and adds 4 each time.","aₙ = 3 + 4(n − 1). Distribute and combine."]},{"id": "AlgI.22-03","std": "Alg I.22","q": "Find the next term: 2, 6, 18, 54, …","a": "162","lvl": 1,"part": "a","steps": ["Divide: 6 ÷ 2 = 3 and 18 ÷ 6 = 3. It multiplies by 3.","Multiply the last term by 3."]},{"id": "AlgI.22-04","std": "Alg I.22","q": "Write an explicit formula: 2, 6, 18, 54, …","a": "aₙ = 2(3)^{n − 1}","lvl": 2,"part": "a","also": ["2(3)^(n−1)","2·3^(n−1)"],"steps": ["It starts at 2 and multiplies by 3 each time.","Use aₙ = a₁ · r^{n − 1}. Put in a₁ = 2 and r = 3."]},{"id": "AlgI.22-05","std": "Alg I.22","q": "Write a recursive formula: 5, 8, 11, 14, …","a": "a₁ = 5, aₙ = aₙ₋₁ + 3","lvl": 2,"part": "a","also": ["a_n = a_(n−1) + 3"],"steps": ["A recursive formula gives the first term, then how to get each term from the one before.","The first term is 5. Each term adds 3 to aₙ₋₁."]},{"id": "AlgI.22-06","std": "Alg I.22","q": "Write a recursive formula: 80, 40, 20, 10, …","a": "a₁ = 80, aₙ = {1/2}aₙ₋₁","lvl": 2,"part": "a","also": ["a_n = 0.5a_(n−1)"],"steps": ["40 ÷ 80 = {1/2}. Each term is half of the one before.","The first term is 80. Each term is {1/2} times aₙ₋₁."]},{"id": "AlgI.22-07","std": "Alg I.22","q": "Find the 20th term of 3, 7, 11, 15, …","a": "79","lvl": 3,"part": "a","steps": ["It starts at 3 and adds 4, so aₙ = 4n − 1.","Put in n = 20: 4(20) − 1."]},{"id": "AlgI.22-08","std": "Alg I.22","q": "Is an arithmetic sequence linear or exponential?","a": "Linear","lvl": 1,"part": "a","choices": ["Linear","Exponential"],"steps": ["An arithmetic sequence adds the same amount each time.","Adding the same amount makes a straight line. Linear or exponential?"]},{"id": "AlgI.22-09","std": "Alg I.22","q": "What is the domain of a sequence?","a": "Whole numbers 1, 2, 3, … (a subset of the integers)","lvl": 2,"steps": ["A sequence has a 1st term, a 2nd term, a 3rd term and so on.","What kind of numbers count the terms?"]},{"id": "AlgI.23-01","std": "Alg I.23","q": "How does y = x² + 5 compare to y = x²?","a": "It shifts up 5","lvl": 1,"also": ["up 5"],"steps": ["Adding outside the x² moves the graph up or down.","+5 moves it which way, and how far?"]},{"id": "AlgI.23-02","std": "Alg I.23","q": "How does y = (x − 3)² compare to y = x²?","a": "It shifts right 3","lvl": 1,"also": ["right 3"],"steps": ["A change inside with x moves the graph left or right.","Where is x − 3 = 0? That's where the vertex moves to."]},{"id": "AlgI.23-03","std": "Alg I.23","q": "How does y = |x + 4| compare to y = |x|?","a": "It shifts left 4","lvl": 1,"also": ["left 4"],"steps": ["A change inside with x moves the graph left or right.","Where is x + 4 = 0? That's where the vertex moves to."]},{"id": "AlgI.23-04","std": "Alg I.23","q": "How does y = 3x² compare to y = x²?","a": "It is a vertical stretch by 3 (narrower)","lvl": 2,"also": ["stretch","narrower"],"steps": ["Multiplying by 3 makes every y value 3 times as big.","Does that make the graph narrower or wider?"]},{"id": "AlgI.23-05","std": "Alg I.23","q": "How does y = −x² compare to y = x²?","a": "It is reflected over the x-axis","lvl": 2,"also": ["reflection over the x-axis","flipped"],"steps": ["The minus sign makes every y value the opposite.","Points above the x-axis flip below it. What is that move called?"]},{"id": "AlgI.23-06","std": "Alg I.23","q": "f(x) = x². g(x) is the graph shifted down 2 and right 1. Write g(x).","a": "g(x) = (x − 1)² − 2","lvl": 2,"steps": ["Right 1: replace x with x − 1, so (x − 1)².","Down 2: subtract 2 at the end."]},{"id": "AlgI.23-07","std": "Alg I.23","q": "g(x) = f(x) + k. g is f moved down 6. Find k.","a": "k = −6","lvl": 1,"steps": ["Adding k moves the graph up or down.","Down 6 means k is what?"]},{"id": "AlgI.23-08","std": "Alg I.23","q": "f(x) = 2^x. What is g(x) = 2^x − 3?","a": "f shifted down 3","lvl": 2,"also": ["down 3"],"steps": ["The − 3 is outside the 2^{x}.","Subtracting outside moves the graph which way, and how far?"]},{"id": "AlgI.23-09","std": "Alg I.23","q": "How does y = {1/2}|x| compare to y = |x|?","a": "Vertical shrink by {1/2} (wider)","lvl": 2,"also": ["wider","shrink"],"steps": ["Multiplying by {1/2} makes every y value half as big.","Does that make the graph narrower or wider?"]},{"id": "AlgI.24-01","std": "Alg I.24","q": "A table goes 4, 8, 12, 16. Linear or exponential?","a": "Linear (adds 4)","lvl": 1,"part": "a","also": ["linear"],"steps": ["Find the change: 8 − 4, 12 − 8, 16 − 12.","Adding the same each time is linear. Multiplying the same each time is exponential."]},{"id": "AlgI.24-02","std": "Alg I.24","q": "A table goes 4, 8, 16, 32. Linear or exponential?","a": "Exponential (times 2)","lvl": 1,"part": "a","also": ["exponential"],"steps": ["Is it adding the same amount, or multiplying by the same number?","8 ÷ 4 = 2 and 16 ÷ 8 = 2. What kind of growth is that?"]},{"id": "AlgI.24-03","std": "Alg I.24","q": "A town grows by 300 people each year. Linear or exponential?","a": "Linear","lvl": 1,"part": "b","choices": ["Linear","Exponential"],"steps": ["It grows by 300 each year: the same amount added.","Adding the same amount: linear or exponential?"]},{"id": "AlgI.24-04","std": "Alg I.24","q": "A town grows by 3% each year. Linear or exponential?","a": "Exponential","lvl": 1,"part": "c","choices": ["Linear","Exponential"],"steps": ["It grows by 3% each year: times 1.03 each time.","Multiplying by the same number: linear or exponential?"]},{"id": "AlgI.24-05","std": "Alg I.24","q": "Write a function: you start with §50 and add §15 a week.","a": "y = 15x + 50","lvl": 2,"part": "b","steps": ["It starts at 50 and adds 15 each week.","Linear: y = (rate)x + (start)."]},{"id": "AlgI.24-06","std": "Alg I.24","q": "Write a function: a §900 laptop loses 20% of its value each year.","a": "y = 900(0.8)^x","lvl": 2,"part": "c","steps": ["Losing 20% means you keep 80%: 1 − 0.2 = 0.8.","Exponential: y = (start)(factor)^{x}."]},{"id": "AlgI.24-07","std": "Alg I.24","q": "Bacteria start at 100 and triple every hour. Write a function.","a": "y = 100(3)^x","lvl": 2,"part": "c","steps": ["It starts at 100. Tripling means times 3 each hour.","Exponential: y = (start)(factor)^{x}."]},{"id": "AlgI.24-08","std": "Alg I.24","q": "Over equal intervals, an exponential function grows by equal ___.","a": "Factors","lvl": 2,"part": "a","choices": ["Differences","Factors"],"steps": ["Linear adds the same amount each time: equal differences.","Exponential multiplies by the same number each time. What is that called?"]},{"id": "AlgI.25-01","std": "Alg I.25","q": "Write the linear function through (0, 2) and (3, 14).","a": "y = 4x + 2","lvl": 1,"steps": ["Slope = {14 − 2/3 − 0} = {12/3}.","(0, 2) is the y-intercept. Write y = mx + b."]},{"id": "AlgI.25-02","std": "Alg I.25","q": "Write the exponential function through (0, 5) and (1, 15).","a": "y = 5(3)^x","lvl": 1,"steps": ["At x = 0, y = 5. That's the start, a.","From x = 0 to 1, y goes from 5 to 15: times 3. Write y = a(b)^{x}."]},{"id": "AlgI.25-03","std": "Alg I.25","q": "Write the exponential function through (0, 64) and (2, 16).","a": "y = 64({1/2})^x","lvl": 2,"also": ["y = 64(0.5)^x"],"steps": ["At x = 0, y = 64. That's the start, a.","From x = 0 to 2, y goes from 64 to 16. That's times {1/4} over 2 steps.","Each step multiplies by b, and b × b = {1/4}. Find b."]},{"id": "AlgI.25-04","std": "Alg I.25","q": "Write the linear function through (2, 9) and (6, 21).","a": "y = 3x + 3","lvl": 2,"steps": ["Slope = {21 − 9/6 − 2} = {12/4}.","Use y = mx + b with (2, 9): 9 = 3(2) + b. Solve for b."]},{"id": "AlgI.25-05","std": "Alg I.25","q": "Write the exponential function through (1, 6) and (2, 18).","a": "y = 2(3)^x","lvl": 3,"steps": ["From x = 1 to 2, y goes from 6 to 18: times 3. So b = 3.","Work back to x = 0: 6 ÷ 3 is the start, a. Write y = a(b)^{x}."]},{"id": "AlgI.25-06","std": "Alg I.25","q": "A table: x 0, 1, 2, 3 and y 3, 6, 12, 24. Write the function.","a": "y = 3(2)^x","lvl": 2,"steps": ["At x = 0, y = 3. That's the start.","Each y doubles: 3, 6, 12, 24. Write y = a(b)^{x}."]},{"id": "AlgI.25-07","std": "Alg I.25","q": "A table: x 0, 1, 2, 3 and y 10, 7, 4, 1. Write the function.","a": "y = −3x + 10","lvl": 2,"steps": ["At x = 0, y = 10. That's the start.","Each y goes down 3: 10, 7, 4, 1. Write y = mx + b."]},{"id": "AlgI.26-01","std": "Alg I.26","q": "Compare y = 2^x and y = 10x at x = 6.","a": "2^6 = 64 vs 10(6) = 60, so 2^x is bigger","lvl": 2,"also": ["2^x"],"steps": ["2⁶ = 2 × 2 × 2 × 2 × 2 × 2.","10x at x = 6 is 10 × 6. Compare the two."]},{"id": "AlgI.26-02","std": "Alg I.26","q": "At x = 5, which is bigger: y = 2^x or y = 10x?","a": "10x (50 vs 32)","lvl": 1,"also": ["10x"],"steps": ["2⁵ = 2 × 2 × 2 × 2 × 2 = 32.","Find 10(5) and compare."]},{"id": "AlgI.26-03","std": "Alg I.26","q": "Which eventually grows larger: y = 100x or y = 1.1^x?","a": "y = 1.1^x","lvl": 2,"also": ["1.1^x","exponential"],"steps": ["Exponential growth multiplies. Linear growth adds the same amount.","Over a long time, which one wins, even if it starts slower?"]},{"id": "AlgI.26-04","std": "Alg I.26","q": "Which is larger at x = 10: y = x² or y = 2^x?","a": "2^x (1,024 vs 100)","lvl": 2,"also": ["2^x"],"steps": ["x² at x = 10 is 10 × 10.","Find 2¹⁰ by doubling 2 ten times. Compare."]},{"id": "AlgI.26-05","std": "Alg I.26","q": "Job A pays §1,000 a day. Job B pays 1 cent on day 1 and doubles each day. On which day does Job B's daily pay first pass Job A's?","a": "Day 18","lvl": 3,"also": ["18"],"steps": ["On day n, Job B pays 0.01 × 2^{n − 1} dollars.","You need 2^{n − 1} to pass 100,000. Try 2¹⁶ = 65,536 and 2¹⁷ = 131,072.","Which power passes 100,000? Then add 1 to get the day."]},{"id": "AlgI.26-06","std": "Alg I.26","q": "Can a linear function with a large slope stay above an increasing exponential function forever?","a": "No","lvl": 1,"choices": ["Yes","No"],"steps": ["An exponential multiplies each step. A line only adds.","Eventually, does multiplying always beat adding?"]},{"id": "AlgI.27-01","std": "Alg I.27","q": "In y = 25x + 150, where y is total savings after x weeks, what does 150 mean?","a": "§150 saved at the start","lvl": 1,"also": ["starting amount"],"steps": ["Put x = 0 for week 0: y = 25(0) + 150.","So 150 is the savings when?"]},{"id": "AlgI.27-02","std": "Alg I.27","q": "In y = 25x + 150 (savings), what does 25 mean?","a": "§25 saved each week","lvl": 1,"steps": ["25 is multiplied by x, the number of weeks.","So each week adds how much?"]},{"id": "AlgI.27-03","std": "Alg I.27","q": "In y = 3,000(1.04)^t for a town's population, what does 1.04 mean?","a": "The population grows 4% each year","lvl": 1,"also": ["4% growth"],"steps": ["1.04 = 1 + 0.04. It's the growth factor each year.","Write 0.04 as a percent."]},{"id": "AlgI.27-04","std": "Alg I.27","q": "In y = 3,000(1.04)^t, what does 3,000 mean?","a": "The starting population","lvl": 1,"steps": ["Put t = 0: 3,000(1.04)⁰ = 3,000 × 1.","So 3,000 is the population when?"]},{"id": "AlgI.27-05","std": "Alg I.27","q": "In y = 80(0.9)^t for a medicine in the body (mg), what percent leaves each hour?","a": "10%","lvl": 2,"also": ["10"],"steps": ["0.9 means 90% stays each hour.","What percent leaves? 100% − 90%."]},{"id": "AlgI.27-06","std": "Alg I.27","q": "In y = −12x + 300 for fuel in a tank, what does −12 mean?","a": "The tank loses 12 units of fuel each hour (or each unit of x)","lvl": 2,"steps": ["−12 is multiplied by x. It's the rate of change.","Negative means the fuel goes down. By how much for each unit of x?"]},{"id": "AlgI.28-01","std": "Alg I.28","q": "y = −(x − 4)² + 9. What is the maximum?","a": "9","lvl": 1,"steps": ["−(x − 4)² is never more than 0.","So the biggest y can be is 0 + 9. That happens when x = 4."]},{"id": "AlgI.28-02","std": "Alg I.28","q": "y = (x − 1)(x − 5). What are the x-intercepts?","a": "x = 1 and x = 5","lvl": 1,"also": ["1, 5","(1, 0) and (5, 0)"],"steps": ["x-intercepts are where y = 0: (x − 1)(x − 5) = 0.","Set each factor equal to 0."]},{"id": "AlgI.28-03","std": "Alg I.28","q": "y = x² − 6x + 8. What is the y-intercept?","a": "(0, 8)","lvl": 1,"also": ["8"],"steps": ["The y-intercept is where x = 0.","Put x = 0 in: 0² − 6(0) + 8. Write it as a point."]},{"id": "AlgI.28-04","std": "Alg I.28","q": "y = (x − 3)² − 4. On what interval is it decreasing?","a": "x < 3","lvl": 2,"steps": ["The vertex is (3, −4) and the graph opens up.","It goes down until it reaches the vertex. Which x-values are left of 3?"]},{"id": "AlgI.28-05","std": "Alg I.28","q": "y = 2^x. What happens as x gets very negative?","a": "y gets close to 0","lvl": 2,"also": ["approaches 0"],"steps": ["Try x = −1, −2, −3: 2^{−1} = {1/2}, 2^{−2} = {1/4}, 2^{−3} = {1/8}.","The values get smaller but stay positive. What do they get close to?"]},{"id": "AlgI.28-06","std": "Alg I.28","q": "A ball's height h(t) = −16t² + 32t + 48. When is it highest, and how high?","a": "At t = 1 s, 64 ft","lvl": 3,"also": ["(1, 64)"],"steps": ["The top is at the vertex: t = {−b/2a} = {−32/2(−16)}.","That gives t = 1. Put it in: h(1) = −16 + 32 + 48."]},{"id": "AlgI.28-07","std": "Alg I.28","q": "Where is y = |x + 2| − 3 at its minimum?","a": "(−2, −3)","lvl": 2,"steps": ["|x + 2| is smallest, 0, when x = −2.","Then y = 0 − 3. Write the point."]},{"id": "AlgI.28-08","std": "Alg I.28","q": "y = −2x + 6. Where is it positive?","a": "x < 3","lvl": 2,"steps": ["Positive means y > 0: −2x + 6 > 0.","Subtract 6: −2x > −6. Divide by −2 and flip the sign."]},{"id": "AlgI.29-01","std": "Alg I.29","q": "f(x) = x². Find the average rate of change from x = 1 to x = 4.","a": "5","lvl": 1,"steps": ["Average rate of change = {f(4) − f(1)/4 − 1}.","f(4) = 16 and f(1) = 1. Subtract the tops, subtract the bottoms, then divide."]},{"id": "AlgI.29-02","std": "Alg I.29","q": "f(x) = 2^x. Find the average rate of change from x = 0 to x = 3.","a": "2{1/3}","lvl": 2,"also": ["2.33"],"steps": ["Average rate of change = {f(3) − f(0)/3 − 0}.","f(3) = 2³ = 8 and f(0) = 2⁰ = 1.","Subtract, divide by 3, and write it as a mixed number."]},{"id": "AlgI.29-03","std": "Alg I.29","q": "A car is 30 miles away at 1 h and 150 miles away at 3 h. What is its average rate of change?","a": "60 miles per hour","lvl": 1,"also": ["60"],"steps": ["Rate = {change in distance/change in time}.","That's {150 − 30/3 − 1}. Find the top and bottom, then divide."]},{"id": "AlgI.29-04","std": "Alg I.29","q": "f(x) = |x|. Find the average rate of change from x = −4 to x = 2.","a": "−{1/3}","lvl": 2,"steps": ["Average rate of change = {f(2) − f(−4)/2 − (−4)}.","f(2) = |2| = 2 and f(−4) = |−4| = 4.","Top: 2 − 4. Bottom: 2 + 4. Divide and simplify."]},{"id": "AlgI.29-05","std": "Alg I.29","q": "Table: x 0, 2, 4 and y 5, 13, 37. Find the average rate of change from 2 to 4.","a": "12","lvl": 2,"steps": ["Average rate of change = {37 − 13/4 − 2}.","Find the top and bottom, then divide."]},{"id": "AlgI.29-06","std": "Alg I.29","q": "f(x) = −x² + 10. Find the average rate of change from x = 0 to x = 3.","a": "−3","lvl": 2,"steps": ["Average rate of change = {f(3) − f(0)/3 − 0}.","f(3) = −9 + 10 = 1 and f(0) = 10.","Subtract, then divide by 3."]},{"id": "AlgI.29-07","std": "Alg I.29","q": "h(t) = −16t² + 64t. Find the average rate of change from t = 1 to t = 3.","a": "0","lvl": 3,"steps": ["h(1) = −16 + 64 = 48 and h(3) = −144 + 192 = 48.","Average rate of change = {48 − 48/3 − 1}."]},{"id": "AlgI.30-01","std": "Alg I.30","q": "Graph y = x² − 4. What are the x-intercepts and the minimum?","a": "x = ±2; minimum (0, −4)","lvl": 2,"part": "a","also": ["±2"],"steps": ["x-intercepts: set x² − 4 = 0, so x² = 4.","Take the square root, ±.","The lowest point is at x = 0. Find y there."]},{"id": "AlgI.30-02","std": "Alg I.30","q": "y = −x² + 2x + 3. Find the vertex.","a": "(1, 4)","lvl": 2,"part": "a","steps": ["The vertex is at x = {−b/2a} = {−2/2(−1)}.","That's x = 1. Put it in: y = −1 + 2 + 3."]},{"id": "AlgI.30-03","std": "Alg I.30","q": "Find the x- and y-intercepts of y = 3x − 6.","a": "x-intercept (2, 0), y-intercept (0, −6)","lvl": 1,"part": "a","steps": ["x-intercept: set y = 0. Solve 0 = 3x − 6.","y-intercept: set x = 0. Find y = 3(0) − 6. Write both as points."]},{"id": "AlgI.30-04","std": "Alg I.30","q": "y = |x − 2| + 1. Where is the vertex?","a": "(2, 1)","lvl": 1,"part": "b","steps": ["|x − 2| is smallest, 0, when x = 2.","Then y = 0 + 1. Write the point."]},{"id": "AlgI.30-05","std": "Alg I.30","q": "A step function: parking costs §5 for each hour or part of an hour. What do 2.5 hours cost?","a": "§15","lvl": 2,"part": "b","also": ["15"],"steps": ["Part of an hour counts as a whole hour, so 2.5 hours counts as 3 hours.","Each hour is §5. Multiply."]},{"id": "AlgI.30-06","std": "Alg I.30","q": "f(x) = x + 1 when x < 0, and f(x) = 2x when x ≥ 0. Find f(−3) and f(3).","a": "f(−3) = −2, f(3) = 6","lvl": 2,"part": "b","also": ["−2 and 6"],"steps": ["−3 < 0, so use x + 1: f(−3) = −3 + 1.","3 ≥ 0, so use 2x: f(3) = 2(3)."]},{"id": "AlgI.30-07","std": "Alg I.30","q": "y = 3(2)^x. What is the y-intercept?","a": "(0, 3)","lvl": 1,"part": "c","also": ["3"],"steps": ["The y-intercept is at x = 0: y = 3(2)⁰.","Anything to the 0 power is 1. Write the point."]},{"id": "AlgI.30-08","std": "Alg I.30","q": "y = 5({1/2})^x. As x gets large, what happens to y?","a": "y gets close to 0","lvl": 2,"part": "c","also": ["approaches 0"],"steps": ["Try x = 1, 2, 3: y = 2.5, then 1.25, then 0.625.","y keeps halving but stays positive. What does it get close to?"]},{"id": "AlgI.30-09","std": "Alg I.30","q": "Does y = 4(3)^x have an x-intercept?","a": "No (y is always positive)","lvl": 2,"part": "c","also": ["no"],"steps": ["An x-intercept needs y = 0: 4(3)^{x} = 0.","3^{x} is always positive. Can 4 times a positive number be 0?"]},{"id": "AlgI.31-01","std": "Alg I.31","q": "A rocket's height is h = −16t² + 96t. When does it land?","a": "6 seconds","lvl": 2,"also": ["6","t = 6"],"steps": ["It lands when h = 0: −16t² + 96t = 0.","Factor: −16t(t − 6) = 0. Set each factor to 0.","t = 0 is the launch. What's the other time?"]},{"id": "AlgI.31-02","std": "Alg I.31","q": "You invest §2,000 at 5% growing yearly. Write a model and find the value after 3 years.","a": "y = 2,000(1.05)^t; §2,315.25","lvl": 3,"also": ["§2,315.25","2315.25"],"steps": ["Growing 5% means times 1.05 each year: y = 2,000(1.05)^{t}.","Put t = 3: 1.05³ = 1.157625.","Multiply by 2,000 and round to the cent."]},{"id": "AlgI.31-03","std": "Alg I.31","q": "A gym costs §30 to join and §20 a month. You have §190. Model it and find the months you can pay for.","a": "30 + 20m ≤ 190, 8 months","lvl": 2,"also": ["8"],"steps": ["Join fee plus months: 30 + 20m ≤ 190.","Subtract 30: 20m ≤ 160. Divide by 20."]},{"id": "AlgI.31-04","std": "Alg I.31","q": "A model predicts 1,250.6 people at a game. What should you report?","a": "About 1,251 people (whole people)","lvl": 1,"also": ["1251","1,251"],"steps": ["Can you have 0.6 of a person?","Round to a whole number of people."]},{"id": "AlgI.31-05","std": "Alg I.31","q": "After using a model to predict, what is the next step of the modeling cycle?","a": "Check whether the answer makes sense in the situation and revise if needed","lvl": 2,"also": ["validate","check"],"steps": ["The cycle: make a model, compute, then interpret.","Once you have an answer, what should you check before you report it?"]},{"id": "AlgI.31-06","std": "Alg I.31","q": "A fence costs §12 a foot. A square pen has area 144 ft². How much does the fence cost?","a": "§576","lvl": 3,"also": ["576"],"steps": ["Area of a square = side². side² = 144, so the side is √144 = 12 ft.","The fence goes all the way around: 4 × 12 feet.","Multiply the feet by §12 a foot."]},{"id": "AlgI.32-01","std": "Alg I.32","q": "Of 200 drivers, 40 texted while driving and 12 of them had a crash. 160 did not text and 8 had a crash. Find the crash rate for texters.","a": "30%","lvl": 2,"also": ["0.3","30"],"steps": ["Crash rate for texters = crashes ÷ texters = {12/40}.","Change it to a percent."]},{"id": "AlgI.32-02","std": "Alg I.32","q": "Using the data above, find the crash rate for non-texters.","a": "5%","lvl": 2,"also": ["0.05","5"],"steps": ["Crash rate for non-texters = {8/160}.","Change it to a percent."]},{"id": "AlgI.32-03","std": "Alg I.32","q": "Using the data above, how many times as likely is a crash for texters?","a": "6 times","lvl": 3,"also": ["6"],"steps": ["Texters: 30%. Non-texters: 5%.","How many times as big is 30% as 5%? Divide."]},{"id": "AlgI.32-04","std": "Alg I.32","q": "Of 100 students who sleep less than 7 hours, 45 are often tired. Of 100 who sleep more, 15 are. Does sleep seem related to being tired?","a": "Yes (45% vs 15%)","lvl": 2,"also": ["yes"],"steps": ["Less sleep: 45 of 100 are tired, 45%. More sleep: 15 of 100, 15%.","When the rates are very different, the variables seem related. Are they?"]},{"id": "AlgI.32-05","std": "Alg I.32","q": "Does an association in a two-way table prove that one thing causes the other?","a": "No","lvl": 1,"choices": ["Yes","No"],"steps": ["An association means two things happen together.","Could something else cause both? Does that prove one causes the other?"]},{"id": "AlgI.32-06","std": "Alg I.32","q": "A vaccine group of 500 had 10 sick; a no-vaccine group of 500 had 50 sick. Which group had the lower risk?","a": "The vaccine group (2% vs 10%)","lvl": 2,"also": ["vaccine"],"steps": ["Vaccine: {10/500} = 2%. No vaccine: {50/500}.","Which percent is lower?"]},{"id": "AlgI.33-01","std": "Alg I.33","q": "You want to know if 8th graders who play sports prefer outdoor lunch. Name the two categorical variables.","a": "Plays sports (yes/no) and lunch preference (indoor/outdoor)","lvl": 1,"steps": ["A categorical variable sorts people into groups.","What two group questions does the survey ask each student?"]},{"id": "AlgI.33-02","std": "Alg I.33","q": "In your survey, 70% of athletes and 30% of non-athletes prefer outdoor lunch. Is there an association?","a": "Yes","lvl": 1,"choices": ["Yes","No"],"steps": ["Compare the rates: 70% vs 30%.","A big difference in the rates means there is an association."]},{"id": "AlgI.33-03","std": "Alg I.33","q": "In your survey, 52% of athletes and 50% of non-athletes prefer outdoor lunch. Is there an association?","a": "Little or none (the rates are about the same)","lvl": 2,"also": ["no"],"steps": ["Compare the rates: 52% vs 50%.","Is that a big difference?"]},{"id": "AlgI.33-04","std": "Alg I.33","q": "Why should you survey a random sample for an investigation?","a": "So the results represent the whole group without bias","lvl": 2,"steps": ["A random sample gives everyone the same chance to be picked.","What does that do for how well the results match the whole group?"]},{"id": "AlgI.33-05","std": "Alg I.33","q": "Write one sentence to argue there is an association from 70% vs 30%.","a": "Athletes prefer outdoor lunch much more often (70%) than non-athletes (30%), so the variables seem associated","lvl": 3,"steps": ["Name both groups and both percents in your sentence.","Say which group prefers outdoor lunch more, then say what that suggests."]},{"id": "AlgI.33-06","std": "Alg I.33","q": "What kind of table organizes two categorical variables?","a": "A two-way table","lvl": 1,"also": ["two-way table"],"steps": ["Two categorical variables: rows for one, columns for the other.","What is that kind of table called?"]},{"id": "AlgI.34-01","std": "Alg I.34","q": "Is \"favorite color\" quantitative or categorical?","a": "Categorical","lvl": 1,"choices": ["Quantitative","Categorical"],"steps": ["Quantitative means numbers you can do math with. Categorical means groups or labels.","Is a color a number or a label?"]},{"id": "AlgI.34-02","std": "Alg I.34","q": "Is \"height in inches\" quantitative or categorical?","a": "Quantitative","lvl": 1,"choices": ["Quantitative","Categorical"],"steps": ["Quantitative means numbers you measure or count.","Is height a measured number?"]},{"id": "AlgI.34-03","std": "Alg I.34","q": "Is \"zip code\" quantitative or categorical?","a": "Categorical (you do not do math with zip codes)","lvl": 2,"choices": ["Quantitative","Categorical (you do not do math with zip codes)"],"steps": ["A zip code is written with numbers, but is it a measurement?","Does it make sense to add or average zip codes?"]},{"id": "AlgI.34-04","std": "Alg I.34","q": "Which display fits categorical data: a bar graph or a histogram?","a": "Bar graph","lvl": 1,"choices": ["Bar graph","Histogram"],"steps": ["Bar graphs show counts for each category.","Histograms show ranges of numbers. Which one fits categories?"]},{"id": "AlgI.34-05","std": "Alg I.34","q": "Which display fits two quantitative variables?","a": "Scatter plot","lvl": 1,"choices": ["Scatter plot","Two-way table","Pie chart"],"steps": ["Two quantitative variables means two numbers for each person.","Which display plots (x, y) points?"]},{"id": "AlgI.34-06","std": "Alg I.34","q": "Can you find the mean of categorical data?","a": "No","lvl": 1,"choices": ["Yes","No"],"steps": ["The mean adds the values and divides.","Can you add colors or names?"]},{"id": "AlgI.34-07","std": "Alg I.34","q": "Is \"number of pets\" quantitative or categorical?","a": "Quantitative","lvl": 1,"choices": ["Quantitative","Categorical"],"steps": ["Is the number of pets a count?","Counts are numbers you can do math with."]},{"id": "AlgI.35-01","std": "Alg I.35","q": "Survey of 80 students: 20 boys like cats, 15 boys like dogs; 25 girls like cats, 20 girls like dogs. How many students like cats?","a": "45","lvl": 1,"part": "a","steps": ["Add the boys who like cats and the girls who like cats.","20 + 25."]},{"id": "AlgI.35-02","std": "Alg I.35","q": "Survey of 80 students: 20 boys like cats, 15 boys like dogs; 25 girls like cats, 20 girls like dogs. What is the joint relative frequency of girls who like dogs?","a": "{1/4}","lvl": 2,"part": "b","also": ["0.25","25%"],"steps": ["Joint relative frequency = one cell ÷ the grand total.","Girls who like dogs: {20/80}. Simplify."]},{"id": "AlgI.35-03","std": "Alg I.35","q": "Survey of 80 students: 20 boys like cats, 15 boys like dogs; 25 girls like cats, 20 girls like dogs. What is the marginal relative frequency of boys?","a": "{7/16}","lvl": 2,"part": "b","also": ["0.4375","43.75%"],"steps": ["Marginal relative frequency = a row total ÷ the grand total.","Boys: 20 + 15 = 35. Find {35/80} and simplify."]},{"id": "AlgI.35-04","std": "Alg I.35","q": "Survey of 80 students: 20 boys like cats, 15 boys like dogs; 25 girls like cats, 20 girls like dogs. Of the boys, what fraction like cats?","a": "{4/7}","lvl": 2,"part": "b","also": ["57%"],"steps": ["Only look at the boys: 20 + 15 = 35.","Boys who like cats ÷ all boys: {20/35}. Simplify."]},{"id": "AlgI.35-05","std": "Alg I.35","q": "Survey of 80 students: 20 boys like cats, 15 boys like dogs; 25 girls like cats, 20 girls like dogs. Of the girls, what fraction like cats?","a": "{5/9}","lvl": 2,"part": "b","also": ["56%"],"steps": ["Only look at the girls: 25 + 20 = 45.","Girls who like cats ÷ all girls: {25/45}. Simplify."]},{"id": "AlgI.35-06","std": "Alg I.35","q": "Survey of 80 students: 20 boys like cats, 15 boys like dogs; 25 girls like cats, 20 girls like dogs. Is there a strong association between gender and pet preference?","a": "No (about 57% of boys and 56% of girls like cats)","lvl": 3,"part": "c","also": ["no"],"steps": ["Boys who like cats: {20/35}, about 57%.","Girls who like cats: {25/45}, about 56%.","Are those very different?"]},{"id": "AlgI.35-07","std": "Alg I.35","q": "In a segmented bar graph, each bar adds up to what percent?","a": "100%","lvl": 1,"part": "a","also": ["100"],"steps": ["Each bar shows the parts of one whole group.","All the parts of a whole make what percent?"]},{"id": "AlgI.36-01","std": "Alg I.36","q": "Class A: 12 of 20 passed. Class B: 18 of 30 passed. Combine them. What percent passed overall?","a": "60%","lvl": 2,"part": "a","also": ["60"],"steps": ["Add the passes: 12 + 18. Add the students: 20 + 30.","Divide, then make it a percent."]},{"id": "AlgI.36-02","std": "Alg I.36","q": "School 1: 30 of 50 ride the bus. School 2: 45 of 100 ride the bus. What fraction ride overall?","a": "{1/2}","lvl": 2,"part": "a","also": ["50%"],"steps": ["Add the riders: 30 + 45. Add the students: 50 + 100.","Divide, then simplify."]},{"id": "AlgI.36-03","std": "Alg I.36","q": "Two clubs: Club A has 8 of 10 who like pizza, Club B has 20 of 40. What is the overall percent?","a": "56%","lvl": 2,"part": "a","also": ["56"],"steps": ["Add the pizza fans: 8 + 20. Add the members: 10 + 40.","Find {28/50} and make it a percent."]},{"id": "AlgI.36-04","std": "Alg I.36","q": "Why can combined percents differ from the average of two percents?","a": "The groups have different sizes","lvl": 3,"part": "a","steps": ["Try it: 8 of 10 is 80% and 20 of 40 is 50%. Their average is 65%, but overall it's 56%.","Which group has more people in it?"]},{"id": "AlgI.36-05","std": "Alg I.36","q": "Make a two-way table total: 15 + 25 in row 1 and 10 + 30 in row 2. What is the grand total?","a": "80","lvl": 1,"steps": ["Row 1: 15 + 25 = 40. Row 2: 10 + 30 = 40.","Add the row totals."]},{"id": "AlgI.36-06","std": "Alg I.36","q": "A store tracks 60 morning and 40 evening buyers. 30 morning and 30 evening buyers used coupons. What percent of all buyers used coupons?","a": "60%","lvl": 2,"part": "a","also": ["60"],"steps": ["Coupon users: 30 + 30. All buyers: 60 + 40.","Divide, then make it a percent."]},{"id": "AlgI.37-01","std": "Alg I.37","q": "A number cube is rolled. List the event \"even.\"","a": "{2, 4, 6}","lvl": 1,"steps": ["A number cube has 1 to 6.","Which of those are even?"]},{"id": "AlgI.37-02","std": "Alg I.37","q": "A number cube is rolled. A = even, B = greater than 3. List A and B (both).","a": "{4, 6}","lvl": 2,"steps": ["Even: 2, 4, 6. Greater than 3: 4, 5, 6.","And means it's in both lists."]},{"id": "AlgI.37-03","std": "Alg I.37","q": "A number cube is rolled. A = even, B = greater than 3. List A or B.","a": "{2, 4, 5, 6}","lvl": 2,"steps": ["Even: 2, 4, 6. Greater than 3: 4, 5, 6.","Or means it's in either list. List each number once."]},{"id": "AlgI.37-04","std": "Alg I.37","q": "A number cube is rolled. What is the complement of \"rolling a 1 or 2\"?","a": "{3, 4, 5, 6}","lvl": 1,"steps": ["The complement is everything that is NOT the event.","Start with 1 to 6 and take out 1 and 2."]},{"id": "AlgI.37-05","std": "Alg I.37","q": "P(A) = 0.35. What is P(not A)?","a": "0.65","lvl": 1,"steps": ["P(not A) = 1 − P(A).","1 − 0.35."]},{"id": "AlgI.37-06","std": "Alg I.37","q": "How many outcomes are there for flipping 3 coins?","a": "8","lvl": 1,"steps": ["Each coin has 2 outcomes.","Multiply: 2 × 2 × 2."]},{"id": "AlgI.37-07","std": "Alg I.37","q": "A deck has 52 cards. How many are red or a king?","a": "28","lvl": 3,"steps": ["Red cards: 26. Kings: 4.","2 of the kings are red, so they got counted twice: 26 + 4 − 2."]},{"id": "AlgI.37-08","std": "Alg I.37","q": "An outfit is a shirt (4 choices), pants (3) and shoes (2). How many outfits?","a": "24","lvl": 1,"steps": ["Multiply the number of choices for each part.","4 × 3 × 2."]},{"id": "AlgI.38-01","std": "Alg I.38","q": "You flip a coin and roll a cube. Are the results independent?","a": "Yes","lvl": 1,"choices": ["Yes","No"],"steps": ["Independent means one result doesn't change the chance of the other.","Does the coin change how the cube lands?"]},{"id": "AlgI.38-02","std": "Alg I.38","q": "You draw two cards without putting the first back. Are the draws independent?","a": "No","lvl": 1,"choices": ["Yes","No"],"steps": ["After the first card, the deck has one fewer card.","Does that change the chances for the second draw?"]},{"id": "AlgI.38-03","std": "Alg I.38","q": "P(A) = 0.5, P(B) = 0.4 and P(A and B) = 0.2. Are A and B independent?","a": "Yes (0.5 × 0.4 = 0.2)","lvl": 2,"also": ["yes"],"steps": ["A and B are independent if P(A) × P(B) = P(A and B).","0.5 × 0.4 = ? Compare it with 0.2."]},{"id": "AlgI.38-04","std": "Alg I.38","q": "P(A) = 0.3, P(B) = 0.6 and P(A and B) = 0.25. Are A and B independent?","a": "No (0.3 × 0.6 = 0.18)","lvl": 2,"also": ["no"],"steps": ["A and B are independent if P(A) × P(B) = P(A and B).","0.3 × 0.6 = 0.18. Is that 0.25?"]},{"id": "AlgI.38-05","std": "Alg I.38","q": "Of 100 students, 40 play an instrument and 50 are in 8th grade. 20 are 8th graders who play an instrument. Are the events independent?","a": "Yes (0.4 × 0.5 = 0.2)","lvl": 3,"also": ["yes"],"steps": ["P(instrument) = 0.4, P(8th grade) = 0.5 and P(both) = 0.2.","Check: does 0.4 × 0.5 equal 0.2?"]},{"id": "AlgI.38-06","std": "Alg I.38","q": "A and B are independent with P(A) = 0.2 and P(B) = 0.5. Find P(A and B).","a": "0.1","lvl": 2,"steps": ["Independent: P(A and B) = P(A) × P(B).","0.2 × 0.5."]},{"id": "AlgI.39-01","std": "Alg I.39","q": "Of 80 students, 30 have a dog. 12 of the dog owners also have a cat. Find P(cat | dog).","a": "{2/5}","lvl": 2,"also": ["0.4","40%"],"steps": ["Given dog: only look at the 30 dog owners.","12 of them have a cat. Find {12/30} and simplify."]},{"id": "AlgI.39-02","std": "Alg I.39","q": "P(A and B) = 0.12 and P(B) = 0.4. Find P(A | B).","a": "0.3","lvl": 2,"steps": ["P(A | B) = {P(A and B)/P(B)}.","Find {0.12/0.4}."]},{"id": "AlgI.39-03","std": "Alg I.39","q": "Survey of 80 students: 20 boys like cats, 15 boys like dogs; 25 girls like cats, 20 girls like dogs. Find P(likes dogs | girl).","a": "{4/9}","lvl": 2,"steps": ["Given girl: only look at the girls, 25 + 20 = 45.","20 girls like dogs. Find {20/45} and simplify."]},{"id": "AlgI.39-04","std": "Alg I.39","q": "Survey of 80 students: 20 boys like cats, 15 boys like dogs; 25 girls like cats, 20 girls like dogs. Find P(girl | likes dogs).","a": "{4/7}","lvl": 3,"steps": ["Given likes dogs: only look at the dog lovers, 15 + 20 = 35.","20 of them are girls. Find {20/35} and simplify."]},{"id": "AlgI.39-05","std": "Alg I.39","q": "A bag has 3 red and 2 blue marbles. You draw one red and don't put it back. What is P(second is red | first was red)?","a": "{1/2}","lvl": 2,"steps": ["After one red is gone, the bag has 2 red and 2 blue.","P(red) = red marbles ÷ all marbles."]},{"id": "AlgI.39-06","std": "Alg I.39","q": "A tree diagram: P(rain) = 0.3, P(late | rain) = 0.5. Find P(rain and late).","a": "0.15","lvl": 2,"steps": ["P(rain and late) = P(rain) × P(late | rain).","0.3 × 0.5."]},{"id": "AlgI.39-07","std": "Alg I.39","q": "Are mutually exclusive events able to happen at the same time?","a": "No","lvl": 1,"choices": ["Yes","No"],"steps": ["Mutually exclusive events share no outcomes.","If they share nothing, can both happen at once?"]},{"id": "AlgI.39-08","std": "Alg I.39","q": "A card is drawn from a standard deck. Are \"heart\" and \"spade\" mutually exclusive?","a": "Yes","lvl": 1,"choices": ["Yes","No"],"steps": ["Can one card be a heart and a spade at the same time?","Mutually exclusive means they can't happen together."]},{"id": "AlgI.40-01","std": "Alg I.40","q": "Explain P(umbrella | rain) in everyday words.","a": "The chance someone carries an umbrella when it is raining","lvl": 1,"steps": ["The bar | means given. Read it as: the chance of an umbrella, given rain.","Say it as a sentence about a rainy day."]},{"id": "AlgI.40-02","std": "Alg I.40","q": "Is the chance of being late higher given there is a snowstorm? Is that conditional probability?","a": "Yes; it is the chance of being late given a snowstorm","lvl": 1,"also": ["yes"],"steps": ["Does a snowstorm make being late more likely?","A chance given a condition is what conditional probability means."]},{"id": "AlgI.40-03","std": "Alg I.40","q": "Does knowing a coin landed heads change the chance the next flip is heads?","a": "No (the flips are independent)","lvl": 1,"also": ["no"],"steps": ["Does a coin remember the last flip?","Independent events don't change each other's chances."]},{"id": "AlgI.40-04","std": "Alg I.40","q": "P(pass | studied) = 0.9 and P(pass | did not study) = 0.5. Are passing and studying independent?","a": "No (the chances are different)","lvl": 2,"also": ["no"],"steps": ["If they were independent, P(pass) would be the same whether you studied or not.","0.9 vs 0.5. Are they the same?"]},{"id": "AlgI.40-05","std": "Alg I.40","q": "Is P(sick | fever) the same as P(fever | sick)? Explain.","a": "No; the first is among people with a fever, the second is among sick people","lvl": 3,"also": ["no"],"steps": ["P(sick | fever): look only at people with a fever.","P(fever | sick): look only at sick people. Are those the same group?"]},{"id": "AlgI.40-06","std": "Alg I.40","q": "Give an example of two independent events in everyday life.","a": "Rolling a die and the weather tomorrow","lvl": 2,"steps": ["Independent means one thing doesn't change the chance of the other.","Think of two things that have nothing to do with each other."]},{"id": "AlgI.41-01","std": "Alg I.41","q": "A number cube is rolled. Given the roll is even, what is the probability it is a 6?","a": "{1/3}","lvl": 1,"steps": ["Given even: only look at 2, 4 and 6.","How many of those are a 6? Out of how many?"]},{"id": "AlgI.41-02","std": "Alg I.41","q": "A number cube is rolled. Given the roll is greater than 2, what is the probability it is even?","a": "{1/2}","lvl": 2,"steps": ["Given greater than 2: only look at 3, 4, 5 and 6.","How many of those are even? Out of 4."]},{"id": "AlgI.41-03","std": "Alg I.41","q": "Of 50 students in band, 20 also play a sport. What is P(sport | band)?","a": "{2/5}","lvl": 1,"also": ["0.4","40%"],"steps": ["Given band: only look at the 50 band students.","20 of them play a sport. Find {20/50} and simplify."]},{"id": "AlgI.41-04","std": "Alg I.41","q": "In P(A | B), which group do you divide by?","a": "The outcomes in B","lvl": 1,"also": ["B"],"steps": ["P(A | B) means the chance of A, given B.","You only look inside B. So what goes on the bottom of the fraction?"]},{"id": "AlgI.41-05","std": "Alg I.41","q": "Two coins are flipped. Given at least one is heads, what is the probability both are heads?","a": "{1/3}","lvl": 3,"steps": ["Two coins can land HH, HT, TH or TT.","Given at least one heads, cross out TT. How many are left?","How many of those are HH?"]},{"id": "AlgI.41-06","std": "Alg I.41","q": "Of 120 people at a game, 75 wore team colors. 45 of those cheered loudly. What fraction of people in team colors cheered loudly?","a": "{3/5}","lvl": 2,"also": ["0.6","60%"],"steps": ["Only look at the 75 in team colors.","45 of them cheered loudly. Find {45/75} and simplify."]},{"id": "AlgI.1-08","std": "Alg I.1","q": "Which radical expression is equivalent to 16^{{1/2}}?","a": "√16","lvl": 1,"choices": ["1 divided by 16 squared","16 divided by 2","√16","∛16"],"steps": ["An exponent of {1/2} means a square root.","The 2 in the bottom of the exponent tells you which root.","Which choice shows the square root of 16?"]},{"id": "AlgI.1-09","std": "Alg I.1","q": "Write ∛y using a rational exponent.","a": "y^{{1/3}}","lvl": 1,"choices": ["3y","y³","y⁻³","y^{{1/3}}"],"steps": ["A root can be written as an exponent with 1 on top.","For a cube root, the 3 goes in the bottom of the exponent.","Write y with that fraction as its exponent."]},{"id": "AlgI.1-10","std": "Alg I.1","q": "What is the value of 27^{{1/3}}?","a": "3","lvl": 1,"choices": ["{1/9}","81","3","9"],"steps": ["The exponent {1/3} means find the cube root of 27.","What number times itself three times equals 27?","Test small whole numbers: 2 × 2 × 2, then 3 × 3 × 3."]},{"id": "AlgI.1-11","std": "Alg I.1","q": "Which expression is equivalent to ∜(m³)?","a": "m^{{3/4}}","lvl": 2,"choices": ["m^{{1/12}}","m^{{3/4}}","m^{{4/3}}","m¹²"],"steps": ["In a rational exponent, the power goes on top and the root on the bottom.","Here the power is 3. What root is ∜?","Write m with that fraction as its exponent."]},{"id": "AlgI.1-12","std": "Alg I.1","q": "What is the value of 32^{{2/5}}?","a": "4","lvl": 2,"choices": ["4","10","12.8","64"],"steps": ["The exponent {2/5} means take the fifth root, then square it.","2⁵ = 32, so the fifth root of 32 is 2.","Now square that result."]},{"id": "AlgI.1-13","std": "Alg I.1","q": "If (x^{{1/4}})⁴ = x¹, which property of integer exponents is being extended to define x^{{1/4}}?","a": "Power of a Power Property","lvl": 2,"choices": ["Product of Powers Property","Zero Exponent Property","Power of a Power Property","Quotient of Powers Property"],"steps": ["The left side raises a power, x^{{1/4}}, to another power, 4.","To simplify, multiply the exponents: {1/4} × 4 = 1.","Which property says to multiply exponents?"]},{"id": "AlgI.1-14","std": "Alg I.1","q": "Maya says 8^{{2/3}} = {16/3} because you multiply 8 by {2/3}. What is the true value of 8^{{2/3}}, and why?","a": "4, because 8^{{2/3}} = (∛8)² = 2²","lvl": 3,"choices": ["64, because 8² = 64","{16/3}, because 8 · {2/3} = {16/3}","4, because 8^{{2/3}} = (∛8)² = 2²","2, because ∛8 is 2"],"steps": ["Maya multiplied the base 8 by the exponent {2/3}. That is the mistake.","An exponent of {2/3} means take the cube root of 8, then square it.","Find the cube root of 8, then square it."]},{"id": "AlgI.1-15","std": "Alg I.1","q": "Which of the following statements correctly explains why b^{{1/n}} is defined as the nth root of b for positive real numbers b?","a": "Raising b^{{1/n}} to the nth power gives b^{({1/n}) · n} = b¹ = b, which matches the definition of an nth root.","lvl": 3,"choices": ["Adding {1/n} to itself n times equals 1, so b^{{1/n}} = b ÷ n.","Subtracting {1/n} from n gives b¹, which is the nth root.","Raising b^{{1/n}} to the nth power gives b^{({1/n}) · n} = b¹ = b, which matches the definition of an nth root.","Multiplying b^{{1/n}} by n gives b."],"steps": ["Raise b^{{1/n}} to the nth power. That is a power of a power.","Multiply the exponents: {1/n} × n = 1, so you get b¹ = b.","Pick the choice that explains this."]},{"id": "AlgI.1-16","std": "Alg I.1","q": "Compare the values of 16^{{3/4}} and 64^{{2/3}}. Which one is greater and by how much?","a": "64^{{2/3}} is greater by 8 (since 64^{{2/3}} = 16 and 16^{{3/4}} = 8).","lvl": 3,"choices": ["64^{{2/3}} is greater by 8 (since 64^{{2/3}} = 16 and 16^{{3/4}} = 8).","64^{{2/3}} is greater by 30 (since 64^{{2/3}} = 42 and 16^{{3/4}} = 12).","16^{{3/4}} is greater by 4 (since 16^{{3/4}} = 12 and 64^{{2/3}} = 8).","They are equal because both simplify to 12."],"steps": ["Evaluate 16^{{3/4}}: take the fourth root of 16, then cube it.","Evaluate 64^{{2/3}}: take the cube root of 64, then square it.","Which is greater? Subtract to find by how much."]},{"id": "AlgI.2-09","std": "Alg I.2","q": "Simplify: x^{{1/3}} · x^{{2/3}}","a": "x","lvl": 1,"choices": ["x","x^{{2/9}}","2x","x^{{3/6}}"],"steps": ["When multiplying powers with the same base x, add the exponents.","Add the fractions: {1/3} + {2/3} = {3/3} = 1.","Write x to that power."]},{"id": "AlgI.2-10","std": "Alg I.2","q": "Simplify: (a^{{3/5}})⁵","a": "a³","lvl": 1,"choices": ["a³","5a³","a^{{3/25}}","a^{{28/5}}"],"steps": ["When raising a power to a power, multiply the two exponents.","Multiply {3/5} × 5 = {15/5} = 3.","Write a to that power."]},{"id": "AlgI.2-11","std": "Alg I.2","q": "Which expression is equivalent to k^{{7/4}} ÷ k^{{3/4}} for k > 0?","a": "k","lvl": 1,"choices": ["k","k^{{7/3}}","k^{{10/4}}","k^{{21/16}}"],"steps": ["When dividing powers with the same base k, subtract the exponents.","Subtract the fractions: {7/4} − {3/4} = {4/4} = 1.","Write k to that power."]},{"id": "AlgI.2-12","std": "Alg I.2","q": "Simplify the expression (25x⁶)^{{1/2}} for x ≥ 0.","a": "5x³","lvl": 2,"choices": ["25x³","12.5x³","5x³","5x⁴"],"steps": ["Apply the exponent {1/2} to both factors: 25^{{1/2}} × (x⁶)^{{1/2}}.","Find √25. For x, multiply 6 × {1/2}.","Put the parts together."]},{"id": "AlgI.2-13","std": "Alg I.2","q": "Which expression is equivalent to √y · (∛y) for y > 0?","a": "y^{{5/6}}","lvl": 2,"choices": ["y^{{1/5}}","y^{{1/6}}","y^{{5/6}}","y^{{2/5}}"],"steps": ["Rewrite both radicals as exponents: y^{{1/2}} × y^{{1/3}}.","Multiplying the same base means add the exponents.","Use a common denominator of 6 to add {1/2} + {1/3}."]},{"id": "AlgI.2-14","std": "Alg I.2","q": "Rewrite {1/∛(n²)} using a single rational exponent for n > 0.","a": "n^{−{2/3}}","lvl": 2,"choices": ["n^{−{3/2}}","n^{−{2/3}}","−n^{{2/3}}","n^{{2/3}}"],"steps": ["Rewrite ∛(n²) in the denominator as n^{{2/3}}.","A power in the denominator can move up with a negative exponent.","Write n with that negative exponent."]},{"id": "AlgI.2-15","std": "Alg I.2","q": "A square has an area of 64x^{{4/3}} square units, where x > 0. What is the side length of the square in simplest form?","a": "8x^{{2/3}}","lvl": 3,"choices": ["32x^{{2/3}}","8x^{{2/3}}","8x^{{8/3}}","8x^{{4/9}}"],"steps": ["The side of a square is the square root of its area: raise it to {1/2}.","Apply {1/2} to each factor: 64^{{1/2}} and (x^{{4/3}})^{{1/2}}.","Find √64, and multiply {4/3} × {1/2}."]},{"id": "AlgI.2-16","std": "Alg I.2","q": "Simplify the expression ((8a³b⁻⁶)^{{1/3}}) ÷ (a^{{1/2}} · b⁻¹) for a > 0 and b > 0.","a": "2a^{{1/2}} ÷ b","lvl": 3,"choices": ["2a^{{1/2}} ÷ b","{8/3}a^{{1/2}} ÷ b","2a^{{1/2}} · b³","2a^{{3/2}} ÷ b³"],"steps": ["Simplify the top: 8^{{1/3}} = 2, (a³)^{{1/3}} = a, (b⁻⁶)^{{1/3}} = b⁻².","Divide by a^{{1/2}} · b⁻¹: subtract exponents for a, then for b.","Write any negative exponent as a fraction."]},{"id": "AlgI.2-17","std": "Alg I.2","q": "Is (∜(x⁶)) · x^{−{1/2}} equivalent to x for all x > 0?","a": "Yes, because x^{{6/4}} · x^{−{1/2}} = x^{{3/2} − {1/2}} = x¹","lvl": 3,"choices": ["No, it equals x^{−{3/4}}","No, it equals x²","No, it equals x only when x = 1","Yes, because x^{{6/4}} · x^{−{1/2}} = x^{{3/2} − {1/2}} = x¹"],"steps": ["Rewrite ∜(x⁶) as x^{{6/4}}, which reduces to x^{{3/2}}.","Multiply by x^{−{1/2}}: add the exponents {3/2} and −{1/2}.","What power of x do you get? Is it x?"]},{"id": "AlgI.3-08","std": "Alg I.3","q": "By definition, what is the value of i²?","a": "−1","lvl": 1,"choices": ["−1","1","0","−i"],"steps": ["The imaginary unit is defined as i = √(−1).","Squaring a square root undoes the root.","So what is (√(−1))²?"]},{"id": "AlgI.3-09","std": "Alg I.3","q": "Simplify the expression (√(−25)) using the imaginary unit i.","a": "5i","lvl": 1,"choices": ["−5i","5i","25i","−5"],"steps": ["Split √(−25) into √25 × √(−1).","Find √25. Replace √(−1) with i.","Multiply the two parts."]},{"id": "AlgI.3-10","std": "Alg I.3","q": "Which of the following is equal to i?","a": "√(−1)","lvl": 1,"choices": ["−1","{1/−1}","√1","√(−1)"],"steps": ["The imaginary unit i is defined using a square root.","i is the square root of which number?","Find the choice that matches."]},{"id": "AlgI.3-11","std": "Alg I.3","q": "Simplify: (3i)(4i)","a": "−12","lvl": 2,"choices": ["12i","−12i","−12","12"],"steps": ["Multiply the numbers and the imaginary units: (3 × 4)(i × i) = 12i².","Substitute i² = −1 into the expression.","Multiply 12 × (−1)."]},{"id": "AlgI.3-12","std": "Alg I.3","q": "Simplify the expression: (√(−9)) + (√(−49))","a": "10i","lvl": 2,"choices": ["−10","10i","10","−10i"],"steps": ["Simplify each radical using i: √(−9) = 3i and √(−49) = 7i.","Add the like imaginary terms: 3i + 7i.","Combine the coefficients."]},{"id": "AlgI.3-13","std": "Alg I.3","q": "Which expression is equivalent to i³?","a": "−i","lvl": 2,"choices": ["−1","1","−i","i"],"steps": ["Rewrite i³ as i² × i.","Substitute i² = −1 into the product.","Multiply (−1) × i."]},{"id": "AlgI.3-14","std": "Alg I.3","q": "Why is √(−16) not a real number, and what does it equal using i?","a": "No real number squared is negative; it equals 4i","lvl": 3,"choices": ["No real number squared is negative; it equals 4i","No real number squared is negative; it equals −4","No real number squared is negative; it equals 16i","Negative numbers have no square root of any kind; it is undefined"],"steps": ["Recall that squaring any real number always gives a non-negative result.","Explain that no real number squared equals −16, so √(−16) is not real.","Rewrite √(−16) as √16 × √(−1). Simplify."]},{"id": "AlgI.3-15","std": "Alg I.3","q": "Evaluate: i⁴ + i² + 1","a": "1","lvl": 3,"choices": ["−1","1","2i + 1","3"],"steps": ["Find each power of i. Start with i² = −1.","i⁴ = (i²)². Square −1.","Put both values into i⁴ + i² + 1 and add."]},{"id": "AlgI.3-16","std": "Alg I.3","q": "Devon simplified (√(−4)) × (√(−9)) as √36 = 6. What is the correct product?","a": "−6, because (2i)(3i) = 6i² = −6","lvl": 3,"choices": ["6i, because (2i)(3i) = 6i","−6i, because (2i)(3i) = −6i","6, because √36 is 6","−6, because (2i)(3i) = 6i² = −6"],"steps": ["Note that √a × √b = √ab only works when a and b are non-negative.","Rewrite each negative radical using i first: √(−4) = 2i and √(−9) = 3i.","Multiply (2i)(3i), then use i² = −1."]},{"id": "AlgI.4-08","std": "Alg I.4","q": "A gym charges a §35 signup fee plus §20 per month, modeled by the expression 20m + 35. What does the term 20m represent in this context?","a": "The total monthly membership fees paid after m months","lvl": 1,"choices": ["The total cost for 1 month","The one-time signup fee","The total monthly membership fees paid after m months","The number of months of membership"],"steps": ["In 20m + 35, 35 is the one-time signup fee and m is the number of months.","The term 20m multiplies the monthly cost of 20 by m months.","So what does 20m stand for?"]},{"id": "AlgI.4-09","std": "Alg I.4","q": "The population of a town is modeled by 12,000(1.03)^t, where t is years since 2020. What does the number 12,000 represent?","a": "The town's population in the year 2020","lvl": 1,"choices": ["The town's population in the year 2020","The annual growth rate of the population","The population increase each year","The number of years since 2020"],"steps": ["In an exponential model a(b)^{t}, the number a is the starting value at t = 0.","Here, t = 0 corresponds to the year 2020.","So what does 12,000 stand for?"]},{"id": "AlgI.4-10","std": "Alg I.4","q": "In the expression 5x² − 8x + 12, what is the constant term?","a": "12","lvl": 1,"choices": ["−8","2","5","12"],"steps": ["A constant term is a number in an expression with no variable attached.","Look at the terms 5x², −8x, and 12.","Which term has no x?"]},{"id": "AlgI.4-11","std": "Alg I.4","q": "The value of a car after t years is given by V(t) = 24,000(1 − 0.15)^t. What does the quantity (1 − 0.15) represent as a single entity?","a": "The decay factor showing the car retains 85% of its value each year","lvl": 2,"choices": ["The decay factor showing the car retains 85% of its value each year","The dollar amount the car loses in the first year","The 15% tax paid when buying the car","The number of years until the car has no value"],"steps": ["Evaluate the quantity inside the parentheses: 1 − 0.15 = 0.85.","In V(t) = 24,000(0.85)^{t}, 0.85 is the annual decay factor.","So what does 0.85 say about the value each year?"]},{"id": "AlgI.4-12","std": "Alg I.4","q": "A rectangular garden has an area modeled by x(x + 6), where x is the width in feet. What does the factor (x + 6) represent?","a": "The length of the garden in feet","lvl": 2,"choices": ["The area of the garden in square feet","The perimeter of the garden in feet","The length of the garden in feet","Six times the width of the garden"],"steps": ["Recall that the area of a rectangle is width × length.","Since x is the width in x(x + 6), the other factor must be the length.","So what does (x + 6) stand for?"]},{"id": "AlgI.4-13","std": "Alg I.4","q": "The height in feet of a water balloon t seconds after being thrown is −16t² + 32t + 5. What does the constant 5 represent?","a": "The initial height in feet from which the balloon was thrown","lvl": 2,"choices": ["The initial upward speed in feet per second","The time in seconds it takes the balloon to hit the ground","The maximum height the balloon reaches","The initial height in feet from which the balloon was thrown"],"steps": ["Substitute t = 0 into −16t² + 32t + 5 to find the starting height.","Compute −16(0)² + 32(0) + 5 = 5.","So what does 5 stand for?"]},{"id": "AlgI.4-14","std": "Alg I.4","q": "A concert venue's ticket revenue is modeled by (25 + 5p)(400 − 20p), where p is the number of §5 price increases. What do the two factors represent?","a": "(25 + 5p) is the price per ticket and (400 − 20p) is the number of tickets sold","lvl": 3,"choices": ["(25 + 5p) is the number of price increases and (400 − 20p) is the seats left","(25 + 5p) is the number of tickets sold and (400 − 20p) is the price per ticket","(25 + 5p) is the total revenue and (400 − 20p) is the total cost","(25 + 5p) is the price per ticket and (400 − 20p) is the number of tickets sold"],"steps": ["Revenue equals (price per ticket) × (number of tickets sold).","Since p is the number of 5-dollar increases, 25 + 5p is the new ticket price.","So what does 400 − 20p stand for?"]},{"id": "AlgI.4-15","std": "Alg I.4","q": "A savings account balance is modeled by 500(1 + {0.04/12})^{12t}, where t is time in years. What do the sub-expressions ({0.04/12}) and (12t) represent?","a": "({0.04/12}) is the monthly interest rate, and (12t) is the total number of monthly compounding periods in t years.","lvl": 3,"choices": ["({0.04/12}) is the initial deposit, and (12t) is the annual interest rate.","({0.04/12}) is the number of months in a year, and (12t) is the total interest paid.","({0.04/12}) is the monthly interest rate, and (12t) is the total number of monthly compounding periods in t years.","({0.04/12}) is the annual interest earned, and (12t) is the balance after 12 years."],"steps": ["The annual rate 0.04 is divided by 12 months, giving the monthly rate.","The exponent 12t multiplies 12 months per year by t years.","Match those meanings to a choice."]},{"id": "AlgI.4-16","std": "Alg I.4","q": "The total cost for a catering order is 150 + 12(n − 10) for n > 10 guests. What does 12(n − 10) mean?","a": "An extra §12 for each guest beyond the first 10","lvl": 3,"choices": ["§12 for every guest, including the first 10","The §150 base fee for the first 10 guests","A §12 discount for each of the first 10 guests","An extra §12 for each guest beyond the first 10"],"steps": ["Notice that 150 is the base fee covering the first 10 guests.","The expression (n − 10) counts the extra guests beyond 10.","So what does 12(n − 10) charge for?"]},{"id": "AlgI.5-08","std": "Alg I.5","q": "Which expression is equivalent to x² − 49?","a": "(x − 7)(x + 7)","lvl": 1,"choices": ["(x − 7)²","(x − 7)(x + 7)","(x + 7)²","(x − 49)(x + 1)"],"steps": ["Recognize x² − 49 as a difference of two squares: x² − 7².","Use a² − b² = (a − b)(a + b).","What are a and b here?"]},{"id": "AlgI.5-09","std": "Alg I.5","q": "Factor out the greatest common factor from 14x² + 21x.","a": "7x(2x + 3)","lvl": 1,"choices": ["7x(2x + 21)","7(2x² + 3)","14x(x + 7)","7x(2x + 3)"],"steps": ["Find the greatest common factor of 14x² and 21x, which is 7x.","Divide each term by 7x.","Write 7x times what is left."]},{"id": "AlgI.5-10","std": "Alg I.5","q": "Which expression is equivalent to 3^{x + 2}?","a": "9 × 3^x","lvl": 1,"choices": ["9 × 3^x","6 × 3^x","3^x + 9","3^{2x}"],"steps": ["Use the Product of Powers rule in reverse: 3^{x + 2} = 3^{x} × 3².","What is 3²?","Write it as a number times 3^{x}."]},{"id": "AlgI.5-11","std": "Alg I.5","q": "Use the structure of the expression 4x² − 25y² to write it in factored form.","a": "(2x − 5y)(2x + 5y)","lvl": 2,"choices": ["(2x − 5y)(2x + 5y)","4(x − 5y)(x + 5y)","(4x − 25y)(x + y)","(2x − 5y)²"],"steps": ["Rewrite 4x² − 25y² as a difference of squares: (2x)² − (5y)².","Apply the formula a² − b² = (a − b)(a + b).","Substitute a = 2x and b = 5y."]},{"id": "AlgI.5-12","std": "Alg I.5","q": "Which expression is equivalent to (x + 3)² − 16?","a": "(x − 1)(x + 7)","lvl": 2,"choices": ["(x + 3)(x − 16)","(x − 13)(x + 19)","(x − 1)(x + 7)","(x + 1)(x − 7)"],"steps": ["Treat (x + 3)² − 4² as a difference of squares a² − b².","Write it as ((x + 3) − 4)((x + 3) + 4).","Simplify inside each set of parentheses."]},{"id": "AlgI.5-13","std": "Alg I.5","q": "Rewrite the exponential expression ({1/4})^t using a base of 2.","a": "2^{−2t}","lvl": 2,"choices": ["2^{2t}","−2^{2t}","2^{−{t/2}}","2^{−2t}"],"steps": ["Rewrite the fraction {1/4} as a power of 2: {1/4} = {1/2²} = 2⁻².","Substitute 2⁻² into the expression: (2⁻²)^{t}.","Multiply the exponents."]},{"id": "AlgI.5-14","std": "Alg I.5","q": "Factor x⁴ − 16 completely over the real numbers by recognizing it as a difference of squares.","a": "(x² + 4)(x − 2)(x + 2)","lvl": 3,"choices": ["(x − 2)(x + 2)(x² − 4)","(x − 2)²(x + 2)²","(x² − 4)(x² − 4)","(x² + 4)(x − 2)(x + 2)"],"steps": ["Factor x⁴ − 16 as a difference of squares: (x² + 4)(x² − 4).","Can x² − 4 be factored again?","Write all the factors together."]},{"id": "AlgI.5-15","std": "Alg I.5","q": "Rewrite 2^{3t + 1} in the form a · b^t.","a": "2 × 8^t","lvl": 3,"choices": ["8 × 2^t","2 × 8^t","8^t + 2","2 × 6^t"],"steps": ["Split the sum in the exponent: 2^{3t + 1} = 2¹ × 2^{3t}.","Rewrite 2^{3t} using Power of a Power as (2³)^{t}.","Simplify 2³, then write it as a · b^{t}."]},{"id": "AlgI.5-16","std": "Alg I.5","q": "A student sees the expression 3(x − 2)² + 10(x − 2) − 8 and treats (x − 2) as a single variable u to factor it. Write the fully factored form in terms of x.","a": "(3x − 8)(x + 2)","lvl": 3,"choices": ["(3x − 2)(x + 4)","(3x + 8)(x − 2)","(3x − 4)(x − 2)","(3x − 8)(x + 2)"],"steps": ["Let u = x − 2. Factor 3u² + 10u − 8.","Substitute u = x − 2 back in: (3(x − 2) − 2)((x − 2) + 4).","Simplify each factor."]},{"id": "AlgI.6-09","std": "Alg I.6","q": "Find the zeros of the function f(x) = (x − 4)(x + 9).","a": "x = 4 and x = −9","lvl": 1,"choices": ["x = 4 and x = 9","x = −4 and x = −9","x = 4 and x = −9","x = −4 and x = 9"],"steps": ["Zeros are the x-values that make f(x) = 0.","Set each factor equal to 0: x − 4 = 0 and x + 9 = 0.","Solve each one."]},{"id": "AlgI.6-10","std": "Alg I.6","q": "A quadratic function is written in vertex form as g(x) = (x − 5)² + 3. What is the minimum value of g(x)?","a": "3","lvl": 1,"choices": ["−5","3","5","28"],"steps": ["In vertex form g(x) = (x − h)² + k, the vertex is (h, k).","Find h and k. Does the parabola open up?","The minimum is the y-value of the vertex."]},{"id": "AlgI.6-11","std": "Alg I.6","q": "Factor the quadratic expression x² + 7x + 12 to reveal its zeros.","a": "(x + 3)(x + 4)","lvl": 1,"choices": ["(x − 3)(x − 4)","(x + 3)(x + 4)","(x + 1)(x + 12)","(x + 2)(x + 6)"],"steps": ["Look for two numbers that multiply to 12 and add to 7.","Test the factor pairs of 12.","Write it as two binomials."]},{"id": "AlgI.6-12","std": "Alg I.6","q": "Rewrite the quadratic expression x² − 8x + 19 in vertex form (x − h)² + k to find the minimum value of the function.","a": "(x − 4)² + 3; minimum value is 3","lvl": 2,"choices": ["(x − 4)² + 3; minimum value is 3","(x + 4)² + 3; minimum value is 3","(x − 8)² − 45; minimum value is −45","(x − 4)² + 19; minimum value is 19"],"steps": ["Take half of −8, which is −4, and square it to get 16.","Add and subtract 16. Rewrite the square.","What is k? That is the minimum."]},{"id": "AlgI.6-13","std": "Alg I.6","q": "A ball's height in feet is modeled by h(t) = −16t² + 48t. Factor the expression to determine when the ball hits the ground after being launched.","a": "h(t) = −16t(t − 3), so it hits the ground at t = 3 seconds.","lvl": 2,"choices": ["h(t) = −16t(t + 3), so it hits the ground at t = 3 seconds.","h(t) = −16t(t − 3), so it hits the ground at t = 3 seconds.","h(t) = −16t(t − 48), so it hits the ground at t = 16 seconds.","h(t) = −16(t² − 48), so it hits the ground at t = 48 seconds."],"steps": ["Factor out the GCF, −16t.","Set −16t(t − 3) = 0 to find when the height is 0.","Solve. Which solution is the landing?"]},{"id": "AlgI.6-14","std": "Alg I.6","q": "The number of bacteria in a petri dish after t hours is modeled by B(t) = 200(2)^{2t}. Rewrite this expression in the form 200(b)^t to find the hourly growth factor.","a": "200(4)^t; the hourly growth factor is 4","lvl": 2,"choices": ["400(2)^t; the hourly growth factor is 2","200(2)^t; the hourly growth factor is 2","200(1)^t; the hourly growth factor is 1","200(4)^t; the hourly growth factor is 4"],"steps": ["Use the Power of a Power rule to rewrite 2^{2t} as (2²)^{t}.","Evaluate 2².","Which base is the hourly growth factor?"]},{"id": "AlgI.6-15","std": "Alg I.6","q": "A company's weekly profit P(x), in hundreds of dollars, is P(x) = −2x² + 24x − 40, where x is the price per item in dollars. Complete the square. Which price gives the most profit, and what is it?","a": "P(x) = −2(x − 6)² + 32; a §6 price gives the most profit, §3,200","lvl": 3,"choices": ["P(x) = −2(x − 6)² + 32; a §32 price gives the most profit, §600","P(x) = −2(x − 6)² + 32; a §6 price gives the most profit, §3,200","P(x) = −2(x − 6)² − 4; a §6 price gives the most profit, §400","P(x) = −2(x − 12)² + 248; a §12 price gives the most profit, §24,800"],"steps": ["Factor −2 from the x-terms: −2(x² − 12x) − 40.","Add 36 inside. That takes away 72, so add 72 outside.","Read the vertex. P is in hundreds of dollars."]},{"id": "AlgI.6-16","std": "Alg I.6","q": "Three equivalent forms of a quadratic function f(x) are given:\nForm A: f(x) = 2x² − 4x − 16\nForm B: f(x) = 2(x − 4)(x + 2)\nForm C: f(x) = 2(x − 1)² − 18\nWhich form most directly reveals the y-intercept, and what is it?","a": "Form A; the y-intercept is (0, −16).","lvl": 3,"choices": ["Form B; the y-intercept is (0, 4).","Form C; the y-intercept is (0, −18).","Form A; the y-intercept is (0, −16).","Form B; the y-intercept is (0, −8)."],"steps": ["The y-intercept occurs where x = 0.","In standard form (Form A), plugging in x = 0 leaves just the constant −16.","Which form shows that constant right away?"]},{"id": "AlgI.6-17","std": "Alg I.6","q": "A sample decays by M(t) = 80(0.5)^{{t/6}}, where t is in days. Rewrite it as 80(b)^t. About what percent of the sample is lost each day?","a": "About 10.9% (b = 0.5^{{1/6}} ≈ 0.891)","lvl": 3,"choices": ["About 8.3%","About 50%","About 10.9% (b = 0.5^{{1/6}} ≈ 0.891)","About 89.1%"],"steps": ["Rewrite (0.5)^{{t/6}} as (0.5^{{1/6}})^{t} to find the daily factor.","Compute 0.5^{{1/6}} on a calculator.","Subtract that factor from 1. Write it as a percent."]},{"id": "AlgI.7-10","std": "Alg I.7","q": "Add the polynomials: (4x² + 3x − 5) + (2x² − 7x + 9)","a": "6x² − 4x + 4","lvl": 1,"choices": ["6x² + 10x + 14","6x² − 4x + 4","2x² − 4x + 4","6x⁴ − 4x² + 4"],"steps": ["Group like terms: (4x² + 2x²) + (3x − 7x) + (−5 + 9).","Add the coefficients for each group: 6x², −4x, and +4.","Write the combined terms."]},{"id": "AlgI.7-11","std": "Alg I.7","q": "Multiply: 3x(2x² − 5x + 4)","a": "6x³ − 15x² + 12x","lvl": 1,"choices": ["6x² − 15x + 12","5x³ − 2x² + 7x","6x³ − 5x + 4","6x³ − 15x² + 12x"],"steps": ["Distribute 3x to each term inside the parentheses.","Multiply 3x by 2x², by −5x and by 4.","Write the three products together."]},{"id": "AlgI.7-12","std": "Alg I.7","q": "Subtract: (7n + 8) − (3n + 2)","a": "4n + 6","lvl": 1,"choices": ["10n + 10","4n + 10","4n + 6","4n − 6"],"steps": ["Distribute the minus sign to the second group: 7n + 8 − 3n − 2.","Combine like terms: (7n − 3n) and (8 − 2).","Simplify each group."]},{"id": "AlgI.7-13","std": "Alg I.7","q": "Subtract (5x² − 3x + 6) from (9x² + 4x − 2).","a": "4x² + 7x − 8","lvl": 2,"choices": ["4x² + 7x − 8","4x² + x + 4","14x² + x + 4","−4x² − 7x + 8"],"steps": ["Set up the subtraction in order: (9x² + 4x − 2) − (5x² − 3x + 6).","Distribute the negative: 9x² + 4x − 2 − 5x² + 3x − 6.","Combine like terms."]},{"id": "AlgI.7-14","std": "Alg I.7","q": "Multiply the binomials: (2x − 5)(3x + 4)","a": "6x² − 7x − 20","lvl": 2,"choices": ["6x² − 20","6x² + 7x − 20","6x² − 23x − 20","6x² − 7x − 20"],"steps": ["Use FOIL to multiply: 2x(3x) + 2x(4) − 5(3x) − 5(4).","Simplify each product: 6x² + 8x − 15x − 20.","Combine the middle terms."]},{"id": "AlgI.7-15","std": "Alg I.7","q": "Expand and simplify: (4a − 3)²","a": "16a² − 24a + 9","lvl": 2,"choices": ["16a² − 9","16a² + 9","16a² − 24a + 9","16a² − 12a + 9"],"steps": ["Rewrite (4a − 3)² as (4a − 3)(4a − 3).","Multiply using FOIL: 16a² − 12a − 12a + 9.","Combine like terms."]},{"id": "AlgI.7-16","std": "Alg I.7","q": "Multiply (x − 3)(2x² + 5x − 4) and write the result in standard form.","a": "2x³ − x² − 19x + 12","lvl": 3,"choices": ["2x³ − 6x² − 15x + 12","2x³ − x² − 11x + 12","2x³ + 11x² + 11x + 12","2x³ − x² − 19x + 12"],"steps": ["Distribute x and −3 across (2x² + 5x − 4).","Expand to get 2x³ + 5x² − 4x − 6x² − 15x + 12.","Combine like terms."]},{"id": "AlgI.7-17","std": "Alg I.7","q": "A rectangular patio has a length of (3x + 4) feet and a width of (2x − 1) feet. Inside the patio is a square flowerbed with a side length of (x + 2) feet. Write a polynomial in standard form representing the area of the patio outside the flowerbed.","a": "5x² + x − 8","lvl": 3,"choices": ["5x² + x − 8","5x² + 9x","7x² + 9x","5x² + 5x − 8"],"steps": ["Find patio area: (3x + 4)(2x − 1) = 6x² + 5x − 4.","Find flowerbed area: (x + 2)² = x² + 4x + 4.","Subtract the flowerbed from the patio."]},{"id": "AlgI.7-18","std": "Alg I.7","q": "Polynomials are not closed under division. Which division gives a result that is NOT a polynomial?","a": "(x + 1) ÷ x = 1 + {1/x}","lvl": 3,"choices": ["(x + 1) ÷ x = 1 + {1/x}","6x³ ÷ 2x = 3x²","(x² + 2x) ÷ x = x + 2","(x² − 9) ÷ (x − 3) = x + 3"],"steps": ["A polynomial can't have a variable in a denominator.","Simplify each division in the choices.","Which result has a term like {1/x}?"]},{"id": "AlgI.8-08","std": "Alg I.8","q": "Is x = −2 a valid solution to the equation |x + 5| = 3x?","a": "No, because |(−2) + 5| = 3 while 3(−2) = −6, and 3 does not equal −6.","lvl": 1,"choices": ["No, because |(−2) + 5| = 3 while 3(−2) = −6, and 3 does not equal −6.","Yes, because absolute value makes −6 positive.","No, because x cannot be negative inside an absolute value.","Yes, because |−2 + 5| = 3 and 3(2) = 6."],"steps": ["Substitute x = −2 into both sides of |x + 5| = 3x.","Left side: |−2 + 5| = |3| = 3. Right side: 3(−2) = −6.","Are the two sides equal?"]},{"id": "AlgI.8-09","std": "Alg I.8","q": "How many solutions does the equation |2x − 1| = −5 have?","a": "0 (no solution)","lvl": 1,"choices": ["1","2","0 (no solution)","Infinitely many"],"steps": ["An absolute value is never negative.","The equation sets an absolute value equal to −5, which is negative.","So how many solutions can it have?"]},{"id": "AlgI.8-10","std": "Alg I.8","q": "Check whether x = 4 satisfies the equation |3x − 10| = x − 2.","a": "Yes, because |3(4) − 10| = |2| = 2 and 4 − 2 = 2.","lvl": 1,"choices": ["No, because |3(4) − 10| = 22 and 4 − 2 = 2.","No, because x = 4 makes the right side zero.","Yes, because |3(4) − 10| = |2| = 2 and 4 − 2 = 2.","Yes, because 3(4) − 10 = 4 + 2."],"steps": ["Substitute x = 4 into the left side: |3(4) − 10| = |12 − 10| = 2.","Substitute x = 4 into the right side: 4 − 2 = 2.","Are they equal?"]},{"id": "AlgI.8-11","std": "Alg I.8","q": "Solve the equation |2x + 3| = x + 6 and identify any extraneous solutions.","a": "x = 3 and x = −3 are both valid solutions; there are no extraneous solutions.","lvl": 2,"choices": ["x = −3 is valid, and x = 3 is extraneous.","x = 3 is valid, and x = −3 is extraneous.","x = 3 and x = −3 are both valid solutions; there are no extraneous solutions.","Both x = 3 and x = −3 are extraneous."],"steps": ["Solve 2x + 3 = x + 6 (gives x = 3) and 2x + 3 = −(x + 6) (gives x = −3).","Check x = 3: |9| = 9 (true). Check x = −3: |−3| = 3 (true).","Did either check fail?"]},{"id": "AlgI.8-12","std": "Alg I.8","q": "When solving |x − 4| = 3x − 8, a student sets up two equations: x − 4 = 3x − 8 and x − 4 = −(3x − 8), getting x = 2 and x = 3. Which candidate solution is extraneous?","a": "x = 2 is extraneous because 3(2) − 8 = −2, and an absolute value cannot equal a negative number.","lvl": 2,"choices": ["x = 2 is extraneous because 3(2) − 8 = −2, and an absolute value cannot equal a negative number.","Both x = 2 and x = 3 are extraneous solutions.","x = 3 is extraneous because |3 − 4| = −1.","Both x = 2 and x = 3 are valid solutions."],"steps": ["Test x = 2 in |x − 4| = 3x − 8: |−2| = 2, but 3(2) − 8 = −2.","Test x = 3: |3 − 4| = 1 and 3(3) − 8 = 1 (valid).","Which one made the right side negative?"]},{"id": "AlgI.8-13","std": "Alg I.8","q": "Find all valid solutions to |3x − 2| = 2x + 3.","a": "x = 5 and x = −{1/5}","lvl": 2,"choices": ["x = 5 only (−{1/5} is extraneous)","x = −{1/5} only (5 is extraneous)","x = 5 and x = −{1/5}","x = 5 and x = {1/5}"],"steps": ["Split into 3x − 2 = 2x + 3 and 3x − 2 = −(2x + 3).","Solve each equation for x.","Check that 2x + 3 ≥ 0 for each value."]},{"id": "AlgI.8-14","std": "Alg I.8","q": "Why can extraneous solutions show up when you solve |ax + b| = cx + d by splitting it into two equations?","a": "A candidate can make cx + d negative, but an absolute value can never be negative","lvl": 3,"choices": ["Splitting the equation changes the slope of the line","Absolute value equations always have two answers, so one is always extra","Extraneous solutions only come from dividing by zero","A candidate can make cx + d negative, but an absolute value can never be negative"],"steps": ["An absolute value |ax + b| is always ≥ 0, so cx + d must also be ≥ 0.","Splitting into two linear equations ignores the condition cx + d ≥ 0.","What if a candidate makes cx + d negative?"]},{"id": "AlgI.8-15","std": "Alg I.8","q": "Solve |4x − 1| = 2x − 5. Test your candidate solutions.","a": "No solution: both candidates (x = −2 and x = 1) make 2x − 5 negative","lvl": 3,"choices": ["x = −2 and x = 1","No solution: both candidates (x = −2 and x = 1) make 2x − 5 negative","x = −2 only","x = 1 only"],"steps": ["Solve 4x − 1 = 2x − 5 (x = −2) and 4x − 1 = −2x + 5 (x = 1).","Check x = −2: |−9| = −9 (false). Check x = 1: |3| = −3 (false).","Did any candidate pass?"]},{"id": "AlgI.8-16","std": "Alg I.8","q": "Without solving, how can you tell that any solution to |5x + 2| = 4x − 12 must have x ≥ 3?","a": "|5x + 2| is never negative, so 4x − 12 ≥ 0, which gives x ≥ 3","lvl": 3,"choices": ["The left side is always bigger than the right side","12 ÷ 4 = 3, and that is always the solution","5x + 2 must be positive, which gives x ≥ 3","|5x + 2| is never negative, so 4x − 12 ≥ 0, which gives x ≥ 3"],"steps": ["Because |5x + 2| ≥ 0 for all x, the right side 4x − 12 must be ≥ 0.","Set up the inequality 4x − 12 ≥ 0 and add 12 to both sides.","Solve 4x − 12 ≥ 0."]},{"id": "AlgI.9-11","std": "Alg I.9","q": "Solve by taking square roots: x² = 81","a": "x = 9 and x = −9","lvl": 1,"part": "b","choices": ["x = 9 and x = −9","x = 81 and x = −81","x = 40.5","x = 9 only"],"steps": ["Take the square root of both sides of x² = 81.","Remember to include both the positive and negative roots: ±√81.","What is √81? Write both solutions."]},{"id": "AlgI.9-12","std": "Alg I.9","q": "Solve by factoring: (x − 6)(x + 2) = 0","a": "x = 6 and x = −2","lvl": 1,"part": "b","choices": ["x = 6 and x = −2","x = −6 and x = 2","x = 6 and x = 2","x = −6 and x = −2"],"steps": ["Use the Zero Product Property: set each factor equal to 0.","Write x − 6 = 0 and x + 2 = 0.","Solve each equation."]},{"id": "AlgI.9-13","std": "Alg I.9","q": "What number should be added to both sides of x² + 10x = 11 to complete the square?","a": "25","lvl": 1,"part": "a","choices": ["5","10","25","100"],"steps": ["To complete the square for x² + bx, take half of b and square it.","Here b = 10, so half of 10 is 5.","Square that half."]},{"id": "AlgI.9-14","std": "Alg I.9","q": "Rewrite the equation x² − 6x − 7 = 0 in the form (x − p)² = q by completing the square.","a": "(x − 3)² = 16","lvl": 2,"part": "a","choices": ["(x + 3)² = 16","(x − 6)² = 43","(x − 3)² = 16","(x − 3)² = 7"],"steps": ["Move the constant to the right side: x² − 6x = 7.","Half of −6 is −3, and (−3)² = 9; add 9 to both sides.","Factor the left side. Add on the right."]},{"id": "AlgI.9-15","std": "Alg I.9","q": "Solve the quadratic equation 2x² + 5x − 3 = 0.","a": "x = {1/2} and x = −3","lvl": 2,"part": "b","choices": ["x = −{1/2} and x = 3","x = 1 and x = −6","x = {1/2} and x = −3","x = 2 and x = −3"],"steps": ["Factor 2x² + 5x − 3 = 0 into (2x − 1)(x + 3) = 0.","Set each factor equal to 0: 2x − 1 = 0 and x + 3 = 0.","Solve each equation."]},{"id": "AlgI.9-16","std": "Alg I.9","q": "Solve (x + 2)² = −9 and write the solutions in complex form a ± bi.","a": "x = −2 ± 3i","lvl": 2,"part": "b","choices": ["x = −2 ± 9i","No solution","x = −2 ± 3i","x = 2 ± 3i"],"steps": ["Take the square root of both sides: x + 2 = ±√(−9).","Simplify √(−9) using i to get x + 2 = ±3i.","Subtract 2 from both sides."]},{"id": "AlgI.9-17","std": "Alg I.9","q": "Solve (A) 3(x − 4)² = 27 and (B) 2x² − 7x + 1 = 0 using the best method for each.","a": "A by square roots: x = 7 and x = 1; B by the quadratic formula: x = {7 ± √41/4}","lvl": 3,"part": "b","choices": ["A by square roots: x = 13 and x = −5; B by the quadratic formula: x = {7 ± √41/4}","A by square roots: x = 7 and x = 1; B by the quadratic formula: x = {7 ± √57/4}","A by square roots: x = 7 and x = 1; B by the quadratic formula: x = {−7 ± √41/4}","A by square roots: x = 7 and x = 1; B by the quadratic formula: x = {7 ± √41/4}"],"steps": ["For A, divide by 3, then take square roots.","For B, use the quadratic formula with a = 2, b = −7, c = 1.","Find b² − 4ac and put it in the formula."]},{"id": "AlgI.9-18","std": "Alg I.9","q": "A student is deriving the quadratic formula from ax² + bx + c = 0 (with a ≠ 0). After dividing by a and moving {c/a} to the right side, the student has x² + ({b/a})x = −{c/a}. What term must be added to both sides next to complete the square?","a": "{b²/4a²}","lvl": 3,"part": "a","choices": ["{b²/4a²}","{b/2a}","{b²/2a}","{b²/a²}"],"steps": ["Identify the coefficient of x, which is {b/a}.","Take half of {b/a} to get {b/2a}.","Square that. That is the term to add."]},{"id": "AlgI.9-19","std": "Alg I.9","q": "Solve 3x² − 2x + 4 = 0 using the quadratic formula. Write the solutions in the form a ± bi.","a": "x = {1/3} ± {√11/3}i","lvl": 3,"part": "b","choices": ["x = {1/3} ± {√11/3}i","x = {1/3} ± {√13/3}","x = −{1/3} ± {√11/3}i","x = 1 ± √11 i"],"steps": ["Use the quadratic formula with a = 3, b = −2, c = 4.","Find b² − 4ac. It is negative, so use i.","Simplify. Divide each part by 2."]},{"id": "AlgI.10-09","std": "Alg I.10","q": "Solve the system using linear combinations (elimination): x + y = 12 and x − y = 2","a": "(7, 5)","lvl": 1,"part": "a","choices": ["(6, 6)","(7, 5)","(14, 10)","(5, 7)"],"steps": ["Add the two equations to eliminate y: 2x = 14.","Divide both sides by 2 to find x.","Plug x into x + y = 12 to find y."]},{"id": "AlgI.10-10","std": "Alg I.10","q": "For which system of equations is substitution the most efficient method without rewriting either equation first?","a": "y = 4x − 1 and 3x + 2y = 20","lvl": 1,"part": "a","choices": ["3x + 5y = 19 and 2x − 5y = 6","y = 4x − 1 and 3x + 2y = 20","4x + 7y = 15 and 4x − 3y = 5","2x + 3y = 12 and 5x − 2y = 11"],"steps": ["Substitution is fastest when one variable is already alone.","Look for an equation that starts with y = or x =.","Which choice has one?"]},{"id": "AlgI.10-11","std": "Alg I.10","q": "Two lines are graphed on a coordinate plane and intersect at the point (−2, 5). What is the solution to the system of equations represented by the lines?","a": "(−2, 5)","lvl": 1,"part": "b","choices": ["(−2, 5)","y = 5 only","(5, −2)","x = −2 only"],"steps": ["The solution to a graphed system is where the lines cross.","Write that point as (x, y).","Which choice matches the crossing point?"]},{"id": "AlgI.10-12","std": "Alg I.10","q": "Solve the system of equations:\n3x + 2y = 16\n5x − 4y = 12","a": "(4, 2)","lvl": 2,"part": "a","choices": ["(4, 2)","(4, −2)","(2, 5)","(2, 4)"],"steps": ["Multiply 3x + 2y = 16 by 2 to get 6x + 4y = 32.","Add that to 5x − 4y = 12 to eliminate y. Solve for x.","Plug x into 3x + 2y = 16 to find y."]},{"id": "AlgI.10-13","std": "Alg I.10","q": "A table of values for two linear functions f(x) and g(x) shows that at x = 3, f(3) = 7 and g(3) = 7. At x = 4, f(4) = 9 and g(4) = 5. What does this tell you about the solution to the system y = f(x) and y = g(x)?","a": "The system has a unique solution at (3, 7).","lvl": 2,"part": "b","choices": ["The system has no solution.","The system has infinitely many solutions.","The system has a unique solution at (3, 7).","The system has a unique solution at (4, 9)."],"steps": ["At x = 3, both functions give y = 7, so (3, 7) is a solution.","At x = 4, the outputs differ (9 vs. 5), so the lines are not identical.","So how many solutions does the system have, and where?"]},{"id": "AlgI.10-14","std": "Alg I.10","q": "Solve the system:\n4x − 6y = 10\n−2x + 3y = −5","a": "Infinitely many solutions","lvl": 2,"part": "a","choices": ["(2.5, 0)","No solution","(0, 0)","Infinitely many solutions"],"steps": ["Multiply the second equation by −2: 4x − 6y = 10.","Notice both equations are identical, representing the same line.","How many solutions does one line with itself have?"]},{"id": "AlgI.10-15","std": "Alg I.10","q": "A student graphs y = 2.4x + 1.1 and y = −1.5x + 8.9 by hand and estimates the solution as (2, 6). Use algebra to find the exact solution.","a": "(2, 5.9)","lvl": 3,"part": "b","choices": ["(2, 6)","(2, 5.9)","(7.8, 19.82)","(3.9, 10.46)"],"steps": ["Set the equations equal: 2.4x + 1.1 = −1.5x + 8.9.","Collect x terms: 3.9x = 7.8. Solve for x.","Plug x into either equation to find the exact y."]},{"id": "AlgI.10-16","std": "Alg I.10","q": "System 1: 7x + 4y = 23 and 3x − 4y = 17. System 2: y = 3x − 5 and 2x + 5y = 26. Pick the faster method for each system and solve.","a": "Linear combinations for System 1: (4, −1.25); substitution for System 2: (3, 4)","lvl": 3,"part": "a","choices": ["Linear combinations for System 1: (4, −1.25); substitution for System 2: (4, 7)","Linear combinations for System 1: (4, −1.25); substitution for System 2: (3, 4)","Linear combinations for System 1: (2, 2.25); substitution for System 2: (3, 4)","Substitution for System 1: (4, 1.25); linear combinations for System 2: (3, 4)"],"steps": ["System 1 has +4y and −4y. Add the equations to eliminate y.","System 2 has y alone. Plug y = 3x − 5 into 2x + 5y = 26.","Solve each system, then match both methods and answers to a choice."]},{"id": "AlgI.10-17","std": "Alg I.10","q": "A table of x = 0 to 5 for two linear equations shows no matching y-values, but the lines have different slopes. Why did the table miss the solution?","a": "The lines cross outside x = 0 to 5 or between whole numbers; set the equations equal to find it","lvl": 3,"part": "b","choices": ["The lines cross outside x = 0 to 5 or between whole numbers; set the equations equal to find it","Lines with different slopes never cross","The lines are parallel, so there is no solution","Every system shows its solution in a table, so the table has a mistake"],"steps": ["Lines with different slopes must intersect at exactly one point.","A table of integers 0 to 5 misses solutions outside 0–5 or non-integers.","Pick the choice that explains where the crossing could be hiding."]},{"id": "AlgI.11-10","std": "Alg I.11","q": "Elena has §45 and saves §12 per week to buy a bicycle that costs §165. Which equation can be used to find w, the number of weeks it will take her to save enough money?","a": "45 + 12w = 165","lvl": 1,"choices": ["45w + 12 = 165","57w = 165","12w − 45 = 165","45 + 12w = 165"],"steps": ["Start with Elena's initial savings of 45.","Add 12w for saving 12 per week for w weeks.","Set that total equal to the bike's cost."]},{"id": "AlgI.11-11","std": "Alg I.11","q": "A delivery truck can carry at most 2,500 pounds. It already holds a 700-pound crate, and the driver wants to load boxes that weigh 60 pounds each. Which inequality represents the number of boxes, b, the driver can load?","a": "700 + 60b ≤ 2500","lvl": 1,"choices": ["700 + 60b ≥ 2500","700 + 60b ≤ 2500","700 + 60b < 2500","760b ≤ 2500"],"steps": ["Add the 700-pound crate and 60b for b boxes.","At most 2,500 means less than or equal to 2,500.","Write the inequality with ≤."]},{"id": "AlgI.11-12","std": "Alg I.11","q": "A culture of 100 bacteria doubles every hour. Which equation models the time t in hours when the population reaches 3,200?","a": "100(2)^t = 3200","lvl": 1,"choices": ["100 + 2t = 3200","100t² = 3200","100(2)^t = 3200","200^t = 3200"],"steps": ["Use exponential growth: initial × (growth factor)^{t}.","Substitute initial = 100 and factor = 2: 100(2)^{t}.","Set that expression equal to 3,200."]},{"id": "AlgI.11-13","std": "Alg I.11","q": "A rectangular garden has a length that is 5 meters longer than its width w. If the area of the garden is 84 square meters, write and solve an equation to find the width of the garden.","a": "w(w + 5) = 84; width = 7 meters","lvl": 2,"choices": ["w(w + 5) = 84; width = 12 meters","w² + 5 = 84; width = 8.9 meters","w(w + 5) = 84; width = 7 meters","2w + 2(w + 5) = 84; width = 18.5 meters"],"steps": ["Write area as width × length: w(w + 5) = 84.","Rewrite as w² + 5w − 84 = 0 and factor: (w + 12)(w − 7) = 0.","Width must be positive. Which factor gives the width?"]},{"id": "AlgI.11-14","std": "Alg I.11","q": "A machine fills bags of flour with a target weight of 500 grams. Bags are acceptable if their actual weight w is within 4 grams of the target weight. Which inequality represents all acceptable weights?","a": "|w − 500| ≤ 4","lvl": 2,"choices": ["|w + 500| ≤ 4","|w − 500| ≤ 4","|w − 500| ≥ 4","|w − 4| ≤ 500"],"steps": ["Express distance from 500 grams as |w − 500|.","Within 4 grams means less than or equal to 4.","Write the inequality with ≤."]},{"id": "AlgI.11-15","std": "Alg I.11","q": "A car purchased for §20,000 loses 10% of its value each year. Which equation can be solved to find the number of years t until the car is worth §14,580?","a": "20000(0.9)^t = 14580","lvl": 2,"choices": ["20000 − 0.1t = 14580","20000(1.1)^t = 14580","20000(0.9)^t = 14580","20000(0.1)^t = 14580"],"steps": ["Losing 10% each year leaves 1 − 0.10 = 0.9 of the value.","Value after t years: 20000(0.9)^{t}.","Set that expression equal to the target value."]},{"id": "AlgI.11-16","std": "Alg I.11","q": "A rocket's height is h = −16t² + 96t + 40 (feet, t seconds). When is the rocket 148 feet high?","a": "t = 1.5 s on the way up and t = 4.5 s on the way down","lvl": 3,"choices": ["t = 1.5 s only, because it can't be at 148 feet twice","t = 3 s on the way up and t = 6 s on the way down","t = 1.5 s on the way up and t = 4.5 s on the way down","t = 4.5 s only, on the way down"],"steps": ["Set −16t² + 96t + 40 = 148, so 16t² − 96t + 108 = 0.","Divide by 4: 4t² − 24t + 27 = 0; factor (2t − 3)(2t − 9) = 0.","Solve each factor for t. Which is going up, and which coming down?"]},{"id": "AlgI.11-17","std": "Alg I.11","q": "A metal rod is cut to a length of 24 cm, but any rod whose length L differs from 24 cm by more than 0.15 cm must be rejected. Write an absolute value inequality representing the lengths of rejected rods and solve it.","a": "|L − 24| > 0.15; L < 23.85 cm or L > 24.15 cm","lvl": 3,"choices": ["|L − 24| > 0.15; L < 23.85 cm or L > 24.15 cm","|L − 24| < 0.15; 23.85 < L < 24.15","|L + 24| > 0.15; L > −23.85 cm","|L − 0.15| > 24; L > 24.15 cm"],"steps": ["Differs from 24 by more than 0.15: |L − 24| > 0.15.","Split into L − 24 < −0.15 or L − 24 > 0.15.","Add 24 to both sides of each part."]},{"id": "AlgI.11-18","std": "Alg I.11","q": "Hall A charges §300 plus §8 per student. Hall B charges a flat §1,100 for up to 150 students. For how many students n (up to 150) is Hall B cheaper?","a": "n > 100, so 101 to 150 students","lvl": 3,"choices": ["n > 100, so 101 to 150 students","n > 175, so Hall B is never cheaper","n < 100, so fewer than 100 students","n > 137.5, so 138 to 150 students"],"steps": ["Set Hall B cost less than Hall A: 1100 < 300 + 8n.","Subtract 300: 800 < 8n, then divide by 8: n > 100.","n must be a whole number up to 150. Which counts work?"]},{"id": "AlgI.12-08","std": "Alg I.12","q": "A plumber charges a §65 service fee plus §45 per hour. Write an equation for the total cost C after h hours of work.","a": "C = 45h + 65","lvl": 1,"choices": ["C = 65h + 45","C = 45h − 65","C = 45h + 65","C = 110h"],"steps": ["Identify the fixed fee (65) and hourly rate (45h).","Combine them to model total cost C.","Write C as the hourly part plus the fixed fee."]},{"id": "AlgI.12-09","std": "Alg I.12","q": "A streaming service starts with 5,000 subscribers and triples its subscribers every year. Which equation models the number of subscribers S after t years?","a": "S = 5000(3)^t","lvl": 1,"choices": ["S = 5000 + 3t","S = 5000t³","S = 3(5000)^t","S = 5000(3)^t"],"steps": ["Start with 5,000 subscribers. Tripling means a factor of 3.","Exponential growth: S = initial × (factor)^{t}.","Put the initial value and factor into that form."]},{"id": "AlgI.12-10","std": "Alg I.12","q": "Using the equation y = 15x + 20, where x is the number of shirts ordered and y is the total cost in dollars, predict the total cost for ordering 8 shirts.","a": "§140","lvl": 1,"choices": ["§120","§140","§175","§280"],"steps": ["Substitute x = 8 into y = 15x + 20.","Multiply: 15 × 8 = 120.","Now add 20."]},{"id": "AlgI.12-11","std": "Alg I.12","q": "A diver jumps from a platform 10 meters above a pool. Her height h in meters after t seconds is modeled by h = −4.9t² + 3t + 10. If you graph this equation on a coordinate plane with t on the horizontal axis, what are the coordinates of the vertical intercept and what does it mean?","a": "(0, 10); at t = 0 seconds, the diver is 10 meters above the water.","lvl": 2,"choices": ["(10, 0); it takes 10 seconds to reach the water.","(0, −4.9); the diver starts 4.9 meters below the platform.","(0, 10); at t = 0 seconds, the diver is 10 meters above the water.","(0, 3); the diver starts 3 meters above the water."],"steps": ["Find the vertical intercept by setting t = 0.","Evaluate h = −4.9(0)² + 3(0) + 10 = 10, giving (0, 10).","What does h mean at t = 0?"]},{"id": "AlgI.12-12","std": "Alg I.12","q": "A car drives toward a city that is 180 miles away at a constant speed of 60 miles per hour, passes through the city, and continues driving away at the same speed. Which equation models the car's distance d in miles from the city after t hours?","a": "d = |180 − 60t|","lvl": 2,"choices": ["d = |60 − 180t|","d = 180 + 60t","d = |180 − 60t|","d = 180 − 60t"],"steps": ["Before the city, the car is 180 − 60t miles away.","After it passes the city, 180 − 60t turns negative.","Distance can't be negative. What symbol fixes that?"]},{"id": "AlgI.12-13","std": "Alg I.12","q": "When graphing the equation P = 250(1.2)^t for t from 0 to 10 years, which scale for the vertical P-axis is most appropriate to show all points clearly without crowding?","a": "0 to 1,600 with intervals of 200","lvl": 2,"choices": ["0 to 1,600 with intervals of 200","0 to 300 with intervals of 25","0 to 10,000 with intervals of 2,500","0 to 50 with intervals of 5"],"steps": ["Evaluate P at t = 0: P = 250(1.2)⁰ = 250.","Evaluate P at t = 10: P = 250(1.2)¹⁰ ≈ 1,548.","Which scale covers 250 to about 1,548 without crowding?"]},{"id": "AlgI.12-14","std": "Alg I.12","q": "A garage charges §5 for up to 1 hour, §9 for more than 1 and up to 2 hours, and §12 for more than 2 and up to 3 hours. What does the graph look like, and what does 2.4 hours cost?","a": "Three flat steps at 5, 9 and 12 (open circle on the left end, closed on the right); §12","lvl": 3,"choices": ["Three flat steps at 5, 9 and 12 (open circle on the left end, closed on the right); §12","A smooth curve that rises faster each hour; §10.80","A straight line through (0, 0) rising §4 per hour; §9.60","Three flat steps at 5, 9 and 12 (open circle on the left end, closed on the right); §9"],"steps": ["Draw horizontal segments at y = 5, y = 9, and y = 12.","Use open circles on left ends and closed on right ends.","2.4 hours is more than 2 and up to 3. Which step is that?"]},{"id": "AlgI.12-15","std": "Alg I.12","q": "A farmer has 120 feet of fencing for a rectangular pen against a barn (two widths x and one length). Which area equation and vertex are correct?","a": "A = x(120 − 2x); vertex (30, 1,800): a 30-foot width gives the most area, 1,800 square feet","lvl": 3,"choices": ["A = x(120 − x); vertex (60, 3,600): a 60-foot width gives the most area, 3,600 square feet","A = x(120 − 2x); vertex (60, 0): a 60-foot width gives the most area","A = x(120 − 2x); vertex (30, 1,800): a 30-foot width gives the most area, 1,800 square feet","A = x(60 − x); vertex (30, 900): a 30-foot width gives the most area, 900 square feet"],"steps": ["Length is 120 − 2x, so A = x(120 − 2x) = −2x² + 120x.","Find the vertex: x = −b ÷ (2a).","Plug that x into A to find the greatest area."]},{"id": "AlgI.12-16","std": "Alg I.12","q": "A town's population was 8,000 in 2015 and 9,680 in 2017. Assuming exponential growth of the form P = a(b)^t where t is years since 2015, write the equation modeling the population and predict the population in 2020.","a": "P = 8000(1.1)^t; in 2020 (t = 5), the predicted population is about 12,884.","lvl": 3,"choices": ["P = 8000(1.1)^t; in 2020 (t = 5), the predicted population is about 12,884.","P = 8000(0.9)^t; in 2020 (t = 5), the predicted population is about 4,724.","P = 8000(1.21)^t; in 2020 (t = 5), the predicted population is about 20,750.","P = 8000 + 840t; in 2020 (t = 5), the predicted population is 12,200."],"steps": ["Use 9680 = 8000b², so b² = 1.21 and b = 1.1.","Write the model: P = 8000(1.1)^{t}.","For 2020, t = 5. Find 8000(1.1)⁵."]},{"id": "AlgI.13-09","std": "Alg I.13","q": "A baker is making x loaves of bread and y batches of muffins. Each loaf requires 3 cups of flour, and each batch of muffins requires 2 cups of flour. The baker has 30 cups of flour available. Which inequality represents this constraint?","a": "3x + 2y ≤ 30","lvl": 1,"choices": ["5(x + y) ≤ 30","3x + 2y ≥ 30","3x + 2y ≤ 30","2x + 3y ≤ 30"],"steps": ["Total flour used is 3x for loaves plus 2y for muffins.","Only 30 cups are available, so use ≤ 30.","Write the inequality with ≤."]},{"id": "AlgI.13-10","std": "Alg I.13","q": "In a problem where x represents the number of bicycles produced by a factory, which solution is nonviable in context?","a": "x = −4","lvl": 1,"choices": ["x = 0","x = 15","x = 120","x = −4"],"steps": ["The number of bicycles x must be 0 or positive.","Check the choices for a negative value.","Which choice is negative?"]},{"id": "AlgI.13-11","std": "Alg I.13","q": "A club sells student tickets (s) for §5 and adult tickets (a) for §8. They want to raise at least §400. Which inequality represents this goal?","a": "5s + 8a ≥ 400","lvl": 1,"choices": ["5s + 8a ≤ 400","5s + 8a ≥ 400","8s + 5a ≥ 400","5s + 8a > 400"],"steps": ["Total money raised is 5s + 8a.","At least 400 means greater than or equal to 400.","Write the inequality with ≥."]},{"id": "AlgI.13-12","std": "Alg I.13","q": "Marcus has at most §50 to spend on x notebooks at §4 each and y pens at §2 each. He must buy at least 5 notebooks. Which system of inequalities models his constraints?","a": "4x + 2y ≤ 50 and x ≥ 5","lvl": 2,"choices": ["4x + 2y ≥ 50 and x ≤ 5","4x + 2y ≤ 50 and y ≥ 5","4x + 2y ≤ 50 and x ≥ 5","2x + 4y ≤ 50 and x > 5"],"steps": ["At most 50 dollars gives 4x + 2y ≤ 50.","At least 5 notebooks gives x ≥ 5.","Put both inequalities together as a system."]},{"id": "AlgI.13-13","std": "Alg I.13","q": "A theater has 200 seats. Ticket prices are §10 for children (c) and §15 for adults (a). The theater needs at least §2,400 in ticket sales to cover costs. Which combination of (c, a) is a viable solution?","a": "(80, 110)","lvl": 2,"choices": ["(100, 90)","(80, 110)","(40, 180)","(150, 50)"],"steps": ["The rules: c + a ≤ 200 and 10c + 15a ≥ 2400.","Test each choice in c + a ≤ 200.","Test the ones that pass in 10c + 15a ≥ 2400."]},{"id": "AlgI.13-14","std": "Alg I.13","q": "A projectile's height in feet after t seconds is given by h = −16t² + 64t. Solving −16t² + 64t = 0 gives t = 0 and t = 4. If the projectile is launched at t = 0, why is t = −1 nonviable even though it produces a number in the formula?","a": "Time t represents seconds after launch, so negative time values before the launch do not apply to the real-world event.","lvl": 2,"choices": ["At t = −1, the height is positive.","The formula cannot be evaluated for negative numbers.","Time t represents seconds after launch, so negative time values before the launch do not apply to the real-world event.","The projectile hits the ground at t = −1."],"steps": ["Time t measures seconds after launch at t = 0.","A value like t = −1 represents time before launch.","Does time before launch fit this situation?"]},{"id": "AlgI.13-15","std": "Alg I.13","q": "A landscaper buys x bags of mulch at §6 and y bags of topsoil at §8. Her budget is §120, she needs at least 16 bags total and at least 4 bags of topsoil. Is 12 bags of mulch and 5 bags of topsoil viable?","a": "Yes: 6(12) + 8(5) = 112 ≤ 120, 12 + 5 = 17 ≥ 16, and 5 ≥ 4","lvl": 3,"choices": ["No: she spends §112, which is less than §120","No: 12 + 5 = 17 bags is more than 16","Yes: 6(12) + 8(5) = 112 ≤ 120, 12 + 5 = 17 ≥ 16, and 5 ≥ 4","No: she needs at least 16 bags of topsoil"],"steps": ["System: 6x + 8y ≤ 120, x + y ≥ 16, y ≥ 4, x ≥ 0.","Test (12, 5): 6(12) + 8(5) = 112 ≤ 120 and 12 + 5 = 17.","Check the other two rules: 17 ≥ 16 and 5 ≥ 4. Viable?"]},{"id": "AlgI.13-16","std": "Alg I.13","q": "A drone company's limits are y ≤ −2x + 20 (battery) and y ≥ 0.5x + 5 (payload), with x in miles and y in pounds. The boundary lines cross at (6, 8). Is (6, 8) viable? Is 8.5 pounds at 6 miles viable?","a": "(6, 8) is viable because the boundaries count (≤ and ≥); 8.5 pounds is not, because 8.5 > −2(6) + 20 = 8","lvl": 3,"choices": ["(6, 8) is viable because the boundaries count (≤ and ≥); 8.5 pounds is not, because 8.5 > −2(6) + 20 = 8","Both are viable because 8.5 ≥ 0.5(6) + 5 = 8","Neither is viable because 6 miles is too far","(6, 8) is not viable because boundaries never count; 8.5 pounds is viable"],"steps": ["Both inequalities use ≤ and ≥, so (6, 8) is viable.","At x = 6, battery limit is y ≤ −2(6) + 20 = 8.","Is 8.5 within the battery limit? Is (6, 8) on the boundary?"]},{"id": "AlgI.13-17","std": "Alg I.13","q": "Attendance is A = 500 − 10p for ticket price p. For at least §6,000 in revenue, p(500 − 10p) ≥ 6000 gives 20 ≤ p ≤ 30. The venue holds only 250 people (A ≤ 250). What are the viable prices now?","a": "25 ≤ p ≤ 30","lvl": 3,"choices": ["25 ≤ p ≤ 30","20 ≤ p ≤ 25","20 ≤ p ≤ 30 (no change)","p ≥ 25 with no upper limit"],"steps": ["Set attendance ≤ 250: 500 − 10p ≤ 250.","Solve: −10p ≤ −250, so p ≥ 25.","Keep only the prices that fit both 20 ≤ p ≤ 30 and p ≥ 25."]},{"id": "AlgI.14-08","std": "Alg I.14","q": "Which point lies on the graph of the equation y = 3x − 4?","a": "(2, 2)","lvl": 1,"choices": ["(2, 2)","(−1, −1)","(0, 4)","(2, 10)"],"steps": ["Test each point in y = 3x − 4.","For (2, 2): find 3(2) − 4.","Which point makes the equation true?"]},{"id": "AlgI.14-09","std": "Alg I.14","q": "The point (3, 5) is on the graph of an equation in x and y. What does that tell you?","a": "x = 3 and y = 5 make the equation true","lvl": 1,"choices": ["The graph must be a straight line","x = 5 and y = 3 make the equation true","The equation has only one solution","x = 3 and y = 5 make the equation true"],"steps": ["Each point (x, y) on a graph is a solution pair.","The full graph includes every pair making the equation true.","So what do x = 3 and y = 5 do to the equation?"]},{"id": "AlgI.14-10","std": "Alg I.14","q": "Does the point (−3, 9) lie on the graph of the equation y = x²?","a": "Yes, because 9 = (−3)²","lvl": 1,"choices": ["Yes, because 9 = −3 × 3","Yes, because 9 = (−3)²","No, because (−3)² = −9","No, because x cannot be negative"],"steps": ["Plug x = −3 into y = x².","(−3)² means (−3) × (−3).","Does that equal 9?"]},{"id": "AlgI.14-11","std": "Alg I.14","q": "The point (4, k) lies on the graph of the relation 2x + 3y = 20. What is the value of k?","a": "4","lvl": 2,"choices": ["2.67","4","6","12"],"steps": ["Plug x = 4 and y = k into 2x + 3y = 20.","Simplify: 8 + 3k = 20.","Subtract 8, then divide by 3."]},{"id": "AlgI.14-12","std": "Alg I.14","q": "Which equation has a graph that passes through all three points: (−1, 3), (0, 2), and (2, 6)?","a": "y = x² + 2","lvl": 2,"choices": ["y = 2x + 2","y = −x + 2","y = x² + 2","y = x² − 2"],"steps": ["Test each point in each equation.","Start with (0, 2). Which equations give y = 2 at x = 0?","Test (−1, 3) and (2, 6) in the ones that are left."]},{"id": "AlgI.14-13","std": "Alg I.14","q": "The graph of x² + y² = 25 is a circle centered at the origin with radius 5. Which of the following points is on this graph?","a": "(−3, 4)","lvl": 2,"choices": ["(5, 5)","(−3, 4)","(−4, −4)","(2, 3)"],"steps": ["A point is on the circle if x² + y² = 25.","Test each choice: square x, square y, and add.","Which point gives exactly 25?"]},{"id": "AlgI.14-14","std": "Alg I.14","q": "Jada says that because (1, 4) and (3, 10) are on the graph of a relation, the graph must be the line y = 3x + 1. Which response is correct?","a": "Not necessarily: y = x² − x + 4 also passes through both points","lvl": 3,"choices": ["Not necessarily: y = x² + 3 also passes through both points","She is wrong: y = 3x + 1 does not pass through (3, 10)","Not necessarily: y = x² − x + 4 also passes through both points","She is right: only one graph can pass through two points"],"steps": ["Two points determine a unique line, not a unique curve.","Check y = x² − x + 4: at x = 1, y = 4; at x = 3, y = 10.","So must the graph be that line?"]},{"id": "AlgI.14-15","std": "Alg I.14","q": "For what value of c will the graph of the equation y = 2x² + cx − 5 pass through the point (−2, 9)?","a": "−3","lvl": 3,"choices": ["−11","−3","3","11"],"steps": ["Substitute (−2, 9): 9 = 2(−2)² + c(−2) − 5.","Simplify: 9 = 8 − 2c − 5, so 9 = 3 − 2c.","Solve 9 = 3 − 2c for c."]},{"id": "AlgI.14-16","std": "Alg I.14","q": "Why does the graph of y = 2^x never touch the x-axis, even for negative x?","a": "2^x is always positive, so y is never 0 (for example, 2⁻¹⁰ = {1/1024})","lvl": 3,"choices": ["2^x is negative for negative x, so the graph stays below the axis","The graph stops at x = 0","It does touch it: 2^x = 0 when x = −1","2^x is always positive, so y is never 0 (for example, 2⁻¹⁰ = {1/1024})"],"steps": ["The x-axis is where y = 0.","For any real x, 2^{x} is always strictly positive (> 0).","Can 2^{x} ever equal 0?"]},{"id": "AlgI.15-10","std": "Alg I.15","q": "Given the function f(x) = 4x − 7, what is the value of f(5)?","a": "13","lvl": 1,"choices": ["−3","3","13","27"],"steps": ["Substitute x = 5 into f(x) = 4x − 7.","Multiply: 4 × 5 = 20.","Now subtract 7."]},{"id": "AlgI.15-11","std": "Alg I.15","q": "Let H(t) represent the height of a plant in centimeters t days after planting. What does the statement H(14) = 22 mean in context?","a": "After 14 days, the plant is 22 centimeters tall.","lvl": 1,"choices": ["After 22 days, the plant is 14 centimeters tall.","After 14 days, the plant is 22 centimeters tall.","The plant grows 14 centimeters every 22 days.","The plant starts at 14 centimeters and grows 22 centimeters per day."],"steps": ["Input t = 14 means 14 days after planting.","Output H(14) = 22 means height is 22 centimeters.","Pick the choice that matches 14 days and 22 centimeters."]},{"id": "AlgI.15-12","std": "Alg I.15","q": "Find the range of the function f(x) = 2x + 1 for the domain {0, 1, 2, 3}.","a": "{1, 3, 5, 7}","lvl": 1,"choices": ["{1, 2, 3, 4}","{1, 3, 5, 7}","{0, 1, 2, 3}","{2, 4, 6, 8}"],"steps": ["Plug each domain value, 0, 1, 2 and 3, into 2x + 1.","Start with 2(0) + 1, then 2(1) + 1.","List all four outputs. That list is the range."]},{"id": "AlgI.15-13","std": "Alg I.15","q": "Given g(x) = x² − 3x + 2, find g(−4).","a": "30","lvl": 2,"choices": ["−26","−2","6","30"],"steps": ["Substitute x = −4: g(−4) = (−4)² − 3(−4) + 2.","Evaluate powers and products: 16 + 12 + 2.","Add the three numbers."]},{"id": "AlgI.15-14","std": "Alg I.15","q": "A canoe rental shop charges a §15 deposit plus §10 per hour for up to 6 hours, modeled by C(h) = 10h + 15. What is a realistic domain for C(h) in this context?","a": "0 ≤ h ≤ 6","lvl": 2,"choices": ["All real numbers","0 ≤ h ≤ 6","15 ≤ h ≤ 75","h ≥ 0"],"steps": ["Domain is the set of valid inputs h (hours rented).","Hours cannot be negative and are at most 6.","Write the hours as an inequality from 0 to 6."]},{"id": "AlgI.15-15","std": "Alg I.15","q": "If f(x) = |2x − 9|, for what two values of x does f(x) = 5?","a": "x = 7 and x = 2","lvl": 2,"choices": ["x = 7 only","x = 7 and x = −2","x = −7 and x = 2","x = 7 and x = 2"],"steps": ["Set |2x − 9| = 5. So 2x − 9 = 5 or 2x − 9 = −5.","Solve 2x − 9 = 5.","Solve 2x − 9 = −5."]},{"id": "AlgI.15-16","std": "Alg I.15","q": "A kicked soccer ball's height is h(t) = −16t² + 48t (feet, t seconds after the kick). What are the practical domain and range?","a": "Domain 0 ≤ t ≤ 3; range 0 ≤ h ≤ 36","lvl": 3,"choices": ["Domain 0 ≤ t ≤ 3; range 0 ≤ h ≤ 48","Domain 0 ≤ t ≤ 1.5; range 0 ≤ h ≤ 36","Domain 0 ≤ t ≤ 3; range 0 ≤ h ≤ 36","Domain all real numbers; range h ≤ 36"],"steps": ["Solve −16t(t − 3) = 0 to find domain: 0 ≤ t ≤ 3.","Max height at vertex t = 1.5: h(1.5) = −16(2.25) + 72 = 36.","Range runs from the ground to the highest point. Write both."]},{"id": "AlgI.15-17","std": "Alg I.15","q": "P(t) is the number of people in a library t hours after it opens at 9:00 AM. What does P(4) > P(1) + 20 mean?","a": "At 1:00 PM there were more than 20 more people than at 10:00 AM","lvl": 3,"choices": ["At 4:00 PM there were more than 20 more people than at 1:00 PM","At 1:00 PM there were more than 20 more people than at 10:00 AM","Between 10:00 AM and 1:00 PM, 20 people left","At 1:00 PM there were exactly 20 more people than at 10:00 AM"],"steps": ["t = 4 is 1:00 PM; t = 1 is 10:00 AM.","P(4) > P(1) + 20 compares people at those two times.","Pick the choice that compares those two times."]},{"id": "AlgI.15-18","std": "Alg I.15","q": "A school sells yearbooks for §40 each and has 250 in stock, so R(n) = 40n. Why is the domain {0, 1, 2, ..., 250} and not every number from 0 to 250?","a": "n counts whole yearbooks, so it must be a whole number from 0 to 250","lvl": 3,"choices": ["40n only works for even numbers","Revenue can't be more than §250","n counts whole yearbooks, so it must be a whole number from 0 to 250","The interval from 0 to 250 leaves out n = 250"],"steps": ["Yearbooks are sold only as whole, non-negative counts.","Fractional yearbooks like 2.5 cannot be sold.","So which values can n be?"]},{"id": "AlgI.16-08","std": "Alg I.16","q": "Which relation is a function?","a": "{(1, 5), (2, 5), (3, 7), (4, 9)}","lvl": 1,"choices": ["{(1, 5), (2, 5), (3, 7), (4, 9)}","{(2, 4), (3, 5), (2, 6), (4, 7)}","{(1, 5), (1, 6), (2, 7), (3, 8)}","{(0, 1), (0, 2), (0, 3), (0, 4)}"],"steps": ["A function has no x-value paired with two different y-values.","Check the inputs in each set for repeats.","Which set has no repeated inputs?"]},{"id": "AlgI.16-09","std": "Alg I.16","q": "What visual test can be used on the graph of a relation in the coordinate plane to determine if it represents y as a function of x?","a": "Vertical Line Test","lvl": 1,"choices": ["Origin Symmetry Test","Vertical Line Test","Horizontal Line Test","Slope-Intercept Test"],"steps": ["Each x-value can have at most one y-value on the graph.","A vertical line checks if any x hits the graph twice.","What is that test called?"]},{"id": "AlgI.16-10","std": "Alg I.16","q": "In the relation {(2, 8), (4, 10), (6, 12), (4, 14)}, why is this relation NOT a function?","a": "The input 4 is paired with two different outputs, 10 and 14.","lvl": 1,"choices": ["There are only four ordered pairs.","The input 4 is paired with two different outputs, 10 and 14.","The outputs increase by 2 each time.","All of the numbers are even."],"steps": ["Look for repeated x-values in the ordered pairs.","The input 4 appears in both (4, 10) and (4, 14).","Can one input have two outputs in a function?"]},{"id": "AlgI.16-11","std": "Alg I.16","q": "Determine which of the following equations does NOT define y as a function of x.","a": "x = y² + 1","lvl": 2,"choices": ["y = |x − 3|","y = x² + 1","x = y² + 1","2x + 5y = 10"],"steps": ["Check if any x-value can give two y-values.","In x = y² + 1, try x = 5. What values can y be?","Which equation lets one x have two y's?"]},{"id": "AlgI.16-12","std": "Alg I.16","q": "A table shows the following (x, y) pairs: (−2, 4), (−1, 1), (0, 0), (1, 1), (2, 4). Does this table represent a function?","a": "Yes, because every input x has exactly one output y, even though different inputs share the same output.","lvl": 2,"choices": ["No, because the outputs 4 and 1 repeat.","Yes, because the table has an odd number of rows.","Yes, because every input x has exactly one output y, even though different inputs share the same output.","No, because x has both positive and negative values."],"steps": ["Check the x-values: −2, −1, 0, 1, 2 (none repeat).","Repeated y-values (1 and 4) are allowed in a function.","So does every input have exactly one output?"]},{"id": "AlgI.16-13","std": "Alg I.16","q": "The graph of a circle has center (0, 0) and radius 4. Explain why this graph represents a relation, not a function.","a": "A vertical line such as x = 0 intersects the circle at two points, (0, 4) and (0, −4), giving two outputs for one input.","lvl": 2,"choices": ["The graph crosses both the x-axis and y-axis.","A horizontal line intersects the circle twice.","A vertical line such as x = 0 intersects the circle at two points, (0, 4) and (0, −4), giving two outputs for one input.","A circle has no endpoints."],"steps": ["Test the Vertical Line Test at x = 0.","The line x = 0 hits the circle at (0, 4) and (0, −4).","Pick the choice that names an input with two outputs."]},{"id": "AlgI.16-14","std": "Alg I.16","q": "Compare R1: y = x² and R2: x = y². Which is a function of x?","a": "y = x² is (x = 2 gives only y = 4); x = y² is not (x = 4 gives y = 2 and y = −2)","lvl": 3,"choices": ["Neither is a function, because both graphs are curved","Both are functions, because both use squaring","x = y² is (y = 2 gives only x = 4); y = x² is not (y = 4 gives x = 2 and x = −2)","y = x² is (x = 2 gives only y = 4); x = y² is not (x = 4 gives y = 2 and y = −2)"],"steps": ["For y = x², each x gives one y, passing vertical line test.","For x = y², x = 4 gives y = 2 and −2, failing the test.","Which relation passes the vertical line test?"]},{"id": "AlgI.16-15","std": "Alg I.16","q": "A student says, 'Every function is a relation, so every relation must also be a function.' Is this true?","a": "False: a relation that pairs one input with two outputs is not a function","lvl": 3,"choices": ["True: every set of ordered pairs is a function","False: a relation that pairs one input with two outputs is not a function","False: a function is not a relation","True: functions and relations are the same thing"],"steps": ["A relation is any set of ordered pairs.","A function requires each input to have strictly one output.","So is every relation a function?"]},{"id": "AlgI.16-16","std": "Alg I.16","q": "Consider the table of values: (1, 3), (2, 5), (3, 7), (k, 9). For what value(s) of k will this table NOT represent a function?","a": "k = 1, k = 2, or k = 3","lvl": 3,"choices": ["k = 9 only","k = 4 only","Any negative number","k = 1, k = 2, or k = 3"],"steps": ["The inputs already used are 1, 2, and 3.","If k repeats one of them, that input gets a second output, 9.","Which values of k would do that?"]},{"id": "AlgI.17-09","std": "Alg I.17","q": "Given f(x) = 3x + 2 and g(x) = x − 5, find (f + g)(x).","a": "4x − 3","lvl": 1,"part": "a","choices": ["2x + 7","3x² − 13x − 10","4x − 3","4x + 7"],"steps": ["Add the functions: (3x + 2) + (x − 5).","Group like terms: (3x + x) + (2 − 5).","Simplify each group."]},{"id": "AlgI.17-10","std": "Alg I.17","q": "If R(x) = 25x models the revenue from selling x tickets and C(x) = 10x + 150 models the cost, which function models the profit P(x) = R(x) − C(x)?","a": "P(x) = 15x − 150","lvl": 1,"part": "a","choices": ["P(x) = 15x − 150","P(x) = 35x + 150","P(x) = 15x + 150","P(x) = −15x − 150"],"steps": ["Profit = revenue − cost: 25x − (10x + 150).","Distribute the minus sign to both terms in the parentheses.","Combine like terms."]},{"id": "AlgI.17-11","std": "Alg I.17","q": "Let f(x) = 2x and g(x) = x + 4. Find f(g(3)).","a": "14","lvl": 1,"part": "b","choices": ["9","10","14","24"],"steps": ["Evaluate the inner function first: g(3) = 3 + 4 = 7.","Substitute 7 into f(x): f(7) = 2(7).","Multiply."]},{"id": "AlgI.17-12","std": "Alg I.17","q": "Water enters a tank at a rate modeled by E(t) = 12t + 50 gallons and leaks out at a rate modeled by L(t) = 2t² + 3t gallons, where t is hours. Write a function W(t) for the net amount of water in the tank after t hours and evaluate W(3).","a": "W(t) = −2t² + 9t + 50; W(3) = 59 gallons","lvl": 2,"part": "a","choices": ["W(t) = 2t² + 15t + 50; W(3) = 113 gallons","W(t) = 2t² − 9t − 50; W(3) = −59 gallons","W(t) = −2t² + 9t + 50; W(3) = 59 gallons","W(t) = −2t² + 15t + 50; W(3) = 77 gallons"],"steps": ["Subtract: W(t) = (12t + 50) − (2t² + 3t) = −2t² + 9t + 50.","Evaluate at t = 3: W(3) = −2(9) + 9(3) + 50.","Simplify: −18 + 27 + 50."]},{"id": "AlgI.17-13","std": "Alg I.17","q": "Given f(x) = x² + 1 and g(x) = 3x − 2, find an expression for f(g(x)).","a": "9x² − 12x + 5","lvl": 2,"part": "b","choices": ["3x² + 1","3x³ − 2x² + 3x − 2","9x² + 5","9x² − 12x + 5"],"steps": ["Put g(x) into f(x): (3x − 2)² + 1.","Expand (3x − 2)² as (3x − 2)(3x − 2).","Add the 1 and combine like terms."]},{"id": "AlgI.17-14","std": "Alg I.17","q": "A rectangle's length is modeled by L(x) = 2x + 3 and its width is modeled by W(x) = x + 4. Write the area function A(x) = L(x) · W(x) in standard polynomial form.","a": "A(x) = 2x² + 11x + 12","lvl": 2,"part": "a","choices": ["A(x) = 6x + 14","A(x) = 3x + 7","A(x) = 2x² + 12","A(x) = 2x² + 11x + 12"],"steps": ["Multiply length and width: (2x + 3)(x + 4).","Expand: 2x² + 8x + 3x + 12.","Combine like terms."]},{"id": "AlgI.17-15","std": "Alg I.17","q": "Temperature at altitude h thousand feet is T(h) = 75 − 3.5h. A balloon's altitude after t minutes is h(t) = 0.4t. Find T(h(t)), say what it means, and find T(h(25)).","a": "T(h(t)) = 75 − 1.4t, the air temperature at the balloon t minutes after launch; 40°F","lvl": 3,"part": "b","choices": ["T(h(t)) = 75 − 3.5t, the temperature t thousand feet up; −12.5°F","T(h(t)) = 75 − 1.4t, the air temperature at the balloon t minutes after launch; 40°F","T(h(t)) = 0.4(75 − 3.5t), the balloon's height at a given temperature; −5°F","T(h(t)) = 75 − 1.4t, the balloon's height after t minutes; 40 feet"],"steps": ["Substitute h(t) = 0.4t into T(h): 75 − 3.5(0.4t) = 75 − 1.4t.","This gives air temperature at the balloon t minutes after launch.","Plug t = 25 into 75 − 1.4t."]},{"id": "AlgI.17-16","std": "Alg I.17","q": "A store takes 20% off, D(p) = 0.80p, and adds 8% tax, T(x) = 1.08x. Compare T(D(p)) and D(T(p)).","a": "Both equal 0.864p, so the order doesn't change the final price","lvl": 3,"part": "b","choices": ["Discount first costs more: T(D(p)) = 0.88p","Both equal 0.28p, because 1.08 − 0.80 = 0.28","Both equal 0.864p, so the order doesn't change the final price","Tax first costs more: D(T(p)) = 0.88p"],"steps": ["Compute T(D(p)) = 1.08(0.80p) = 0.864p.","Compute D(T(p)) = 0.80(1.08p) = 0.864p.","Compare the two results. Does the order matter?"]},{"id": "AlgI.17-17","std": "Alg I.17","q": "Deer: D(t) = 120(1.05)^t. Elk: E(t) = 80(1.03)^t, with t years since 2020. Write P(t) for the total and predict the total in 2022.","a": "P(t) = 120(1.05)^t + 80(1.03)^t; about 217 animals","lvl": 3,"part": "a","choices": ["P(t) = 120(1.05)^t · 80(1.03)^t; about 11,229 animals","P(t) = 200(1.08)^t; about 233 animals","P(t) = 120(1.05)^t + 80(1.03)^t; about 217 animals","P(t) = 120(1.05)^t + 80(1.03)^t; about 200 animals"],"steps": ["Add populations: P(t) = 120(1.05)^{t} + 80(1.03)^{t}.","For 2022 (t = 2): 120(1.1025) + 80(1.0609) = 132.3 + 84.872.","Add the two values and round to a whole animal."]},{"id": "AlgI.18-07","std": "Alg I.18","q": "The graphs of y = x² and y = 4 intersect at two points. What are the coordinates of the intersection points?","a": "(−2, 4) and (2, 4)","lvl": 1,"choices": ["(4, 16) and (−4, 16)","(0, 4) and (2, 0)","(2, 4) only","(−2, 4) and (2, 4)"],"steps": ["Set the equations equal: x² = 4.","Which two numbers square to 4?","Each point has y = 4. Write both points."]},{"id": "AlgI.18-08","std": "Alg I.18","q": "What is the maximum number of intersection points possible between the graph of a quadratic equation (a parabola) and the graph of a linear equation (a line)?","a": "2","lvl": 1,"choices": ["1","2","3","4"],"steps": ["Setting a quadratic equal to a linear gives a degree-2 equation.","A quadratic equation has at most 2 real solutions.","So what is the most times a line and a parabola can meet?"]},{"id": "AlgI.18-09","std": "Alg I.18","q": "When solving a system consisting of a line and a parabola graphically, the two graphs do not touch or cross anywhere. How many real solutions does the system have?","a": "0","lvl": 1,"choices": ["2","1","Infinitely many","0"],"steps": ["Real solutions correspond to intersection points on the graph.","The graphs do not touch or cross anywhere.","So how many real solutions are there?"]},{"id": "AlgI.18-10","std": "Alg I.18","q": "Find the solutions to the system of equations:\ny = x² − 3\ny = 2x","a": "(−1, −2) and (3, 6)","lvl": 2,"choices": ["(1, 2) and (−3, −6)","(3, 6) only","(−1, −2) and (3, 6)","(−1, 2) and (3, 6)"],"steps": ["Set x² − 3 = 2x, so x² − 2x − 3 = 0.","Factor and solve for both x-values.","Plug each x into y = 2x to get the points."]},{"id": "AlgI.18-11","std": "Alg I.18","q": "A parabola has vertex (2, −1) and opens upward, modeled by y = (x − 2)² − 1. A horizontal line is given by y = −1. Where do the two graphs intersect?","a": "(2, −1) only (1 solution)","lvl": 2,"choices": ["(0, 3) and (2, −1)","(2, −1) only (1 solution)","No intersection","(1, −1) and (3, −1)"],"steps": ["Set (x − 2)² − 1 = −1, so (x − 2)² = 0.","How many x-values make (x − 2)² = 0?","Write the point using y = −1."]},{"id": "AlgI.18-12","std": "Alg I.18","q": "Use graphing or substitution to find the intersection points of y = −x² + 4x + 1 and y = x + 1.","a": "(0, 1) and (3, 4)","lvl": 2,"choices": ["(1, 2) and (4, 5)","(0, 1) and (−3, −2)","(0, 1) and (3, 4)","(0, 0) and (3, 3)"],"steps": ["Set −x² + 4x + 1 = x + 1, so −x² + 3x = 0.","Factor: −x(x − 3) = 0. Solve for x.","Plug each x into y = x + 1 to get the points."]},{"id": "AlgI.18-13","std": "Alg I.18","q": "A flare's height is h = −16t² + 80t and a drone's is h = 16t + 48 (feet, t seconds). Where do their paths meet, and what does it mean?","a": "(1, 64) and (3, 96): they are at the same height at 1 s and at 3 s","lvl": 3,"choices": ["(1, 64) only: they are at the same height at 1 s","(1, 64) and (3, 96): they are at the same height at 1 s and at 3 s","(0, 0) and (5, 0): both are on the ground","(2, 96) and (4, 64): they are at the same height at 2 s and 4 s"],"steps": ["Set −16t² + 80t = 16t + 48, giving 16t² − 64t + 48 = 0.","Divide by 16: t² − 4t + 3 = 0, so t = 1 and t = 3.","Plug each t into h = 16t + 48 to find the heights."]},{"id": "AlgI.18-14","std": "Alg I.18","q": "A calculator shows y = x² + 2x − 4 and y = 3x − 1 crossing near x = 2.3 and x = −1.3. Use substitution to find the exact x-values.","a": "x = {1 ± √13/2}","lvl": 3,"choices": ["x = {−1 ± √13/2}","x = 2.3 and x = −1.3","x = {1 ± √13/2}","x = {1 ± √11/2}"],"steps": ["Set x² + 2x − 4 = 3x − 1, so x² − x − 3 = 0.","Use the quadratic formula with a = 1, b = −1, c = −3.","Simplify b² − 4ac under the root, then write both x-values."]},{"id": "AlgI.18-15","std": "Alg I.18","q": "For what value of k will the line y = 4x + k intersect the parabola y = x² at exactly one point?","a": "−4","lvl": 3,"choices": ["−16","−4","0","4"],"steps": ["Set x² = 4x + k, so x² − 4x − k = 0.","One intersection means the discriminant b² − 4ac = 0.","Solve (−4)² − 4(1)(−k) = 0 for k."]},{"id": "AlgI.19-07","std": "Alg I.19","q": "The graphs of y = 2x + 1 and y = x + 4 intersect at the point (3, 7). What is the solution to the equation 2x + 1 = x + 4?","a": "x = 3","lvl": 1,"choices": ["x = 4","x = 3","x = 7","x = 1"],"steps": ["The solution to 2x + 1 = x + 4 is the x-value where the lines meet.","Look at the point (3, 7). Which number is x?","So what x makes the equation true?"]},{"id": "AlgI.19-08","std": "Alg I.19","q": "Why is the x-coordinate of the intersection of y = f(x) and y = g(x) a solution to f(x) = g(x)?","a": "At that x-value, both functions produce the same y-value","lvl": 1,"choices": ["At that x-value, both functions equal zero","At that x-value, both graphs cross the y-axis","At that x-value, both graphs have the same slope","At that x-value, both functions produce the same y-value"],"steps": ["An intersection point (x, y) lies on both graphs.","That means f(x) and g(x) yield the exact same y-value.","Pick the choice that says what is true at that x-value."]},{"id": "AlgI.19-09","std": "Alg I.19","q": "A table of values shows that at x = 2, f(2) = 5 and g(2) = 5. Which statement must be true?","a": "x = 2 is a solution to f(x) = g(x)","lvl": 1,"choices": ["f(x) and g(x) have no intersection","x = 5 is a solution to f(x) = g(x)","x = 2 is a solution to f(x) = g(x)","y = 2 is the y-intercept of both functions"],"steps": ["At x = 2, both functions give the output 5.","Since f(2) = g(2), x = 2 satisfies f(x) = g(x).","Which choice must be true?"]},{"id": "AlgI.19-10","std": "Alg I.19","q": "For f(x) = 2^x and g(x) = x + 2, f(1) = 2 and g(1) = 3, while f(2) = 4 and g(2) = 4. What is a solution to 2^x = x + 2?","a": "x = 2","lvl": 2,"choices": ["x = 1","x = 2","x = 3","x = 4"],"steps": ["Compare f(x) and g(x) at each x-value given.","At which x are the two outputs equal?","That x makes 2^{x} = x + 2 true."]},{"id": "AlgI.19-11","std": "Alg I.19","q": "The graphs of y = x² − 4 and y = 2x − 1 intersect at (−1, −3) and (3, 5). What are the solutions to x² − 4 = 2x − 1?","a": "x = −1 and x = 3","lvl": 2,"choices": ["x = −3 and x = 5","x = −1 and x = 5","x = 3 and x = −3","x = −1 and x = 3"],"steps": ["Solutions to x² − 4 = 2x − 1 are the intersection x-values.","Read x-coordinates from (−1, −3) and (3, 5).","Write the x-values of both points."]},{"id": "AlgI.19-12","std": "Alg I.19","q": "Using a table for f(x) = 3^x and g(x) = 4x + 1: at x = 1, f(1) = 3 and g(1) = 5; at x = 2, f(2) = 9 and g(2) = 9. Where do the graphs intersect?","a": "(2, 9)","lvl": 2,"choices": ["(2, 9)","(1, 3)","(9, 2)","(1, 5)"],"steps": ["Find where f(x) and g(x) have the same output.","At x = 1 they differ. Check x = 2.","Write the point as (x, output)."]},{"id": "AlgI.19-13","std": "Alg I.19","q": "For f(x) = 2^x and g(x) = 3x + 2, f(3) = 8 and g(3) = 11, while f(4) = 16 and g(4) = 14. Between which two integers is a solution to 2^x = 3x + 2?","a": "Between 3 and 4","lvl": 3,"choices": ["Between 8 and 11","Between 2 and 3","Between 3 and 4","Between 14 and 16"],"steps": ["At x = 3, f(3) = 8 < g(3) = 11.","At x = 4, f(4) = 16 > g(4) = 14.","The order switched. Where must they be equal?"]},{"id": "AlgI.19-14","std": "Alg I.19","q": "Using successive approximations for |x − 2| = 0.5x + 1: at x = 5, |5 − 2| = 3 and 0.5(5) + 1 = 3.5; at x = 6, |6 − 2| = 4 and 0.5(6) + 1 = 4. What is the positive solution?","a": "x = 6","lvl": 3,"choices": ["x = 5","x = 6","x = 3.5","x = 4"],"steps": ["At x = 5, 3 ≠ 3.5, so x = 5 is not a solution.","Check x = 6: find |6 − 2| and 0.5(6) + 1.","Are the two sides equal there?"]},{"id": "AlgI.19-15","std": "Alg I.19","q": "If the graphs of y = f(x) and y = g(x) are parallel lines with different y-intercepts, how many solutions does the equation f(x) = g(x) have?","a": "No solutions","lvl": 3,"choices": ["Infinitely many solutions","Exactly one solution","No solutions","Exactly two solutions"],"steps": ["Parallel lines with different y-intercepts never intersect.","Solutions to f(x) = g(x) are intersection points.","So how many solutions are there?"]},{"id": "AlgI.20-08","std": "Alg I.20","q": "When graphing the linear inequality y > 3x − 2, what type of boundary line should be drawn?","a": "A dashed line","lvl": 1,"choices": ["A horizontal line","A solid line","A dashed line","A vertical line"],"steps": ["The symbol > is strict and does not include equality.","Points on the boundary line are not solutions.","Should the boundary be dashed or solid?"]},{"id": "AlgI.20-09","std": "Alg I.20","q": "Which ordered pair is a solution to the inequality y ≤ 2x + 1?","a": "(2, 4)","lvl": 1,"choices": ["(1, 5)","(2, 4)","(0, 3)","(−1, 2)"],"steps": ["Test each point in y ≤ 2x + 1.","For (2, 4): is 4 ≤ 2(2) + 1?","Which point makes the inequality true?"]},{"id": "AlgI.20-10","std": "Alg I.20","q": "For the inequality y ≥ −x + 4, which side of the boundary line should be shaded?","a": "Above the boundary line","lvl": 1,"choices": ["Only in Quadrant I","Below the boundary line","Only on the boundary line","Above the boundary line"],"steps": ["The inequality is solved for y: y ≥ −x + 4.","Greater than or equal to (≥) means larger y-values.","Larger y-values are above or below the line?"]},{"id": "AlgI.20-11","std": "Alg I.20","q": "Which ordered pair is in the solution set of the system y > x and y ≤ −x + 6?","a": "(1, 3)","lvl": 2,"choices": ["(3, 5)","(5, 2)","(4, 2)","(1, 3)"],"steps": ["Test each point in y > x.","Test the ones that pass in y ≤ −x + 6.","Which point passes both?"]},{"id": "AlgI.20-12","std": "Alg I.20","q": "The boundary line of 2x − y < 4 is graphed. Which statement describes the graph of its solution set?","a": "A dashed line with slope 2 and y-intercept −4, shaded above the line","lvl": 2,"choices": ["A solid line with slope 2 and y-intercept −4, shaded above the line","A solid line with slope −2 and y-intercept 4, shaded below the line","A dashed line with slope 2 and y-intercept −4, shaded below the line","A dashed line with slope 2 and y-intercept −4, shaded above the line"],"steps": ["Solve for y: −y < −2x + 4, so y > 2x − 4 (flip sign).","Slope is 2, y-intercept is −4, and > means dashed line.","Shade above or below the dashed line?"]},{"id": "AlgI.20-13","std": "Alg I.20","q": "Where is the solution set to a system of two linear inequalities located on a coordinate plane?","a": "In the overlapping shaded region of both half-planes","lvl": 2,"choices": ["Anywhere shaded by at least one of the two inequalities","In the unshaded region of the coordinate plane","At the single point where the two boundary lines cross","In the overlapping shaded region of both half-planes"],"steps": ["Each inequality shades a half-plane of solutions.","A system solution must satisfy both inequalities at once.","So where do both shaded regions count?"]},{"id": "AlgI.20-14","std": "Alg I.20","q": "A point lies on the intersection of the boundary lines of y > 2x − 1 and y ≤ −x + 5. Is this point a solution to the system?","a": "No, because one inequality is strict and excludes its boundary line","lvl": 3,"choices": ["No, because one inequality is strict and excludes its boundary line","No, because intersection points are never solutions to systems of inequalities","Yes, because the second inequality includes its boundary line","Yes, because it lies on both boundary lines"],"steps": ["A system solution must satisfy both inequalities.","The first inequality (y > 2x − 1) is strict (dashed line).","Is a point on a dashed boundary a solution?"]},{"id": "AlgI.20-15","std": "Alg I.20","q": "Which system of linear inequalities has no solution?","a": "y > 2x + 3 and y < 2x − 1","lvl": 3,"choices": ["y ≥ 2x + 3 and y ≥ 2x − 1","y > 2x + 3 and y < −2x − 1","y > 2x + 3 and y < 2x − 1","y < 2x + 3 and y > 2x − 1"],"steps": ["Look for two parallel boundary lines with different intercepts.","One shades above y = 2x + 3; the other below y = 2x − 1.","Which system's shaded regions never overlap?"]},{"id": "AlgI.20-16","std": "Alg I.20","q": "Which inequality has a graph that includes the point (0, 0) in its shaded region but NOT the point (2, 1)?","a": "y > x − 1","lvl": 3,"choices": ["y > x − 1","y < x − 1","y ≥ 2x − 3","y ≤ −x + 4"],"steps": ["Test (0, 0) in each inequality.","Test (2, 1) in each one that included (0, 0).","Which inequality includes (0, 0) but not (2, 1)?"]},{"id": "AlgI.21-07","std": "Alg I.21","q": "Function f is given by f(x) = 3x + 2. Function g is a linear function with a slope of 5 and a y-intercept of 1. Which function has the greater y-intercept?","a": "Function f","lvl": 1,"choices": ["They have the same y-intercept","Function g","Function f","Cannot be determined"],"steps": ["Find the y-intercept of f(x) = 3x + 2.","Function g has a y-intercept of 1.","Compare the two y-intercepts."]},{"id": "AlgI.21-08","std": "Alg I.21","q": "Function f(x) = x² − 4 has a minimum value of −4. A table for quadratic function g(x) shows its vertex at (2, −7). Which function has the lower minimum value?","a": "Function g","lvl": 1,"choices": ["Function f","Function g","Neither function has a minimum value","They have the same minimum value"],"steps": ["Identify the minimum value of f(x) as −4.","From the vertex (2, −7), the minimum value of g(x) is −7.","Which minimum is lower?"]},{"id": "AlgI.21-09","std": "Alg I.21","q": "Function f(x) = 2(3)^x and function g(x) starts at 5 when x = 0 and doubles each time x increases by 1. Which function has the greater initial value?","a": "Function g","lvl": 1,"choices": ["Function g","Function f has no initial value","Function f","They have the same initial value"],"steps": ["Find f's initial value: f(0) = 2(3)⁰.","Function g starts at 5 when x = 0.","Compare the two starting values."]},{"id": "AlgI.21-10","std": "Alg I.21","q": "Function f(x) = −2(x − 3)² + 8 and function g(x) is represented by a table with values g(0) = 1, g(1) = 6, g(2) = 9, g(3) = 6, g(4) = 1. Which function has the greater maximum value?","a": "Function g, with a maximum of 9","lvl": 2,"choices": ["Function f, with a maximum of 8","Function f, with a maximum of 3","They have the same maximum value","Function g, with a maximum of 9"],"steps": ["From vertex form f(x) = −2(x − 3)² + 8, the maximum of f is 8.","From the table for g(x), the highest output value is g(2) = 9.","Which maximum is greater?"]},{"id": "AlgI.21-11","std": "Alg I.21","q": "Function f(x) = |x − 4| + 2 and function g(x) is an absolute value function whose V-shaped graph opens upward with vertex at (−1, 5). Which statement is true?","a": "Function f has a smaller minimum value than function g","lvl": 2,"choices": ["Function g has a smaller minimum value than function f","Both functions have a maximum value","Function f has a smaller minimum value than function g","Both functions have the same axis of symmetry"],"steps": ["Find the vertex of f(x) = |x − 4| + 2 at (4, 2), so its minimum is 2.","Note that g(x) opens upward with vertex (−1, 5), so its minimum is 5.","Which minimum is smaller?"]},{"id": "AlgI.21-12","std": "Alg I.21","q": "Function f(x) = 4x − 3. Function g passes through the points (0, 2) and (3, 14). How do the slopes of f and g compare?","a": "They have the same slope of 4","lvl": 2,"choices": ["Function g has a slope of 12","Function g has a greater slope than function f","Function f has a greater slope than function g","They have the same slope of 4"],"steps": ["Read the slope of f(x) = 4x − 3 directly as m = 4.","Find g's slope: (14 − 2) ÷ (3 − 0).","Compare the two slopes."]},{"id": "AlgI.21-13","std": "Alg I.21","q": "Function f(x) = 2^x + 1 and function g(x) is a linear function passing through (0, 3) and (2, 7). Compare f(3) and g(3).","a": "f(3) and g(3) are both equal to 9","lvl": 3,"choices": ["g(3) is greater than f(3) by 1","f(3) is 8 and g(3) is 9","f(3) and g(3) are both equal to 9","f(3) is greater than g(3) by 2"],"steps": ["Evaluate f(3) = 2³ + 1 = 8 + 1 = 9.","Find g(x): slope (7 − 3) ÷ (2 − 0), and y-intercept 3.","Evaluate g(3) and compare it with f(3)."]},{"id": "AlgI.21-14","std": "Alg I.21","q": "Function f(x) = x² − 6x + 5 and function g(x) has zeros at x = −2 and x = 4. Which function has a greater distance between its zeros?","a": "Function g, with a distance of 6","lvl": 3,"choices": ["Function f, with a distance of 4","Function g, with a distance of 6","Both functions have the same distance of 4","Function f, with a distance of 6"],"steps": ["Factor f(x) = (x − 1)(x − 5) to find zeros at x = 1 and x = 5.","Find distance between zeros of f: 5 − 1 = 4.","Find the distance for g: 4 − (−2). Which distance is greater?"]},{"id": "AlgI.21-15","std": "Alg I.21","q": "Piecewise function f(x) equals 2x for x < 3 and equals 6 for x ≥ 3. Function g(x) = |x − 3| + 4. Which function has a greater value at x = 5?","a": "They have the same value of 6 at x = 5","lvl": 3,"choices": ["They have the same value of 6 at x = 5","Function f is greater, with a value of 6 compared to 4","Function g is greater, with a value of 8","Function f is greater, with a value of 10"],"steps": ["Since 5 ≥ 3, use the second rule of f(x) to get f(5) = 6.","Evaluate g(5) = |5 − 3| + 4 = 2 + 4 = 6.","Compare f(5) and g(5)."]},{"id": "AlgI.22-10","std": "Alg I.22","q": "What is the domain of a sequence when it is defined as a function?","a": "A subset of the integers, usually the positive integers","lvl": 1,"choices": ["All negative numbers only","All rational numbers between 0 and 1","All real numbers","A subset of the integers, usually the positive integers"],"steps": ["Recall that a sequence is an ordered list of terms indexed by position.","Term positions are counted with whole numbers like 1, 2, 3, ...","So what set of numbers is the domain?"]},{"id": "AlgI.22-11","std": "Alg I.22","q": "What are the first four terms of the sequence defined recursively by a(1) = 5 and a(n) = a(n − 1) + 3?","a": "5, 8, 11, 14","lvl": 1,"part": "a","choices": ["5, 2, −1, −4","5, 15, 45, 135","5, 8, 11, 14","3, 8, 13, 18"],"steps": ["Start with the first term a(1) = 5.","Add 3 to get each next term: a(2) = 5 + 3.","Keep adding 3 until you have four terms."]},{"id": "AlgI.22-12","std": "Alg I.22","q": "Which type of function corresponds to an arithmetic sequence?","a": "A linear function","lvl": 1,"part": "a","choices": ["An absolute value function","A linear function","A quadratic function","An exponential function"],"steps": ["An arithmetic sequence adds the same difference each step.","Which kind of function has a constant rate of change?","Pick the function type that matches."]},{"id": "AlgI.22-13","std": "Alg I.22","q": "Write an explicit formula for the arithmetic sequence 7, 11, 15, 19, ... where n ≥ 1.","a": "a(n) = 7 + 4(n − 1)","lvl": 2,"part": "a","choices": ["a(n) = 7(4)^{n − 1}","a(n) = 4n + 7","a(n) = 4 + 7(n − 1)","a(n) = 7 + 4(n − 1)"],"steps": ["The first term is 7. The common difference is 11 − 7.","Use the formula a(n) = a(1) + d(n − 1).","Put the first term and d into that formula."]},{"id": "AlgI.22-14","std": "Alg I.22","q": "Write an explicit formula for the geometric sequence 3, 6, 12, 24, ... where n ≥ 1.","a": "a(n) = 3(2)^{n − 1}","lvl": 2,"part": "a","choices": ["a(n) = 3 + 2(n − 1)","a(n) = 3(2)^{n − 1}","a(n) = 3(2)^n","a(n) = 2(3)^{n − 1}"],"steps": ["The first term is 3. The common ratio is 6 ÷ 3.","Use the formula a(n) = a(1) × r^{n − 1}.","Put the first term and r into that formula."]},{"id": "AlgI.22-15","std": "Alg I.22","q": "A sequence is defined recursively by a(1) = 80 and a(n) = 0.5 · a(n − 1). What is a(4)?","a": "10","lvl": 2,"part": "a","choices": ["5","10","20","40"],"steps": ["Start with a(1) = 80 and multiply by 0.5 to get a(2) = 40.","Multiply by 0.5 again to get a(3) = 20.","Multiply by 0.5 once more."]},{"id": "AlgI.22-16","std": "Alg I.22","q": "An arithmetic sequence has explicit formula a(n) = 5n − 2 for n ≥ 1. Which recursive formula represents the same sequence?","a": "a(1) = 3, a(n) = a(n − 1) + 5","lvl": 3,"part": "a","choices": ["a(1) = 3, a(n) = 5 · a(n − 1)","a(1) = 5, a(n) = a(n − 1) − 2","a(1) = −2, a(n) = a(n − 1) + 5","a(1) = 3, a(n) = a(n − 1) + 5"],"steps": ["Find the first term by plugging in n = 1: a(1) = 5(1) − 2 = 3.","Identify the common difference from the coefficient of n, which is 5.","Write the recursive rule with a(1) and the difference."]},{"id": "AlgI.22-17","std": "Alg I.22","q": "A geometric sequence has a(1) = 4 and a(4) = 108. What is the explicit formula for a(n)?","a": "a(n) = 4(3)^{n − 1}","lvl": 3,"part": "a","choices": ["a(n) = 4(3)^{n − 1}","a(n) = 3(4)^{n − 1}","a(n) = 4(27)^{n − 1}","a(n) = 4 + 34.67(n − 1)"],"steps": ["Use a(4) = a(1) × r³ to set up 108 = 4 × r³.","Divide by 4 to get r³ = 27, so the common ratio is r = 3.","Write a(n) = a(1) × r^{n − 1}."]},{"id": "AlgI.22-18","std": "Alg I.22","q": "The Fibonacci-style sequence is defined by f(1) = 2, f(2) = 5, and f(n) = f(n − 1) + f(n − 2) for n ≥ 3. What is f(5)?","a": "19","lvl": 3,"part": "a","choices": ["12","17","19","24"],"steps": ["Find f(3) = f(2) + f(1) = 5 + 2 = 7.","Find f(4) = f(3) + f(2) = 7 + 5 = 12.","Find f(5) = f(4) + f(3)."]},{"id": "AlgI.23-10","std": "Alg I.23","q": "How does the graph of g(x) = f(x) + 5 compare to the graph of f(x)?","a": "It is shifted 5 units up","lvl": 1,"choices": ["It is shifted 5 units down","It is shifted 5 units up","It is shifted 5 units right","It is shifted 5 units left"],"steps": ["The 5 is added outside the function f(x).","Adding a number outside moves the graph up or down.","A positive number moves it which way?"]},{"id": "AlgI.23-11","std": "Alg I.23","q": "How does the graph of g(x) = f(x − 3) compare to the graph of f(x)?","a": "It is shifted 3 units right","lvl": 1,"choices": ["It is shifted 3 units down","It is shifted 3 units right","It is shifted 3 units up","It is shifted 3 units left"],"steps": ["Notice that 3 is subtracted inside the parentheses from x.","Replacing x with x − h shifts the graph horizontally h units right.","So which way does g move, and how far?"]},{"id": "AlgI.23-12","std": "Alg I.23","q": "How does the graph of g(x) = −f(x) compare to the graph of f(x)?","a": "It is reflected across the x-axis","lvl": 1,"choices": ["It is reflected across the y-axis","It is reflected across the x-axis","It is shifted 1 unit down","It is stretched horizontally"],"steps": ["Notice the negative sign is outside the function, multiplying y-values by −1.","Negating all y-values flips every point over the x-axis.","So what does g(x) = −f(x) do to the graph?"]},{"id": "AlgI.23-13","std": "Alg I.23","q": "If f(x) = x² is transformed to g(x) = 3f(x), what effect does the factor 3 have on the graph?","a": "A vertical stretch by a factor of 3","lvl": 2,"choices": ["A vertical shift 3 units up","A horizontal shift 3 units right","A vertical stretch by a factor of 3","A vertical compression by a factor of 3"],"steps": ["Identify that 3 multiplies the entire function f(x) from the outside.","Multiplying outputs by a factor a > 1 stretches the graph vertically.","So what does the 3 do to the graph?"]},{"id": "AlgI.23-14","std": "Alg I.23","q": "The graph of f(x) = |x| is shifted 4 units left and 2 units down to form g(x). Which equation represents g(x)?","a": "g(x) = |x + 4| − 2","lvl": 2,"choices": ["g(x) = |x + 4| − 2","g(x) = |x − 4| − 2","g(x) = |x − 4| + 2","g(x) = |x + 4| + 2"],"steps": ["Shifting 4 units left replaces x with x + 4 inside the absolute value.","Shifting 2 units down subtracts 2 outside the absolute value.","Put both changes into one equation."]},{"id": "AlgI.23-15","std": "Alg I.23","q": "The graph of f(x) = 2^x passes through (0, 1). The graph of g(x) = f(x) + k passes through (0, −4). What is the value of k?","a": "k = −5","lvl": 2,"choices": ["k = −4","k = −5","k = 5","k = −3"],"steps": ["Substitute x = 0 into g(x) = f(x) + k to get g(0) = f(0) + k.","Plug in the known values: −4 = 1 + k.","Subtract 1 from both sides."]},{"id": "AlgI.23-16","std": "Alg I.23","q": "How does the graph of g(x) = f(2x) compare to the graph of f(x)?","a": "It is compressed horizontally by a factor of {1/2}","lvl": 3,"choices": ["It is stretched vertically by a factor of 2","It is stretched horizontally by a factor of 2","It is shifted 2 units left","It is compressed horizontally by a factor of {1/2}"],"steps": ["Notice that x is multiplied by b = 2 inside the function.","An inside factor b > 1 compresses the graph horizontally by {1/b}.","So what does the 2 inside do to the graph?"]},{"id": "AlgI.23-17","std": "Alg I.23","q": "The vertex of f(x) = x² is at (0, 0). The vertex of g(x) = f(x + k) is at (−6, 0). What is the value of k?","a": "k = 6","lvl": 3,"choices": ["k = −6","k = −36","k = 6","k = 36"],"steps": ["The vertex moves from (0, 0) to (−6, 0), 6 units left.","A left shift shows up as f(x + something).","Match f(x + k) to a 6-unit left shift."]},{"id": "AlgI.23-18","std": "Alg I.23","q": "If f(x) = |x| and g(x) = −0.5f(x − 2) + 3, which sequence of transformations maps f to g?","a": "Vertical compression by 0.5, reflection across the x-axis, shift right 2, and shift up 3","lvl": 3,"choices": ["Vertical stretch by 2, reflection across the y-axis, shift left 2, and shift up 3","Vertical compression by 0.5, reflection across the x-axis, shift left 2, and shift up 3","Vertical compression by 0.5, reflection across the x-axis, shift right 2, and shift up 3","Vertical stretch by 0.5, reflection across the x-axis, shift right 2, and shift down 3"],"steps": ["The −0.5 outside reflects across the x-axis and compresses vertically by 0.5.","The (x − 2) inside shifts the graph 2 units right.","The + 3 outside shifts the graph which way? Match all four moves."]},{"id": "AlgI.24-09","std": "Alg I.24","q": "Which situation is best modeled by a linear function?","a": "A gym charges a §25 sign-up fee plus §15 per month","lvl": 1,"part": "b","choices": ["A gym charges a §25 sign-up fee plus §15 per month","An investment earns 4% compound interest annually","A bacteria colony doubles every 3 hours","A car loses 12% of its value each year"],"steps": ["A linear function adds a constant amount per equal interval.","A flat fee of 25 plus 15 per month adds 15 each month.","Which choice adds the same amount each month?"]},{"id": "AlgI.24-10","std": "Alg I.24","q": "Which situation is best modeled by an exponential function?","a": "A town's population increases by 6% each year","lvl": 1,"part": "c","choices": ["A town's population increases by 200 people each year","A tank drains at a constant rate of 5 gallons per minute","A worker earns §18 for every hour worked","A town's population increases by 6% each year"],"steps": ["An exponential function changes by a constant percentage or factor.","Increasing by 6% each year multiplies the population by 1.06 yearly.","Which choice grows by a percent?"]},{"id": "AlgI.24-11","std": "Alg I.24","q": "How does an exponential function change over equal intervals of x?","a": "By equal factors","lvl": 1,"part": "a","choices": ["By equal differences","By equal sums","By equal factors","By alternating signs"],"steps": ["In f(x) = a × b^{x}, each step multiplies by b.","Multiplying by the same number each time changes outputs how?","Pick the choice that describes that change."]},{"id": "AlgI.24-12","std": "Alg I.24","q": "A table has points (0, 4), (1, 12), (2, 36), (3, 108). Is this function linear or exponential, and why?","a": "Exponential, because y is multiplied by a constant factor of 3 each time x increases by 1","lvl": 2,"part": "a","choices": ["Linear, because the x-values increase by 1","Exponential, because y increases by 8 each time x increases by 1","Linear, because y increases by a constant difference of 8 each time x increases by 1","Exponential, because y is multiplied by a constant factor of 3 each time x increases by 1"],"steps": ["Check the x-values: 0, 1, 2, 3 increase by equal intervals of 1.","Check the ratios of consecutive y-values: {12/4} = 3, {36/12} = 3, {108/36} = 3.","Is a constant factor linear or exponential?"]},{"id": "AlgI.24-13","std": "Alg I.24","q": "A table has points (1, 5), (3, 11), (5, 17), (7, 23). Is this function linear or exponential, and why?","a": "Linear, because y increases by 6 over each equal interval of 2 in x","lvl": 2,"part": "a","choices": ["Linear, because y increases by 2 each time x increases by 6","Exponential, because y increases by a factor of 3 each time","Exponential, because the outputs are all odd numbers","Linear, because y increases by 6 over each equal interval of 2 in x"],"steps": ["Check the x-values: 1, 3, 5, 7 increase by equal intervals of 2.","Check the differences in y-values: 11 − 5 = 6, 17 − 11 = 6, 23 − 17 = 6.","Is a constant difference linear or exponential?"]},{"id": "AlgI.24-14","std": "Alg I.24","q": "A radioactive substance decays by 15% every hour. Which decay factor should be used in an exponential model?","a": "0.85","lvl": 2,"part": "c","choices": ["−0.15","0.15","0.85","1.15"],"steps": ["Convert the 15% decay rate to a decimal: r = 0.15.","Subtract the decay rate from 1 to find the decay factor: 1 − r.","Subtract 0.15 from 1."]},{"id": "AlgI.24-15","std": "Alg I.24","q": "For f(x) = 5(2)^x, what is the ratio {f(x + 3)/f(x)} for any real number x?","a": "8","lvl": 3,"part": "a","choices": ["2","5","6","8"],"steps": ["Write f(x + 3) ÷ f(x) as 5(2)^{x + 3} ÷ 5(2)^{x}.","Cancel the 5s. Subtract exponents: (x + 3) − x.","Evaluate 2 to that power."]},{"id": "AlgI.24-16","std": "Alg I.24","q": "For a linear function f(x) = mx + b, what is f(x + 4) − f(x) for any real number x?","a": "4m","lvl": 3,"part": "a","choices": ["4m + b","m⁴","m + 4","4m"],"steps": ["Plug x + 4 into f: m(x + 4) + b.","Distribute: mx + 4m + b. Then subtract f(x) = mx + b.","Cancel the matching terms. What is left?"]},{"id": "AlgI.24-17","std": "Alg I.24","q": "A savings account starts with §500 and grows by 3.5% each year. Which function models the balance B(t) after t years?","a": "B(t) = 500(1.035)^t","lvl": 3,"part": "c","choices": ["B(t) = 500(1.35)^t","B(t) = 500(0.035)^t","B(t) = 500 + 3.5t","B(t) = 500(1.035)^t"],"steps": ["Identify the initial amount a = 500 and growth rate r = 3.5% = 0.035.","Find the growth factor: 1 + 0.035 = 1.035.","Write B(t) = a × (growth factor)^{t}."]},{"id": "AlgI.25-08","std": "Alg I.25","q": "A linear function has a slope of 4 and a y-intercept of −3. What is the equation of the function?","a": "f(x) = 4x − 3","lvl": 1,"choices": ["f(x) = 4x − 3","f(x) = 4x + 3","f(x) = −3x + 4","f(x) = 3x − 4"],"steps": ["Use slope-intercept form f(x) = mx + b.","Here m = 4 and b = −3.","Put m and b into the form."]},{"id": "AlgI.25-09","std": "Alg I.25","q": "An exponential function has an initial value of 10 and triples every time x increases by 1. Which function models this relationship?","a": "f(x) = 10(3)^x","lvl": 1,"choices": ["f(x) = 10(3)^x","f(x) = 30^x","f(x) = 10 + 3x","f(x) = 3(10)^x"],"steps": ["Use exponential form f(x) = a × b^{x}.","The initial value is a. Tripling gives the growth factor b.","Put a and b into the form."]},{"id": "AlgI.25-10","std": "Alg I.25","q": "A table shows the points (0, 6) and (1, 10) for a linear function. What is the equation of the function?","a": "f(x) = 4x + 6","lvl": 1,"choices": ["f(x) = 4x + 6","f(x) = 4x + 10","f(x) = 10x + 6","f(x) = 6x + 4"],"steps": ["From (0, 6), the y-intercept is b = 6.","Find the slope: (10 − 6) ÷ (1 − 0).","Write f(x) = mx + b."]},{"id": "AlgI.25-11","std": "Alg I.25","q": "Construct a linear function that passes through the points (2, 9) and (5, 21).","a": "f(x) = 4x + 1","lvl": 2,"choices": ["f(x) = 3x + 3","f(x) = 12x − 15","f(x) = 4x + 1","f(x) = 4x + 9"],"steps": ["Find the slope: (21 − 9) ÷ (5 − 2).","Plug (2, 9) and the slope into y = mx + b. Solve for b.","Write f(x) = mx + b."]},{"id": "AlgI.25-12","std": "Alg I.25","q": "Construct an exponential function that passes through the points (0, 5) and (2, 45).","a": "f(x) = 5(3)^x","lvl": 2,"choices": ["f(x) = 5(4.5)^x","f(x) = 3(5)^x","f(x) = 5(3)^x","f(x) = 5(9)^x"],"steps": ["From (0, 5), the initial value is a = 5, so f(x) = 5 × b^{x}.","Plug in (2, 45): 45 = 5 × b². Solve for b.","Write f(x) = a × b^{x}."]},{"id": "AlgI.25-13","std": "Alg I.25","q": "A taxi charges a flat fee plus a constant rate per mile. A 3-mile ride costs §11 and a 7-mile ride costs §19. Which function gives the cost C(m) for m miles?","a": "C(m) = 2m + 5","lvl": 2,"choices": ["C(m) = 5m + 2","C(m) = 2m + 11","C(m) = 4m − 1","C(m) = 2m + 5"],"steps": ["Find the rate per mile: (19 − 11) ÷ (7 − 3).","Plug (3, 11) and the rate into C = rate × m + b. Solve for b.","Write C(m) using the rate and b."]},{"id": "AlgI.25-14","std": "Alg I.25","q": "An exponential function passes through (1, 12) and (3, 108). What is the equation of the function?","a": "f(x) = 4(3)^x","lvl": 3,"choices": ["f(x) = 12(3)^x","f(x) = 4(3)^x","f(x) = 4(9)^x","f(x) = 3(4)^x"],"steps": ["Divide the outputs: 108 ÷ 12 = b², since x goes up by 2.","Find b, then use (1, 12) in 12 = a × b¹ to find a.","Write f(x) = a × b^{x}."]},{"id": "AlgI.25-15","std": "Alg I.25","q": "An exponential decay function passes through (0, 64) and (3, 8). What is the equation of the function?","a": "f(x) = 64(0.5)^x","lvl": 3,"choices": ["f(x) = 8(0.5)^x","f(x) = 64(0.5)^x","f(x) = 64(0.125)^x","f(x) = 64(0.25)^x"],"steps": ["From (0, 64), the initial value is a = 64.","Plug in (3, 8): 8 = 64 × b³. Solve for b.","Write f(x) = a × b^{x}."]},{"id": "AlgI.25-16","std": "Alg I.25","q": "An arithmetic sequence has a(4) = 17 and a(9) = 37. Which linear function f(n) represents this sequence?","a": "f(n) = 4n + 1","lvl": 3,"choices": ["f(n) = 4n − 1","f(n) = 4n + 1","f(n) = 5n − 3","f(n) = 4n + 17"],"steps": ["Find the common difference: (37 − 17) ÷ (9 − 4).","Plug (4, 17) and d into f(n) = dn + b. Solve for b.","Write f(n) = dn + b."]},{"id": "AlgI.26-07","std": "Alg I.26","q": "As x increases without bound, which type of function will eventually have the greatest output values?","a": "An exponential growth function","lvl": 1,"choices": ["A constant function","An exponential growth function","A linear function with a positive slope","A quadratic function opening upward"],"steps": ["Compare long-term growth of constant, linear, quadratic, and exponential.","Exponential growth multiplies outputs repeatedly by a factor > 1.","Which kind of function eventually beats the rest?"]},{"id": "AlgI.26-08","std": "Alg I.26","q": "Compare f(x) = 10x and g(x) = 2^x. At x = 1, f(1) = 10 and g(1) = 2. At x = 6, f(6) = 60 and g(6) = 64. What does this table show?","a": "The exponential function g(x) eventually exceeds the linear function f(x)","lvl": 1,"choices": ["The exponential function g(x) eventually exceeds the linear function f(x)","The linear function f(x) is always greater than g(x)","The exponential function g(x) is always greater than f(x)","The two functions grow at the same rate"],"steps": ["At x = 1, the linear function f(1) = 10 is greater than g(1) = 2.","By x = 6, the exponential function g(6) = 64 is greater than f(6) = 60.","What does the switch tell you about the two functions?"]},{"id": "AlgI.26-09","std": "Alg I.26","q": "For f(x) = x² and g(x) = 2^x, which function has a greater value at x = 5?","a": "g(x), because 32 > 25","lvl": 1,"choices": ["g(x), because 32 > 25","f(x), because 25 > 10","f(x), because 25 > 16","They are equal at x = 5"],"steps": ["Evaluate f(5) = 5² = 25.","Evaluate g(5) = 2⁵ = 32.","Compare 25 and 32."]},{"id": "AlgI.26-10","std": "Alg I.26","q": "Compare f(x) = 5x + 20 and g(x) = 3^x. What is the smallest positive integer x for which g(x) > f(x)?","a": "x = 4","lvl": 2,"choices": ["x = 3","x = 4","x = 5","x = 2"],"steps": ["Test x = 3: compare 5(3) + 20 with 3³.","Test x = 4: compare 5(4) + 20 with 3⁴.","Where does g first pass f?"]},{"id": "AlgI.26-11","std": "Alg I.26","q": "Compare f(x) = 2x² and g(x) = 2^x for positive integers x. At x = 4, f(4) = 32 and g(4) = 16. At what integer x does g(x) first exceed f(x)?","a": "x = 7","lvl": 2,"choices": ["x = 8","x = 5","x = 6","x = 7"],"steps": ["Check x = 5: compare 2(25) with 2⁵. Check x = 6 the same way.","Check x = 7: compare 2(49) with 2⁷.","Where does g first pass f?"]},{"id": "AlgI.26-12","std": "Alg I.26","q": "Option A pays §500 per day. Option B pays §1 on day 1, §2 on day 2, §4 on day 3, doubling each day. On which day does Option B's daily pay first exceed Option A's daily pay?","a": "Day 10","lvl": 2,"choices": ["Day 11","Day 10","Day 8","Day 9"],"steps": ["Model Option B's pay on day n as 2^{n − 1}.","Find the first power of 2 greater than 500: 2⁸ = 256, 2⁹ = 512.","Day n pays 2^{n − 1}. Which day has n − 1 = 9?"]},{"id": "AlgI.26-13","std": "Alg I.26","q": "Compare f(x) = 100x² and g(x) = 1.5^x. Why will g(x) eventually exceed f(x) even though f(10) = 10,000 is much larger than g(10) ≈ 57.67?","a": "A constant percentage growth factor eventually outpaces any fixed-degree polynomial growth","lvl": 3,"choices": ["g(x) has a greater slope at x = 0","A constant percentage growth factor eventually outpaces any fixed-degree polynomial growth","Quadratic functions stop increasing after x = 100","The y-intercept of g(x) is larger than the y-intercept of f(x)"],"steps": ["Recognize f(x) = 100x² as quadratic and g(x) = 1.5^{x} as exponential.","Exponential functions grow by a constant percentage factor each step.","Pick the choice that explains why repeated multiplying wins."]},{"id": "AlgI.26-14","std": "Alg I.26","q": "A table shows f(x) = x² + 10x and g(x) = 2^x. At x = 6, f(6) = 96 and g(6) = 64. At x = 7, f(7) = 119 and g(7) = 128. Between which two integers do the graphs intersect for x > 0?","a": "Between 6 and 7","lvl": 3,"choices": ["Between 6 and 7","Between 7 and 8","Between 64 and 96","Between 5 and 6"],"steps": ["At x = 6, f(6) = 96 is greater than g(6) = 64.","At x = 7, f(7) = 119 is less than g(7) = 128.","They switched order. Between which x-values did they cross?"]},{"id": "AlgI.26-15","std": "Alg I.26","q": "Which function will eventually exceed both f(x) = 500x + 10,000 and g(x) = 10x² as x approaches infinity?","a": "h(x) = 0.01(1.1)^x","lvl": 3,"choices": ["h(x) = 500(0.9)^x","h(x) = 1000x + 50,000","h(x) = 0.01(1.1)^x","h(x) = 25x² + 100"],"steps": ["Look for exponential growth: a base greater than 1.","500(0.9)^{x} shrinks because 0.9 < 1. The others are linear or quadratic.","Which choice has a base greater than 1?"]},{"id": "AlgI.27-07","std": "Alg I.27","q": "The cost C(h) in dollars to rent a kayak for h hours is modeled by C(h) = 12h + 15. What does the 15 represent?","a": "A flat rental fee of §15","lvl": 1,"choices": ["A flat rental fee of §15","The discount is §15","The cost per hour is §15","The maximum rental time is 15 hours"],"steps": ["In C(h) = 12h + 15, the 15 is the constant term.","Find the cost at h = 0 hours.","So what does that 15 stand for?"]},{"id": "AlgI.27-08","std": "Alg I.27","q": "The population P(t) of a town t years after 2020 is modeled by P(t) = 8,500(1.04)^t. What does 8,500 represent?","a": "The population of the town in 2020","lvl": 1,"choices": ["The growth rate of the town","The population after 4 years","The number of people added each year","The population of the town in 2020"],"steps": ["In P(t) = 8,500(1.04)^{t}, 8,500 is the initial value when t = 0.","Since t is years after 2020, t = 0 corresponds to the year 2020.","So what does 8,500 stand for?"]},{"id": "AlgI.27-09","std": "Alg I.27","q": "In the function f(x) = 45 − 3x, which models the number of gallons of water left in a tank after x minutes, what does −3 represent?","a": "The tank loses 3 gallons of water per minute","lvl": 1,"choices": ["The tank loses 3 gallons of water per minute","The tank starts with 3 gallons of water","The tank gains 3 gallons every 45 minutes","The tank empties in 3 minutes"],"steps": ["In f(x) = 45 − 3x, −3 is the slope (rate of change per minute).","The negative sign means the amount of water is decreasing.","So what does −3 stand for?"]},{"id": "AlgI.27-10","std": "Alg I.27","q": "The value V(t) of a car t years after purchase is modeled by V(t) = 24,000(0.86)^t. What does 0.86 indicate about the car's value?","a": "The car loses 14% of its value each year","lvl": 2,"choices": ["The car loses 14% of its value each year","The car loses 86% of its value each year","The car gains 86% of its value each year","The car loses §860 each year"],"steps": ["Identify 0.86 as the decay factor 1 − r.","Solve 1 − r = 0.86 to find r = 0.14, or 14%.","Is that a gain or a loss each year?"]},{"id": "AlgI.27-11","std": "Alg I.27","q": "A bacteria culture is modeled by B(t) = 300(1.25)^t, where t is in hours. What does 1.25 represent in this context?","a": "The bacteria population increases by 25% each hour","lvl": 2,"choices": ["The bacteria population increases by 125% each hour","There are 125 bacteria initially","The bacteria population increases by 1.25 bacteria each hour","The bacteria population increases by 25% each hour"],"steps": ["Identify 1.25 as the growth factor 1 + r.","Solve 1 + r = 1.25 to find r = 0.25, or 25%.","Is that growth or decay each hour?"]},{"id": "AlgI.27-12","std": "Alg I.27","q": "A phone plan charges C(g) = 35 + 8g dollars for using g gigabytes of data. What does the parameter 8 represent?","a": "An additional charge of §8 per gigabyte of data","lvl": 2,"choices": ["8 gigabytes are included for free","The base monthly fee is §8","The total cost for 35 gigabytes","An additional charge of §8 per gigabyte of data"],"steps": ["In C(g) = 35 + 8g, 8 is the slope multiplying gigabytes g.","Each additional gigabyte increases the cost by 8 dollars.","So what does the 8 stand for?"]},{"id": "AlgI.27-13","std": "Alg I.27","q": "An investment is modeled by A(t) = 1,200(1.06)^{2t}, where t is in years. What does the base 1.06 represent?","a": "A 6% growth rate every half-year","lvl": 3,"choices": ["A 6% annual growth rate","A 12% growth rate every half-year","A 6% growth rate every 2 years","A 6% growth rate every half-year"],"steps": ["The base 1.06 = 1 + 0.06 shows a 6% growth rate per compounding period.","The exponent 2t means there are 2 compounding periods per year.","So 6% happens how often?"]},{"id": "AlgI.27-14","std": "Alg I.27","q": "A cup of coffee cools according to T(m) = 70 + 120(0.92)^m, where m is minutes. What does the 70 represent in this context?","a": "The room temperature in degrees that the coffee approaches","lvl": 3,"choices": ["The number of minutes until the coffee is cold","The room temperature in degrees that the coffee approaches","The temperature drop per minute","The initial temperature of the coffee"],"steps": ["As m increases, (0.92)^{m} approaches 0, so 120(0.92)^{m} approaches 0.","Therefore, T(m) approaches 70 + 0 = 70 over time.","So what temperature is the coffee getting close to?"]},{"id": "AlgI.27-15","std": "Alg I.27","q": "The remaining mass of a medicine in the bloodstream is M(t) = 500(0.5)^{{t/4}}, where t is hours. What does the 4 in the exponent represent?","a": "The mass is cut in half every 4 hours","lvl": 3,"choices": ["The mass decreases by 4 mg per hour","The medicine is completely gone after 4 hours","The mass is cut in half every 4 hours","The initial dose is taken 4 times a day"],"steps": ["The base 0.5 means the remaining mass is cut in half each period.","The exponent {t/4} equals 1 when t = 4 hours.","So what happens to the mass every 4 hours?"]},{"id": "AlgI.28-09","std": "Alg I.28","q": "The height h(t) of a ball thrown upward is graphed against time t in seconds. What does the vertex of the parabola represent?","a": "The maximum height of the ball and the time it reaches that height","lvl": 1,"choices": ["The initial height of the ball","The speed of the ball at t = 0","The maximum height of the ball and the time it reaches that height","The time when the ball hits the ground"],"steps": ["A ball thrown upward forms a downward-opening parabola.","The vertex is the highest point on a downward-opening parabola.","So what two facts does the vertex give?"]},{"id": "AlgI.28-10","std": "Alg I.28","q": "On a graph of a runner's distance from home over time, what does a horizontal line segment represent?","a": "The runner is stopped and not moving","lvl": 1,"choices": ["The runner is stopped and not moving","The runner is returning home","The runner is speeding up","The runner is moving at a fast constant speed"],"steps": ["A horizontal segment has a slope of 0, meaning y does not change.","Here y is distance from home, so distance stays constant as time passes.","So what is the runner doing?"]},{"id": "AlgI.28-11","std": "Alg I.28","q": "A profit function P(x) models profit in dollars from selling x items. What does a positive x-intercept of the graph represent?","a": "The break-even number of items where profit is §0","lvl": 1,"choices": ["The break-even number of items where profit is §0","The maximum profit possible","The profit per item sold","The fixed startup cost"],"steps": ["At an x-intercept, the output y-value is 0.","Here y is profit P(x) and x is the number of items sold.","So what does profit 0 mean for the business?"]},{"id": "AlgI.28-12","std": "Alg I.28","q": "The temperature of a city over 24 hours increases from 6 AM to 3 PM and decreases from 3 PM to midnight. On which interval is the temperature function increasing?","a": "From 6 AM to 3 PM","lvl": 2,"choices": ["From 3 PM to midnight","Over the entire 24-hour period","From 6 AM to 3 PM","From midnight to 6 AM"],"steps": ["A function is increasing where its output values go up as time moves forward.","Read when the temperature goes up.","Which interval matches?"]},{"id": "AlgI.28-13","std": "Alg I.28","q": "A rocket is launched from a platform. Its height is modeled by h(t) = −16t² + 64t + 80. What does the y-intercept (0, 80) represent?","a": "The rocket was launched from a height of 80 feet","lvl": 2,"choices": ["The rocket was launched from a height of 80 feet","The rocket's initial speed is 80 feet per second","The rocket stays in the air for 80 seconds","The rocket reaches a maximum height of 80 feet"],"steps": ["At the y-intercept (0, 80), time is t = 0 and height is h = 80.","Time t = 0 is the exact moment of launch.","So what does 80 tell you about the launch?"]},{"id": "AlgI.28-14","std": "Alg I.28","q": "The distance d(t) from a drone to a target is modeled by an absolute value function with vertex at (5, 0). What happened at t = 5?","a": "The drone reached the target","lvl": 2,"choices": ["The drone flew at a height of 5 feet","The drone started its flight","The drone was farthest from the target","The drone reached the target"],"steps": ["At the vertex (5, 0), time is t = 5 and distance to target is d = 0.","A distance of 0 means the drone is at the target.","So what happened at t = 5?"]},{"id": "AlgI.28-15","std": "Alg I.28","q": "A piecewise function models a parking garage fee: §4 for up to 2 hours, then §2 per additional hour. How does the graph behave at x = 2?","a": "It changes from a horizontal segment at y = 4 to a line with slope 2 starting at (2, 4)","lvl": 3,"choices": ["It drops to y = 0 and starts over","It curves upward like a parabola","It changes from a horizontal segment at y = 4 to a line with slope 2 starting at (2, 4)","It continues as a horizontal line at y = 6"],"steps": ["For 0 < x ≤ 2, the flat fee of 4 gives a horizontal segment at y = 4.","After x = 2, adding 2 per hour gives a line with slope 2 starting at (2, 4).","Pick the choice that describes that switch."]},{"id": "AlgI.28-16","std": "Alg I.28","q": "For a ball's height h(t) = −16t² + 32t + 48, the graph crosses the t-axis at t = −1 and t = 3. Why is t = −1 not a reasonable part of the domain in context?","a": "Time after the ball is thrown cannot be negative","lvl": 3,"choices": ["Time after the ball is thrown cannot be negative","The parabola does not exist for negative x","The ball hits the ground at t = −1","The ball cannot be at a height of 0"],"steps": ["Identify what t represents: time in seconds after the ball is thrown.","Negative time (t = −1) would be before the ball was even thrown.","Can time before the throw be part of this situation?"]},{"id": "AlgI.28-17","std": "Alg I.28","q": "An exponential decay graph models the amount of caffeine in a person's body over time. What does the horizontal asymptote at y = 0 represent?","a": "The amount of caffeine approaches 0 but theoretically never reaches exactly 0","lvl": 3,"choices": ["The caffeine is completely gone after 1 hour","The caffeine level stays constant over time","The amount of caffeine approaches 0 but theoretically never reaches exactly 0","The person drank 0 mg of caffeine initially"],"steps": ["A horizontal asymptote at y = 0 means the graph gets closer and closer to 0.","An exponential decay curve never actually touches or crosses y = 0.","Pick the choice that matches that idea."]},{"id": "AlgI.29-08","std": "Alg I.29","q": "What is the average rate of change of f(x) = 3x + 5 from x = 1 to x = 4?","a": "3","lvl": 1,"choices": ["3","5","9","12"],"steps": ["f(x) = 3x + 5 is linear. Its slope is the number in front of x.","A linear function's average rate of change equals its slope.","So what is the rate from x = 1 to x = 4?"]},{"id": "AlgI.29-09","std": "Alg I.29","q": "A table shows f(0) = 2 and f(3) = 14. What is the average rate of change of f(x) over the interval [0, 3]?","a": "4","lvl": 1,"choices": ["3","4","6","12"],"steps": ["Average rate of change = (f(b) − f(a)) ÷ (b − a).","Use f(3) = 14 and f(0) = 2: (14 − 2) ÷ (3 − 0).","Simplify that division."]},{"id": "AlgI.29-10","std": "Alg I.29","q": "For f(x) = x², what is the average rate of change from x = 1 to x = 3?","a": "4","lvl": 1,"choices": ["2","3","4","8"],"steps": ["Find f(1) and f(3) for f(x) = x².","Set up (f(3) − f(1)) ÷ (3 − 1).","Simplify that division."]},{"id": "AlgI.29-11","std": "Alg I.29","q": "What is the average rate of change of f(x) = 2^x over the interval [1, 4]?","a": "{14/3}","lvl": 2,"choices": ["{14/3}","14","4","{16/3}"],"steps": ["Find f(1) = 2¹ and f(4) = 2⁴.","Set up (f(4) − f(1)) ÷ (4 − 1).","Simplify. Leave it as a fraction if it does not divide evenly."]},{"id": "AlgI.29-12","std": "Alg I.29","q": "A car's distance in miles is recorded as d(1) = 55 and d(4) = 220, where t is in hours. What does the average rate of change over [1, 4] mean in context?","a": "The car traveled an average of 55 miles per hour between hour 1 and hour 4","lvl": 2,"choices": ["The car was moving at 165 miles per hour","The car traveled an average of 55 miles per hour between hour 1 and hour 4","The car traveled a total of 55 miles","The car increased its speed by 55 mph each hour"],"steps": ["Average rate = (220 − 55) ÷ (4 − 1).","Miles divided by hours gives miles per hour.","Pick the choice that matches the rate and its meaning."]},{"id": "AlgI.29-13","std": "Alg I.29","q": "What is the average rate of change of f(x) = |x − 2| over the interval [0, 5]?","a": "{1/5}","lvl": 2,"choices": ["{3/5}","{1/5}","1","5"],"steps": ["Find f(0) = |0 − 2| and f(5) = |5 − 2|.","Set up (f(5) − f(0)) ÷ (5 − 0).","Simplify that fraction."]},{"id": "AlgI.29-14","std": "Alg I.29","q": "For f(x) = x² − 4x + 3, compare the average rate of change over [0, 2] and over [2, 4].","a": "It is −2 on [0, 2] and 2 on [2, 4]","lvl": 3,"choices": ["It is 2 on both intervals","It is 0 on both intervals","It is −4 on [0, 2] and 4 on [2, 4]","It is −2 on [0, 2] and 2 on [2, 4]"],"steps": ["Find f(0), f(2), and f(4).","On [0, 2]: (f(2) − f(0)) ÷ (2 − 0).","On [2, 4]: (f(4) − f(2)) ÷ (4 − 2). Compare the two."]},{"id": "AlgI.29-15","std": "Alg I.29","q": "A ball's height is h(t) = −16t² + 80t. What is the average rate of change of the ball's height from t = 1 to t = 4, and what does it mean?","a": "0 feet per second; the ball is at the same height at t = 1 and t = 4","lvl": 3,"choices": ["32 feet per second; the ball rises 32 feet per second","−16 feet per second; the ball is falling","0 feet per second; the ball did not move between t = 1 and t = 4","0 feet per second; the ball is at the same height at t = 1 and t = 4"],"steps": ["Find h(1) = −16(1)² + 80(1) and h(4) = −16(4)² + 80(4).","Set up (h(4) − h(1)) ÷ (4 − 1).","What does that rate say about the ball's height at t = 1 and t = 4?"]},{"id": "AlgI.29-16","std": "Alg I.29","q": "For f(x) = 3(2)^x, how does the average rate of change on [2, 3] compare to the average rate of change on [0, 1]?","a": "It is 4 times as great","lvl": 3,"choices": ["It is 2 times as great","It is 4 times as great","It is the same","It is 8 times as great"],"steps": ["On [0, 1]: f(0) = 3 and f(1) = 6. Find the rate.","On [2, 3]: find f(2) and f(3), then the rate.","Divide the second rate by the first."]},{"id": "AlgI.30-10","std": "Alg I.30","q": "What are the x- and y-intercepts of the linear function f(x) = 2x − 6?","a": "x-intercept (3, 0) and y-intercept (0, −6)","lvl": 1,"part": "a","choices": ["x-intercept (2, 0) and y-intercept (0, −6)","x-intercept (−6, 0) and y-intercept (0, 3)","x-intercept (3, 0) and y-intercept (0, −6)","x-intercept (−3, 0) and y-intercept (0, 6)"],"steps": ["For the y-intercept, set x = 0: f(0) = 2(0) − 6 = −6, giving (0, −6).","For the x-intercept, set 2x − 6 = 0 to get 2x = 6 and x = 3.","Pick the choice with both intercepts."]},{"id": "AlgI.30-11","std": "Alg I.30","q": "What is the vertex of the quadratic function f(x) = (x − 4)² + 2?","a": "(4, 2)","lvl": 1,"part": "a","choices": ["(−4, 2)","(4, 2)","(2, 4)","(4, −2)"],"steps": ["Compare (x − 4)² + 2 with vertex form a(x − h)² + k.","Find h and k. Watch the sign on h.","Write the vertex as (h, k)."]},{"id": "AlgI.30-12","std": "Alg I.30","q": "What is the y-intercept of the exponential function f(x) = 5(2)^x?","a": "(0, 5)","lvl": 1,"part": "c","choices": ["(0, 5)","(0, 2)","(5, 0)","(0, 10)"],"steps": ["To find the y-intercept, plug x = 0 into 5(2)^{x}.","Any nonzero number to the 0 power is 1.","Write the y-intercept as a point (0, y)."]},{"id": "AlgI.30-13","std": "Alg I.30","q": "For the quadratic function f(x) = −x² + 6x − 5, what is the maximum value of the function?","a": "4","lvl": 2,"part": "a","choices": ["−5","3","4","5"],"steps": ["The vertex is at x = −b ÷ (2a) = −6 ÷ (2 × (−1)).","Plug that x into f(x) = −x² + 6x − 5.","a < 0, so the vertex is the highest point. What is f there?"]},{"id": "AlgI.30-14","std": "Alg I.30","q": "What is the vertex and direction of opening for the absolute value function f(x) = -|x + 3| + 5?","a": "Vertex at (−3, 5), opening downward","lvl": 2,"part": "b","choices": ["Vertex at (−3, 5), opening upward","Vertex at (−3, 5), opening downward","Vertex at (3, 5), opening downward","Vertex at (3, −5), opening upward"],"steps": ["Rewrite f(x) = −|x − (−3)| + 5 to identify vertex (h, k) = (−3, 5).","Notice the negative sign in front of the absolute value (a = −1 < 0).","So what is the vertex, and which way does it open?"]},{"id": "AlgI.30-15","std": "Alg I.30","q": "Describe the end behavior of f(x) = 3(0.5)^x as x approaches positive infinity.","a": "f(x) approaches 0","lvl": 2,"part": "c","choices": ["f(x) approaches negative infinity","f(x) approaches positive infinity","f(x) approaches 3","f(x) approaches 0"],"steps": ["The base 0.5 is between 0 and 1, so this is decay.","As x gets large, what happens to (0.5)^{x}?","So what does 3(0.5)^{x} get close to?"]},{"id": "AlgI.30-16","std": "Alg I.30","q": "A step function rounds any positive number x up to the next whole integer. On the interval (2, 3], what is the constant y-value of the graph?","a": "3","lvl": 3,"part": "b","choices": ["2","2.5","3","4"],"steps": ["The interval (2, 3] includes all numbers greater than 2 up to and including 3.","Rounding any number like 2.1, 2.5, or 3 up to the next integer gives 3.","So what y-value is the graph on that interval?"]},{"id": "AlgI.30-17","std": "Alg I.30","q": "A piecewise function is defined by f(x) = x + 1 for x < 2 and f(x) = 2x − 3 for x ≥ 2. Which point has an open circle on the graph?","a": "(2, 3)","lvl": 3,"part": "b","choices": ["(0, 1)","(2, 2)","(2, 1)","(2, 3)"],"steps": ["An open circle occurs at the boundary of a strict inequality (x < 2).","Plug x = 2 into the first rule f(x) = x + 1 to get 2 + 1 = 3.","Which point gets the open circle?"]},{"id": "AlgI.30-18","std": "Alg I.30","q": "Which quadratic function has x-intercepts at (−2, 0) and (4, 0) and a minimum value of −9?","a": "f(x) = (x + 2)(x − 4)","lvl": 3,"part": "a","choices": ["f(x) = (x − 2)(x + 4)","f(x) = (x + 2)(x − 4)","f(x) = −(x + 2)(x − 4)","f(x) = 2(x + 2)(x − 4)"],"steps": ["Zeros at −2 and 4 give the form f(x) = a(x + 2)(x − 4).","The vertex x is halfway between −2 and 4.","Plug in that x with y = −9 and solve for a."]},{"id": "AlgI.31-07","std": "Alg I.31","q": "In the mathematical modeling cycle, what is the first step when solving a real-world problem?","a": "Identify the problem, variables, and assumptions","lvl": 1,"choices": ["Graph an exponential function","Solve an equation for x","Report the final answer immediately","Identify the problem, variables, and assumptions"],"steps": ["Recall the stages of the mathematical modeling cycle.","Before building equations, define the problem and variables.","So what comes first in the cycle?"]},{"id": "AlgI.31-08","std": "Alg I.31","q": "A bakery sells cupcakes for §3 each and has §120 in daily fixed costs. Which function models daily profit P(x) for selling x cupcakes?","a": "P(x) = 3x − 120","lvl": 1,"choices": ["P(x) = 3x − 120","P(x) = 120 − 3x","P(x) = 3x + 120","P(x) = 120x − 3"],"steps": ["Find revenue from selling x cupcakes at 3 dollars each: 3x.","Subtract daily fixed costs of 120 dollars from revenue.","Write P(x) as revenue minus fixed costs."]},{"id": "AlgI.31-09","std": "Alg I.31","q": "Why is validating a mathematical model against real-world data an essential step in the modeling cycle?","a": "To check whether the model makes reasonable and accurate predictions","lvl": 1,"choices": ["To eliminate all rounding in calculations","To check whether the model makes reasonable and accurate predictions","To guarantee the model is always linear","To avoid having to define variables"],"steps": ["Compare the model's outputs with actual real-world data.","Validating tests whether predictions are reasonable and accurate.","So why do we compare a model to real data?"]},{"id": "AlgI.31-10","std": "Alg I.31","q": "A rectangular garden is enclosed with 40 feet of fencing. If w is the width, the area is modeled by A(w) = w(20 − w). What width maximizes the area?","a": "10 feet","lvl": 2,"choices": ["5 feet","10 feet","20 feet","40 feet"],"steps": ["Find the zeros of A(w) = w(20 − w).","A downward parabola's maximum is halfway between its zeros.","Find the number halfway between the zeros."]},{"id": "AlgI.31-11","std": "Alg I.31","q": "A streaming service charges §10 per month for up to 2 screens, and §3 extra per month for each additional screen. Which type of function best models the monthly cost?","a": "A linear piecewise function","lvl": 2,"choices": ["A constant function","An exponential decay function","A quadratic function","A linear piecewise function"],"steps": ["For 1 to 2 screens, cost is constant at 10 dollars.","Above 2 screens, cost increases linearly by 3 dollars per screen.","What do you call two linear rules on different intervals?"]},{"id": "AlgI.31-12","std": "Alg I.31","q": "A viral video has 500 views at noon and triples its views every hour. Using the model V(t) = 500(3)^t, how many views are predicted at 3 PM?","a": "13,500 views","lvl": 2,"choices": ["1,500 views","4,500 views","13,500 views","40,500 views"],"steps": ["Find hours elapsed from noon to 3 PM: t = 3.","Substitute t = 3 into V(t) = 500(3)^{t} to get 500 × 3³.","Multiply 500 × 27."]},{"id": "AlgI.31-13","std": "Alg I.31","q": "An exponential model predicts a town's population will reach 50 million in 40 years, even though the town only has 2 square miles of land. What should a modeler do next?","a": "Revise the model to account for space limits and carrying capacity","lvl": 3,"choices": ["Keep the model because exponential math is exact","Ignore the land constraint and report 50 million","Revise the model to account for space limits and carrying capacity","Change the initial population to 0"],"steps": ["Check if 50 million people on 2 square miles is realistic.","Exponential growth ignores physical limits like available land.","So what should the modeler do next?"]},{"id": "AlgI.31-14","std": "Alg I.31","q": "A quality control machine accepts bolts whose length x is within 0.05 mm of 12 mm. Which function measures the error E(x) from the target length?","a": "E(x) = |x − 12|","lvl": 3,"choices": ["E(x) = x − 12","E(x) = 12x − 0.05","E(x) = |x + 12|","E(x) = |x − 12|"],"steps": ["Error is how far x is from the 12 mm target.","The difference is x − 12. It can be negative.","Distance can't be negative. What symbol fixes that?"]},{"id": "AlgI.31-15","std": "Alg I.31","q": "A ticket price starts at §20 with 100 buyers. For each §1 increase x, 4 fewer people buy tickets. Revenue is R(x) = (20 + x)(100 − 4x). What ticket price maximizes revenue?","a": "§22.50","lvl": 3,"choices": ["§20.00","§22.00","§22.50","§25.00"],"steps": ["Find the zeros of R(x) = (20 + x)(100 − 4x): x = −20 and x = 25.","Find the vertex x-value halfway between: (−20 + 25) ÷ 2 = 2.5.","Add 2.5 to the §20 base price."]},{"id": "AlgI.32-07","std": "Alg I.32","q": "In a two-way frequency table of 100 students, 40 play a sport and 60 do not. What is the marginal relative frequency of students who play a sport?","a": "0.40","lvl": 1,"choices": ["0.25","0.40","0.60","40"],"steps": ["Identify the number of students who play a sport: 40.","Divide by the grand total of 100 students: {40/100}.","Write that fraction as a decimal."]},{"id": "AlgI.32-08","std": "Alg I.32","q": "In a survey of 200 adults, 30 own both a dog and a cat. What is the joint relative frequency of owning both a dog and a cat?","a": "0.15","lvl": 1,"choices": ["0.06","0.15","0.30","0.60"],"steps": ["Identify the joint count for both dog and cat: 30.","Divide by the total surveyed (200): {30/200}.","Write that fraction as a decimal."]},{"id": "AlgI.32-09","std": "Alg I.32","q": "Which type of data is summarized in a two-way frequency table?","a": "Bivariate categorical data","lvl": 1,"choices": ["Continuous time-series data","Bivariate categorical data","Bivariate quantitative data only","Univariate numerical data"],"steps": ["Rows represent categories of one variable; columns represent another.","Two variables together are called bivariate data.","So what kind of data is in a two-way table?"]},{"id": "AlgI.32-10","std": "Alg I.32","q": "In a clinical trial, 10 of 100 patients taking Medicine A got a headache, while 25 of 100 patients taking a placebo got a headache. What is the conditional relative frequency of getting a headache given Medicine A?","a": "0.10","lvl": 2,"choices": ["0.10","0.175","0.25","0.35"],"steps": ["Restrict to the given group: 100 patients taking Medicine A.","Identify how many in that group got a headache: 10.","Divide by the group's total."]},{"id": "AlgI.32-11","std": "Alg I.32","q": "Out of 80 ninth graders, 48 prefer math. Out of 120 tenth graders, 72 prefer math. What does comparing the conditional relative frequencies suggest?","a": "There is no association between grade level and preferring math, since both are 60%","lvl": 2,"choices": ["There is a strong negative association","Ninth graders are more likely to prefer math","There is no association between grade level and preferring math, since both are 60%","Tenth graders are much more likely to prefer math because 72 > 48"],"steps": ["Find 9th grade rate: {48/80} = 0.60, or 60%.","Find 10th grade rate: {72/120} = 0.60, or 60%.","Are the two rates the same? What does that tell you?"]},{"id": "AlgI.32-12","std": "Alg I.32","q": "In a safety study, 4 out of 200 drivers wearing seatbelts were injured in minor crashes, compared to 20 out of 100 drivers not wearing seatbelts. What is the risk of injury for drivers not wearing seatbelts?","a": "20%","lvl": 2,"choices": ["2%","8%","10%","20%"],"steps": ["Focus on drivers not wearing seatbelts: 100 total.","Identify how many of them were injured: 20.","Divide, then write it as a percent."]},{"id": "AlgI.32-13","std": "Alg I.32","q": "In a study, the risk of a cold is 8% for people who wash hands frequently and 24% for those who do not. What is the relative risk of getting a cold for those who do not wash hands frequently compared to those who do?","a": "3 times as likely","lvl": 3,"choices": ["0.33 times as likely","2 times as likely","3 times as likely","16 times as likely"],"steps": ["Identify the two risks: 24% (infrequent) and 8% (frequent).","Divide the higher risk by the baseline risk: 24% ÷ 8%.","Do the division."]},{"id": "AlgI.32-14","std": "Alg I.32","q": "A two-way table shows 60% of Group A and 62% of Group B chose Option 1, with 50 people per group. Which conclusion is most appropriate?","a": "There appears to be little to no meaningful association between group and choice","lvl": 3,"choices": ["Group B definitely causes people to choose Option 1","The two variables are perfectly correlated","Group A strongly avoids Option 1","There appears to be little to no meaningful association between group and choice"],"steps": ["Compare the two conditional percentages: 60% and 62%.","A 2% difference in groups of 50 is just 1 person.","Is that difference big enough to show an association?"]},{"id": "AlgI.32-15","std": "Alg I.32","q": "Why is it important to use conditional relative frequencies instead of raw counts when comparing groups of different sizes in a two-way table?","a": "Raw counts can be misleading when one group has many more total individuals than another","lvl": 3,"choices": ["Raw counts can be misleading when one group has many more total individuals than another","Raw counts cannot be added together","Conditional relative frequencies prove causation","Conditional relative frequencies are always larger than raw counts"],"steps": ["Larger groups naturally have higher raw counts.","Conditional relative frequencies put each group on a 100% scale.","Pick the choice that explains why raw counts can mislead."]},{"id": "AlgI.33-07","std": "Alg I.33","q": "Which research question investigates an association between two categorical variables?","a": "Is there an association between grade level (9th vs. 10th) and preferred lunch option?","lvl": 1,"choices": ["How does study time in hours relate to test score?","What is the median number of pets owned by students?","Is there an association between grade level (9th vs. 10th) and preferred lunch option?","What is the average height of 9th-grade students?"],"steps": ["Look for a question with two variables that use categories.","Grade level (9th vs. 10th) and lunch option are both categories.","Which choice uses two categorical variables?"]},{"id": "AlgI.33-08","std": "Alg I.33","q": "When designing a survey to investigate whether students' favorite music genre is associated with whether they play an instrument, how should participants be selected to reduce bias?","a": "Use a random sample of students from the whole school","lvl": 1,"choices": ["Survey only students in the school band","Use a random sample of students from the whole school","Ask students who volunteer after school","Survey only your close friends"],"steps": ["Surveying only band members, friends, or volunteers creates bias.","Every student in the school should have an equal chance of selection.","Which choice gives every student an equal chance?"]},{"id": "AlgI.33-09","std": "Alg I.33","q": "Which display is best for organizing the results of an investigation into two categorical variables?","a": "A two-way frequency table","lvl": 1,"choices": ["A scatter plot","A two-way frequency table","A dot plot","A box-and-whisker plot"],"steps": ["Scatter, box, and dot plots are for quantitative data.","Two categorical variables need rows and columns for counts.","Which display uses rows and columns of counts?"]},{"id": "AlgI.33-10","std": "Alg I.33","q": "A student surveys 100 randomly chosen classmates about whether they drink coffee and whether they get at least 8 hours of sleep. 20% of coffee drinkers get 8+ hours of sleep, compared to 65% of non-coffee drinkers. What claim is supported?","a": "There appears to be an association between drinking coffee and getting less than 8 hours of sleep","lvl": 2,"choices": ["There is no association between coffee and sleep","Drinking coffee causes students to lose sleep","All students who do not drink coffee sleep 8+ hours","There appears to be an association between drinking coffee and getting less than 8 hours of sleep"],"steps": ["Compare 8+ hour sleep rates: 20% (coffee) vs. 65% (no coffee).","The large gap supports an association between coffee and less sleep.","Can a survey prove cause? Pick the claim that fits."]},{"id": "AlgI.33-11","std": "Alg I.33","q": "Why should a persuasive argument based on an observational survey avoid claiming that one variable caused the other?","a": "Observational studies can show association, but confounding variables may explain the relationship","lvl": 2,"choices": ["Only studies with 10,000 people can show association","Categorical variables can never be related","Observational studies can show association, but confounding variables may explain the relationship","Surveys never use numbers"],"steps": ["Observational surveys do not randomly assign treatments.","Confounding variables could explain the observed pattern.","So what should the argument report instead?"]},{"id": "AlgI.33-12","std": "Alg I.33","q": "In a school investigation, 15 out of 20 athletes and 18 out of 40 non-athletes bring a reusable water bottle. Which piece of evidence best supports a claim of association?","a": "75% of athletes bring a reusable bottle compared to 45% of non-athletes","lvl": 2,"choices": ["75% of athletes bring a reusable bottle compared to 45% of non-athletes","20 athletes is less than 40 non-athletes","There were 60 total students surveyed","18 non-athletes is greater than 15 athletes"],"steps": ["Compute athlete rate: {15/20} = 75%.","Compute non-athlete rate: {18/40} = 45%.","Which choice uses rates instead of raw counts?"]},{"id": "AlgI.33-13","std": "Alg I.33","q": "A student wants to know if bus riders are more likely to eat school breakfast than car riders. She surveys 50 students arriving at the bus loop. What is the main flaw in her investigation design?","a": "Her sample excludes car riders, so she cannot compare the two groups","lvl": 3,"choices": ["She should have used a scatter plot instead","Eating breakfast is not a categorical variable","Her sample excludes car riders, so she cannot compare the two groups","50 students is too many to survey"],"steps": ["Check which groups are needed: bus riders and car riders.","Surveying only at the bus loop excludes car riders completely.","What group is missing from her sample?"]},{"id": "AlgI.33-14","std": "Alg I.33","q": "Which element makes a persuasive argument from a categorical data investigation strongest?","a": "Citing conditional relative frequencies, describing the sampling method, and noting any limitations","lvl": 3,"choices": ["Citing conditional relative frequencies, describing the sampling method, and noting any limitations","Leaving out data that does not fit the hypothesis","Using only raw totals and ignoring sample size","Claiming 100% proof of cause and effect"],"steps": ["Strong arguments use conditional relative frequencies, not raw counts.","Explain how the sample was chosen to show reliability.","Which choice includes all three of these?"]},{"id": "AlgI.33-15","std": "Alg I.33","q": "Two students investigate whether owning a pet is associated with participating in clubs. Student A surveys 12 friends; Student B surveys 150 randomly selected students. Whose conclusion is more reliable and why?","a": "Student B, because a larger random sample reduces bias and sampling variability","lvl": 3,"choices": ["Student B, because a larger random sample reduces bias and sampling variability","Both are equally reliable because they asked the same question","Student A, because friends answer more honestly","Student A, because smaller samples have no errors"],"steps": ["Compare sampling methods: 12 friends vs. 150 random students.","Random sampling reduces bias; a larger size lowers variability.","Whose sample is random and larger?"]},{"id": "AlgI.34-08","std": "Alg I.34","q": "Which of the following is an example of categorical data?","a": "The favorite movie genre of each student in a class","lvl": 1,"choices": ["The favorite movie genre of each student in a class","The height of each student in centimeters","The number of minutes spent on homework last night","The weight of each backpack in pounds"],"steps": ["Categorical data places items into named groups or labels.","Height, minutes, and weight are numerical measurements.","Which choice is a label, not a number?"]},{"id": "AlgI.34-09","std": "Alg I.34","q": "Which of the following is an example of quantitative data?","a": "The daily high temperature in degrees Fahrenheit","lvl": 1,"choices": ["The daily high temperature in degrees Fahrenheit","The eye color of each participant","The state in which a person was born","The brand of phone each person owns"],"steps": ["Quantitative data consists of numerical measurements or counts.","Phone brand, eye color, and birth state are categories.","Which choice is a measured number?"]},{"id": "AlgI.34-10","std": "Alg I.34","q": "Which summary measure is appropriate for quantitative data but NOT for categorical data?","a": "Mean","lvl": 1,"choices": ["Relative frequency","Frequency count","Percentage per category","Mean"],"steps": ["Counts, percentages, and relative frequencies work for categories.","Which measure needs you to add values and divide?","That one works only for numbers."]},{"id": "AlgI.34-11","std": "Alg I.34","q": "A dataset records each car's zip code of registration and its fuel efficiency in miles per gallon. How should these two variables be classified?","a": "Zip code is categorical; fuel efficiency is quantitative","lvl": 2,"choices": ["Zip code is categorical; fuel efficiency is quantitative","Both zip code and fuel efficiency are quantitative","Both zip code and fuel efficiency are categorical","Zip code is quantitative; fuel efficiency is categorical"],"steps": ["Zip codes use digits only as location labels, so they are categorical.","Fuel efficiency in mpg is a measurable number, so it is quantitative.","Match each variable to its type."]},{"id": "AlgI.34-12","std": "Alg I.34","q": "Which pair of graphs is best suited for displaying categorical data rather than quantitative data?","a": "Bar graph and segmented bar graph","lvl": 2,"choices": ["Box plot and stem-and-leaf plot","Histogram and box plot","Bar graph and segmented bar graph","Scatter plot and dot plot"],"steps": ["Histograms, box, scatter, dot, and stem plots show numerical data.","Bar graphs and segmented bar graphs display category counts or rates.","Which pair shows category counts?"]},{"id": "AlgI.34-13","std": "Alg I.34","q": "A researcher collects the number of siblings each student has and whether each student rides the bus. Which analysis technique matches each variable?","a": "Use mean or median for number of siblings, and proportions for bus riding","lvl": 2,"choices": ["Use a scatter plot to find the slope between the two variables","Use mean for both variables","Use mean or median for number of siblings, and proportions for bus riding","Use proportions only for number of siblings, and median for bus riding"],"steps": ["Number of siblings is a count, so it is quantitative.","Riding the bus is yes or no, so it is categorical.","Which tools fit each kind of variable?"]},{"id": "AlgI.34-14","std": "Alg I.34","q": "A jersey number on a basketball team is written with digits such as 12, 23, and 34. Why is jersey number considered categorical data rather than quantitative data?","a": "The numbers serve only as labels, so averaging or subtracting them has no meaningful interpretation","lvl": 3,"choices": ["Jersey numbers can never be greater than 99","Jersey numbers are always whole numbers","The numbers serve only as labels, so averaging or subtracting them has no meaningful interpretation","There are fewer than 50 players on a team"],"steps": ["Test whether arithmetic on jersey numbers makes sense.","Averaging or subtracting jersey numbers has no real meaning.","So what kind of data are labels?"]},{"id": "AlgI.34-15","std": "Alg I.34","q": "A school records student test scores as exact percentages (0 to 100) and also assigns letter grades (A, B, C, D, F). How does the choice of variable change the appropriate statistical analysis?","a": "Exact percentages allow computing mean and standard deviation, while letter grades are summarized with frequencies and proportions","lvl": 3,"choices": ["Neither variable can be summarized graphically","Both variables must be analyzed using only a two-way frequency table","Exact percentages allow computing mean and standard deviation, while letter grades are summarized with frequencies and proportions","Letter grades allow computing a mean, while percentages only allow frequency counts"],"steps": ["Exact percentages are quantitative, allowing mean and SD.","Letter grades are categories, summarized by frequencies and proportions.","Match the tools to each kind of variable."]},{"id": "AlgI.34-16","std": "Alg I.34","q": "Which statement accurately distinguishes continuous quantitative data from discrete quantitative data?","a": "Continuous data can take any value in an interval (like time), while discrete data take countable values (like number of books)","lvl": 3,"choices": ["Continuous data are summarized with bar graphs, while discrete data are summarized with pie charts","Continuous data are always categorical, while discrete data are always numerical","Continuous data can take any value in an interval (like time), while discrete data take countable values (like number of books)","Discrete data can take any decimal value, while continuous data are only whole numbers"],"steps": ["Continuous data can take any value in an interval, like time.","Discrete data take distinct countable values, like book counts.","Which statement matches those two ideas?"]},{"id": "AlgI.35-08","std": "Alg I.35","q": "In a survey of 60 students, 18 prefer indoor recess and 12 prefer outdoor recess among 9th graders, while 10 prefer indoor and 20 prefer outdoor among 10th graders. What is the total number of students who prefer outdoor recess?","a": "32","lvl": 1,"part": "a","choices": ["20","28","30","32"],"steps": ["Find 9th graders who prefer outdoor recess: 12.","Find 10th graders who prefer outdoor recess: 20.","Add the two groups."]},{"id": "AlgI.35-09","std": "Alg I.35","q": "In a two-way table of 200 people, 50 are left-handed. What is the marginal relative frequency of being left-handed?","a": "0.25","lvl": 1,"part": "b","choices": ["0.20","0.25","0.50","0.75"],"steps": ["Identify the total number of left-handed people: 50.","Divide by the grand total of 200 people: {50/200}.","Write that fraction as a decimal."]},{"id": "AlgI.35-10","std": "Alg I.35","q": "What does each full bar in a segmented bar graph represent?","a": "100% of one category of the explanatory variable","lvl": 1,"part": "a","choices": ["The raw count of the largest group only","The difference between two categories","The average value of a quantitative variable","100% of one category of the explanatory variable"],"steps": ["In a segmented bar graph, every bar has the same full height.","That full height represents 100% of one explanatory category.","So what does one full bar stand for?"]},{"id": "AlgI.35-11","std": "Alg I.35","q": "In a two-way table of 150 students, 30 are seniors who drive to school. What is the joint relative frequency of being a senior who drives to school?","a": "0.20","lvl": 2,"part": "b","choices": ["0.15","0.20","0.30","0.50"],"steps": ["Identify the count for both senior and drives to school: 30.","Divide by the grand total of 150 students: {30/150}.","Write that fraction as a decimal."]},{"id": "AlgI.35-12","std": "Alg I.35","q": "A segmented bar graph shows that 70% of dog owners walk daily, while 35% of non-dog owners walk daily. What does this suggest?","a": "There is an association between owning a dog and walking daily","lvl": 2,"part": "c","choices": ["Walking daily is a quantitative variable","There is no association between owning a dog and walking daily","There is an association between owning a dog and walking daily","More people own dogs than do not own dogs"],"steps": ["Compare daily walking rates: 70% (dog owners) vs. 35% (non-owners).","The conditional percentages are very different between groups.","Big difference between groups. What does that suggest?"]},{"id": "AlgI.35-13","std": "Alg I.35","q": "In a survey, 40 out of 50 band students like jazz, and 15 out of 50 non-band students like jazz. What is the conditional relative frequency of liking jazz given that a student is in band?","a": "0.80","lvl": 2,"part": "b","choices": ["0.30","0.40","0.55","0.80"],"steps": ["Restrict to the given group: 50 band students.","Identify how many band students like jazz: 40.","Divide by the band total."]},{"id": "AlgI.35-14","std": "Alg I.35","q": "In a segmented bar graph comparing grade level (9th, 10th, 11th) and preferred lunch (pizza, salad, sandwich), all three bars have nearly identical segment heights. What conclusion is most appropriate?","a": "There is little to no association between grade level and preferred lunch","lvl": 3,"part": "c","choices": ["There is little to no association between grade level and preferred lunch","Pizza is the least popular lunch in every grade","There is a strong positive association between grade level and preferred lunch","All three grades have the exact same number of students"],"steps": ["Nearly identical segment heights mean similar conditional rates.","Lunch preference does not change much across grade levels.","What does that say about association?"]},{"id": "AlgI.35-15","std": "Alg I.35","q": "A table shows 120 total shoppers: 48 bought coffee, 60 bought a pastry, and 24 bought both. What is the conditional relative frequency of buying a pastry given that a shopper bought coffee?","a": "0.50","lvl": 3,"part": "b","choices": ["0.20","0.25","0.40","0.50"],"steps": ["Restrict to the given group: 48 shoppers who bought coffee.","Identify how many of them also bought a pastry: 24.","Divide by the coffee total."]},{"id": "AlgI.35-16","std": "Alg I.35","q": "Why is a segmented bar graph often more useful than a side-by-side raw count bar graph when checking for an association between two categorical variables?","a": "It displays conditional proportions out of 100%, removing distortions caused by unequal group sizes","lvl": 3,"part": "c","choices": ["It hides the smaller categories so the graph is simpler","It always proves that one variable causes the other","It shows the exact mean and median of each category","It displays conditional proportions out of 100%, removing distortions caused by unequal group sizes"],"steps": ["Raw count bars can look different just because group sizes differ.","Segmented bar graphs scale every group to 100%.","Pick the choice that explains this."]},{"id": "AlgI.36-07","std": "Alg I.36","q": "What is Simpson's Paradox?","a": "A trend that appears in several groups of data reverses when the groups are combined","lvl": 1,"choices": ["A trend that appears in several groups of data reverses when the groups are combined","A survey where every participant gives the same answer","A probability that is greater than 1","A graph that has no title or axis labels"],"steps": ["Recall the definition of Simpson's Paradox.","A trend holds inside each separate subgroup of data.","What happens to the trend when the groups combine?"]},{"id": "AlgI.36-08","std": "Alg I.36","q": "In Simpson's Paradox, what causes the direction of an association between two categorical variables to reverse?","a": "A lurking third variable with unequal group sizes","lvl": 1,"choices": ["A rounding error in the percentages","Using a bar graph instead of a pie chart","A lurking third variable with unequal group sizes","Having too many decimal places"],"steps": ["Combining subgroups weights them by their group sizes.","A lurking variable can make the groups very different sizes.","Pick the choice that names that cause."]},{"id": "AlgI.36-09","std": "Alg I.36","q": "Player A has a higher free-throw percentage than Player B in both the first half and the second half of the season, yet Player B has a higher overall percentage. What statistical phenomenon is this?","a": "Simpson's Paradox","lvl": 1,"choices": ["The Law of Large Numbers","Random sampling bias","Independent events","Simpson's Paradox"],"steps": ["Player A leads in both halves individually.","When the two halves are combined, Player B leads overall.","What is it called when a trend flips after combining groups?"]},{"id": "AlgI.36-10","std": "Alg I.36","q": "Hospital X has a higher survival rate than Hospital Y for mild cases AND for severe cases, yet Hospital Y has a higher overall survival rate. Which explanation makes this possible?","a": "Hospital X treats a much larger proportion of severe cases than Hospital Y","lvl": 2,"choices": ["Hospital X treats a much larger proportion of severe cases than Hospital Y","Hospital X reports its numbers incorrectly","Hospital Y has fewer doctors than Hospital X","Hospital Y treats only severe cases"],"steps": ["Severe cases have lower survival rates than mild cases.","Hospital X's overall rate drops if it treats mostly severe cases.","Which choice would pull Hospital X's overall rate down?"]},{"id": "AlgI.36-11","std": "Alg I.36","q": "Student A scores {1/1} (100%) on Easy quizzes and {4/10} (40%) on Hard quizzes. Student B scores {9/10} (90%) on Easy quizzes and {0/1} (0%) on Hard quizzes. Who has the higher overall percentage?","a": "Student B, with {9/11} (about 82%) compared to Student A's {5/11} (about 45%)","lvl": 2,"choices": ["Student B, with {9/11} (about 82%) compared to Student A's {5/11} (about 45%)","Student A, because Student A won both categories","They have the exact same overall percentage","Student A, with 70% compared to Student B's 45%"],"steps": ["Find Student A's total: (1 + 4) ÷ (1 + 10) = {5/11} ≈ 45%.","Find Student B's total: (9 + 0) ÷ (10 + 1) = {9/11} ≈ 82%.","Compare the two overall percents."]},{"id": "AlgI.36-12","std": "Alg I.36","q": "In a university admissions study, each individual department admitted a higher percentage of women than men, but overall a higher percentage of men were admitted. What is the lurking third variable?","a": "Which department applicants applied to","lvl": 2,"choices": ["The cost of tuition","The total number of classrooms","The year the university was founded","Which department applicants applied to"],"steps": ["The reversal appears when individual departments are combined.","Different departments have different admission rates and applicant mixes.","What variable changes from department to department?"]},{"id": "AlgI.36-13","std": "Alg I.36","q": "Treatment 1 succeeds in {90/100} small kidney stone cases (90%) and {20/100} large cases (20%). Treatment 2 succeeds in {80/100} small cases (80%) and {10/100} large cases (10%). Can Simpson's Paradox occur here?","a": "No, because both treatments were tested on the exact same number of small and large cases","lvl": 3,"choices": ["No, because both treatments were tested on the exact same number of small and large cases","Yes, because 90% is greater than 20%","Yes, because Treatment 2 will always win overall","No, because kidney stone size is a quantitative variable"],"steps": ["Check subgroup sizes: both treatments have 100 small and 100 large.","Simpson's Paradox requires unequal subgroup weights to reverse trends.","So can the trend flip here?"]},{"id": "AlgI.36-14","std": "Alg I.36","q": "Airline A has a better on-time rate than Airline B at every single airport, yet Airline B has a better overall on-time rate. Which condition must be true?","a": "Airline A flies a higher proportion of its flights out of airports with frequent weather delays","lvl": 3,"choices": ["Both airlines fly the exact same proportion of flights at each airport","Airline A flies a higher proportion of its flights out of airports with frequent weather delays","Airline A has older airplanes than Airline B","Airline B flies more total flights at every single airport"],"steps": ["Airline A wins at every airport but loses overall.","Its overall rate must be pulled down by harder, delay-prone airports.","Which choice would pull Airline A's overall rate down?"]},{"id": "AlgI.36-15","std": "Alg I.36","q": "When Simpson's Paradox occurs in a medical study comparing two treatments across mild and severe patients, which data should doctors usually rely on to choose a treatment for a specific patient?","a": "The subgroup data matching that patient's severity level","lvl": 3,"choices": ["Neither dataset, because the data must be invalid","The subgroup data matching that patient's severity level","Whichever group has the smaller sample size","Only the combined overall average"],"steps": ["Combined averages are distorted by the mix of mild and severe cases.","A specific patient has a known severity level.","So which data fits one specific patient?"]},{"id": "AlgI.37-09","std": "Alg I.37","q": "A standard six-sided die is rolled. What is the sample space of all possible outcomes?","a": "{1, 2, 3, 4, 5, 6}","lvl": 1,"choices": ["{1, 2, 3, 4, 5, 6}","{1, 3, 5}","{1, 2, 3, 4, 5}","{2, 4, 6}"],"steps": ["The sample space lists every possible outcome.","What numbers are on the faces of a six-sided die?","Write all of them as a set."]},{"id": "AlgI.37-10","std": "Alg I.37","q": "For a standard six-sided die, let event A be rolling an even number: A = {2, 4, 6}. What is the complement of event A (not A)?","a": "{1, 3, 5}","lvl": 1,"choices": ["{4, 5, 6}","{2, 4, 6}","{1, 2, 3}","{1, 3, 5}"],"steps": ["Start with the full sample space: {1, 2, 3, 4, 5, 6}.","Remove the outcomes in event A: {2, 4, 6}.","Write what is left as a set."]},{"id": "AlgI.37-11","std": "Alg I.37","q": "Let A = {1, 2, 3, 4} and B = {3, 4, 5, 6}. What is the intersection of A and B (A and B)?","a": "{3, 4}","lvl": 1,"choices": ["{1, 2}","{1, 2, 3, 4, 5, 6}","{5, 6}","{3, 4}"],"steps": ["The intersection (A and B) means outcomes in both sets.","Compare A = {1, 2, 3, 4} and B = {3, 4, 5, 6}.","Which numbers are in both?"]},{"id": "AlgI.37-12","std": "Alg I.37","q": "Let A = {1, 2, 3, 4} and B = {3, 4, 5, 6}. What is the union of A and B (A or B)?","a": "{1, 2, 3, 4, 5, 6}","lvl": 2,"choices": ["{1, 2, 3, 4, 5, 6}","{1, 2}","{1, 2, 5, 6}","{3, 4}"],"steps": ["Union (A or B) combines all outcomes in A, B, or both.","Merge {1, 2, 3, 4} and {3, 4, 5, 6} without repeating 3 or 4.","Write the merged set."]},{"id": "AlgI.37-13","std": "Alg I.37","q": "Two coins are flipped. Let H be heads and T be tails. Which subset represents the event 'at least one head'?","a": "{HH, HT, TH}","lvl": 2,"choices": ["{HH, HT, TH}","{HT, TH}","{HH}","{TT}"],"steps": ["List all outcomes for two coin flips: {HH, HT, TH, TT}.","Keep outcomes with 1 or 2 heads (at least one H).","Remove the outcome with no heads. Write what is left."]},{"id": "AlgI.37-14","std": "Alg I.37","q": "A card is drawn from a standard 52-card deck. Event R is drawing a red card and event K is drawing a king. Which outcome is in the intersection (R and K)?","a": "King of hearts","lvl": 2,"choices": ["King of hearts","King of spades","Queen of clubs","Ace of diamonds"],"steps": ["Intersection (R and K) needs a card that is both red and a king.","Red suits are hearts and diamonds.","Which choice is a red king?"]},{"id": "AlgI.37-15","std": "Alg I.37","q": "From the numbers 1 through 10, let A be multiples of 2 and B be multiples of 3. What is the complement of (A or B)?","a": "{1, 5, 7}","lvl": 3,"choices": ["{2, 3, 4, 6, 8, 9, 10}","{6}","{1, 3, 5, 7, 9}","{1, 5, 7}"],"steps": ["List A = {2, 4, 6, 8, 10} and B = {3, 6, 9}.","Find the union (A or B) = {2, 3, 4, 6, 8, 9, 10}.","Which numbers from 1 to 10 are not in that union?"]},{"id": "AlgI.37-16","std": "Alg I.37","q": "Two events A and B in a sample space have an empty intersection (A and B = {}). What does this mean about events A and B?","a": "They are mutually exclusive and cannot occur at the same time","lvl": 3,"choices": ["They are mutually exclusive and cannot occur at the same time","They must include every outcome in the sample space","They have the exact same outcomes","They are complements of each other"],"steps": ["An empty intersection means A and B share no outcomes.","Therefore, A and B cannot happen at the same time.","What do we call events that can't happen together?"]},{"id": "AlgI.37-17","std": "Alg I.37","q": "In a sample space S = {1, 2, 3, 4, 5, 6, 7, 8}, let A = {2, 4, 6, 8} and B = {5, 6, 7, 8}. Which set represents (A and not B)?","a": "{2, 4}","lvl": 3,"choices": ["{6, 8}","{2, 4}","{1, 3}","{5, 7}"],"steps": ["Find not B: the outcomes in S that are not in B.","Find the outcomes in both A and not B.","Write those shared outcomes as a set."]},{"id": "AlgI.38-07","std": "Alg I.38","q": "Using a two-way table, how can you check whether events A and B are independent?","a": "Check whether P(A and B) = P(A) · P(B), or whether P(A | B) = P(A)","lvl": 1,"choices": ["Check whether P(A) + P(B) = 1","Check whether A and B have the same total count","Check whether P(A and B) = P(A) · P(B), or whether P(A | B) = P(A)","Check whether P(A and B) = 0"],"steps": ["Recall the two equivalent tests for independence.","Check if P(A and B) = P(A) × P(B).","Which choice names those tests?"]},{"id": "AlgI.38-08","std": "Alg I.38","q": "A tree diagram shows flipping a fair coin (0.5 heads, 0.5 tails) and then rolling a fair die ({1/6} for each number). Are the two events independent?","a": "Yes, because the branch probabilities for the die do not change based on the coin result","lvl": 1,"choices": ["No, because there are 12 total outcomes","Yes, because the branch probabilities for the die do not change based on the coin result","Yes, because both events have probability 0.5","No, because 0.5 does not equal {1/6}"],"steps": ["Check the second-stage branch probabilities for the die.","Each die number is {1/6} after both heads and tails.","So are the events independent?"]},{"id": "AlgI.38-09","std": "Alg I.38","q": "In a bag of 5 red and 5 blue marbles, one marble is drawn and NOT replaced before a second marble is drawn. A tree diagram shows the second-draw probabilities change. Are the two draws independent?","a": "No, because the probability of the second draw depends on the first draw","lvl": 1,"choices": ["Yes, because there are still marbles left in the bag","No, because the probability of the second draw depends on the first draw","No, because red and blue are different colors","Yes, because the bag started with equal numbers of red and blue marbles"],"steps": ["Drawing without replacement changes the marbles left in the bag.","The second-draw probabilities depend on the first draw.","So are the two draws independent?"]},{"id": "AlgI.38-10","std": "Alg I.38","q": "In a two-way table of 100 students, 50 are athletes, 40 are in honor roll, and 20 are both. Are being an athlete and being on honor roll independent?","a": "Yes, because P(athlete and honor roll) = 0.20 equals 0.50 × 0.40","lvl": 2,"choices": ["Yes, because P(athlete and honor roll) = 0.20 equals 0.50 × 0.40","No, because 20 does not equal 50","Yes, because 20 is half of 40","No, because 50 + 40 does not equal 100"],"steps": ["Find P(athlete) = {50/100} = 0.50 and P(honor) = {40/100} = 0.40.","Multiply: 0.50 × 0.40 = 0.20.","Compare 0.20 with P(both) = 20 ÷ 100. Independent?"]},{"id": "AlgI.38-11","std": "Alg I.38","q": "In a two-way table of 200 adults, 80 drink tea, 100 exercise daily, and 60 do both. Are drinking tea and exercising daily independent?","a": "No, because P(tea and exercise) = 0.30, while P(tea) · P(exercise) = 0.40 × 0.50 = 0.20","lvl": 2,"choices": ["Yes, because 60 is less than 80","No, because P(tea and exercise) = 0.30, while P(tea) · P(exercise) = 0.40 × 0.50 = 0.20","Yes, because 80 + 100 is close to 200","No, because P(tea) does not equal P(exercise)"],"steps": ["Find P(tea) = {80/200} = 0.40 and P(exercise) = {100/200} = 0.50.","Multiply: 0.40 × 0.50 = 0.20.","Compare 0.20 with P(both) = 60 ÷ 200. Independent?"]},{"id": "AlgI.38-12","std": "Alg I.38","q": "A tree diagram shows: if it rains (0.3), the bus is late with probability 0.6; if it does not rain (0.7), the bus is late with probability 0.1. Are rain and the bus being late independent?","a": "No, because P(late | rain) = 0.6 does not equal P(late | no rain) = 0.1","lvl": 2,"choices": ["No, because 0.6 + 0.1 does not equal 1","Yes, because 0.3 + 0.7 = 1","Yes, because the bus can be late whether it rains or not","No, because P(late | rain) = 0.6 does not equal P(late | no rain) = 0.1"],"steps": ["Read P(late | rain) = 0.6 from the tree diagram.","Read P(late | no rain) = 0.1 from the tree diagram.","Are the two rates equal? What does that tell you?"]},{"id": "AlgI.38-13","std": "Alg I.38","q": "In a two-way table of 120 students, 30 take French and 40 take Art. How many students would need to take BOTH French and Art for the two events to be independent?","a": "10","lvl": 3,"choices": ["10","12","15","20"],"steps": ["Find P(French) = 30 ÷ 120 and P(Art) = 40 ÷ 120.","For independence, P(both) = P(French) × P(Art).","Multiply that probability by 120 students."]},{"id": "AlgI.38-14","std": "Alg I.38","q": "A two-way table shows P(A | B) = 0.35 and P(A | not B) = 0.35. What must be true about events A and B?","a": "Events A and B are independent","lvl": 3,"choices": ["P(B) must equal 0.35","Events A and B are mutually exclusive","P(A and B) must equal 0.35","Events A and B are independent"],"steps": ["Compare P(A | B) = 0.35 and P(A | not B) = 0.35.","Whether B occurs or not, the probability of A stays 0.35.","What does that tell you about A and B?"]},{"id": "AlgI.38-15","std": "Alg I.38","q": "In a table of 500 voters, 250 support Measure X, 200 are under age 30, and 100 are under age 30 and support Measure X. Which calculation proves independence?","a": "P(support | under 30) = {100/200} = 0.50, which equals P(support) = {250/500} = 0.50","lvl": 3,"choices": ["P(support) + P(under 30) = 0.50 + 0.40 = 0.90","P(support | under 30) = {100/200} = 0.50, which equals P(support) = {250/500} = 0.50","250 − 200 = 50, which is half of 100","{100/500} = 0.20, which is less than 0.50"],"steps": ["Compute P(support | under 30) = {100/200} = 0.50.","Compute overall P(support) = {250/500} = 0.50.","Are the two probabilities equal? What does that show?"]},{"id": "AlgI.39-09","std": "Alg I.39","q": "In a two-way table, 40 students play soccer, and 16 of those soccer players also play basketball. What is P(basketball | soccer)?","a": "0.40","lvl": 1,"choices": ["0.16","0.25","0.40","0.60"],"steps": ["Use the given condition (soccer) as the denominator: 40.","Use the overlap (both soccer and basketball) as numerator: 16.","Divide the overlap by the soccer total."]},{"id": "AlgI.39-10","std": "Alg I.39","q": "A tree diagram has first-stage branches A (0.6) and B (0.4). From branch A, the branch to Win is labeled 0.7. What is P(Win | A)?","a": "0.7","lvl": 1,"choices": ["0.28","0.42","0.6","0.7"],"steps": ["Second-stage tree branches show conditional probabilities.","Follow branch A to the Win branch.","Read the label on that branch."]},{"id": "AlgI.39-11","std": "Alg I.39","q": "Out of 50 people who ordered lunch, 35 ordered a drink. What is P(drink | ordered lunch)?","a": "0.70","lvl": 1,"choices": ["0.30","0.35","0.50","0.70"],"steps": ["Use the given group (ordered lunch) as the denominator: 50.","Use those who ordered a drink as the numerator: 35.","Divide 35 by 50."]},{"id": "AlgI.39-12","std": "Alg I.39","q": "A two-way table of 80 students shows: 24 seniors pass, 6 seniors fail, 35 juniors pass, 15 juniors fail. What is P(senior | pass)?","a": "{24/59}","lvl": 2,"choices": ["{24/80}","{24/30}","{24/59}","{30/80}"],"steps": ["The condition is pass, so the total passed goes on the bottom.","Add the seniors and juniors who passed.","Put the seniors who passed over that total."]},{"id": "AlgI.39-13","std": "Alg I.39","q": "Using the same table (24 seniors pass, 6 seniors fail, 35 juniors pass, 15 juniors fail), what is P(pass | junior)?","a": "0.70","lvl": 2,"choices": ["0.35","0.59","0.70","0.80"],"steps": ["Find the total number of juniors: 35 + 15 = 50.","Identify juniors who passed: 35.","Divide by the junior total."]},{"id": "AlgI.39-14","std": "Alg I.39","q": "A tree diagram shows: Machine 1 makes 60% of parts with a 5% defect rate; Machine 2 makes 40% of parts with a 10% defect rate. What is P(Machine 1 and defective)?","a": "0.03","lvl": 2,"choices": ["0.03","0.04","0.05","0.65"],"steps": ["Multiply along the tree path for Machine 1 and defective.","Convert percents to decimals: 0.60 and 0.05.","Multiply 0.60 × 0.05."]},{"id": "AlgI.39-15","std": "Alg I.39","q": "Using the tree diagram (Machine 1: 60% of parts, 5% defective; Machine 2: 40% of parts, 10% defective), what is P(Machine 1 | defective)?","a": "{3/7}","lvl": 3,"choices": ["0.05","0.03","{3/7}","{4/7}"],"steps": ["Find P(M1 and defective) = 0.60 × 0.05 and P(M2 and defective) = 0.40 × 0.10.","Add them to get the total P(defective).","Divide P(M1 and defective) by P(defective). Simplify."]},{"id": "AlgI.39-16","std": "Alg I.39","q": "In a two-way table, P(A and B) = 0.18 and P(B) = 0.45. What is P(A | B)?","a": "0.40","lvl": 3,"choices": ["0.081","0.27","0.40","0.63"],"steps": ["Use the formula P(A | B) = P(A and B) ÷ P(B).","Substitute the given values: 0.18 ÷ 0.45.","Do the division."]},{"id": "AlgI.39-17","std": "Alg I.39","q": "A bag has 4 red and 6 blue marbles. Two marbles are drawn without replacement. Using a tree diagram, what is P(second is red | first is blue)?","a": "{4/9}","lvl": 3,"choices": ["{3/9}","{4/10}","{6/9}","{4/9}"],"steps": ["After drawing 1 blue marble, 9 marbles remain in the bag.","All 4 red marbles are still in the bag.","Write red marbles over marbles left."]},{"id": "AlgI.40-07","std": "Alg I.40","q": "Which pair of everyday events is most likely independent?","a": "Rolling a 6 on a die and flipping heads on a coin","lvl": 1,"choices": ["Carrying an umbrella and it raining outside","Rolling a 6 on a die and flipping heads on a coin","Being a high school senior and having a driver's license","Studying for a test and earning an A on the test"],"steps": ["Independent events do not affect each other.","Rain and umbrellas are linked. So are studying and grades.","Which pair has no effect on each other?"]},{"id": "AlgI.40-08","std": "Alg I.40","q": "In everyday language, what does it mean if two events are independent?","a": "Knowing that one event happened does not change the chance that the other event happens","lvl": 1,"choices": ["One event always causes the other event","Both events have a 50% chance of happening","The two events can never happen at the same time","Knowing that one event happened does not change the chance that the other event happens"],"steps": ["Independence means one event gives no information about the other.","Knowing one happened does not change the other's probability.","Choose the statement that matches this everyday meaning."]},{"id": "AlgI.40-09","std": "Alg I.40","q": "Which statement describes a conditional probability?","a": "The chance that a student plays varsity sports, given that the student is over 6 feet tall","lvl": 1,"choices": ["The average height of all students in a school","The chance of flipping heads on a single fair coin","The chance that a student plays varsity sports, given that the student is over 6 feet tall","The total number of students in a school"],"steps": ["A conditional probability has a condition, often the word given.","Totals and averages are not probabilities.","Which choice limits the group with a given?"]},{"id": "AlgI.40-10","std": "Alg I.40","q": "Compare the chance of having a fever given that you have the flu versus the chance of having the flu given that you have a fever. Why are these two probabilities different?","a": "Most people with the flu have a fever, but many other illnesses can also cause a fever","lvl": 2,"choices": ["Having a fever and having the flu are independent events","Most people with the flu have a fever, but many other illnesses can also cause a fever","They are actually always the exact same probability","Conditional probability does not apply to medical situations"],"steps": ["P(fever | flu) is high because most flu patients get a fever.","P(flu | fever) is lower because many illnesses cause a fever.","Which choice explains why P(flu | fever) is lower?"]},{"id": "AlgI.40-11","std": "Alg I.40","q": "A weather app says the chance of a flight delay is 15% overall, but 60% if there is a thunderstorm. What does this tell you in everyday language?","a": "Flight delays and thunderstorms are not independent, because a thunderstorm makes a delay much more likely","lvl": 2,"choices": ["Flight delays and thunderstorms are independent events","A flight can never be delayed without a thunderstorm","Flight delays and thunderstorms are not independent, because a thunderstorm makes a delay much more likely","60% of all days have thunderstorms"],"steps": ["Compare overall delay rate (15%) with thunderstorm rate (60%).","Because 60% ≠ 15%, the events are not independent.","What does that say about storms and delays?"]},{"id": "AlgI.40-12","std": "Alg I.40","q": "A basketball player makes 80% of her free throws overall, and 80% of her free throws in the fourth quarter. How would you describe this in everyday language?","a": "Her free-throw shooting is independent of whether it is the fourth quarter","lvl": 2,"choices": ["Her free-throw shooting is independent of whether it is the fourth quarter","Making a free throw and being in the fourth quarter are mutually exclusive","She only shoots free throws in the fourth quarter","She is much more likely to miss in the fourth quarter"],"steps": ["Compare overall rate (80%) with fourth-quarter rate (80%).","The probability stays the same regardless of the quarter.","What does an unchanged rate tell you?"]},{"id": "AlgI.40-13","std": "Alg I.40","q": "A store notices that 90% of people who buy a winter coat also live in a cold climate, and 20% of people who live in a cold climate buy a winter coat this year. Explain the difference between these two conditional probabilities.","a": "The first restricts attention to coat buyers; the second restricts attention to people living in cold climates","lvl": 3,"choices": ["Both percentages refer to the entire population of the country","The two percentages must add to 100%, so the data are wrong","Living in a cold climate and buying a coat are independent","The first restricts attention to coat buyers; the second restricts attention to people living in cold climates"],"steps": ["Identify the given group for 90%: people who buy a winter coat.","Identify the given group for 20%: people living in a cold climate.","Pick the choice that compares the two given groups."]},{"id": "AlgI.40-14","std": "Alg I.40","q": "A student says, 'Because I flipped 5 heads in a row, tails is now more likely on the next flip.' How does the concept of independence correct this reasoning?","a": "Each flip of a fair coin is independent of previous flips, so the probability of tails remains 50%","lvl": 3,"choices": ["The coin must now land on tails to balance the sample space","Previous flips make heads more likely on the next flip","Each flip of a fair coin is independent of previous flips, so the probability of tails remains 50%","The probability of tails actually decreases to 0%"],"steps": ["A fair coin has no memory of previous flips.","Each flip is independent of the 5 heads before it.","So what is P(tails) on the next flip?"]},{"id": "AlgI.41-07","std": "Alg I.41","q": "When computing P(A | B), which set of outcomes serves as the new reduced sample space (the denominator)?","a": "The outcomes in event B","lvl": 1,"choices": ["All outcomes in the entire sample space","The outcomes in event A","The outcomes in event B","The outcomes in neither A nor B"],"steps": ["In P(A | B), the vertical bar means 'given B'.","We restrict our focus only to outcomes where B occurs.","So which set is the new sample space?"]},{"id": "AlgI.41-08","std": "Alg I.41","q": "In a standard deck of 52 cards, there are 13 hearts, and 3 of them are face cards (J, Q, K). Why is P(face card | heart) equal to {3/13} instead of {3/52}?","a": "Because we already know the card is a heart, so we only consider the 13 hearts","lvl": 1,"choices": ["Because there are only 13 cards in a deck","Because we already know the card is a heart, so we only consider the 13 hearts","Because face cards are not included in the 52 cards","Because {3/52} is not a valid probability"],"steps": ["We already know the drawn card is a heart.","Reduce the sample space from 52 cards to the 13 hearts.","How many of those 13 are face cards?"]},{"id": "AlgI.41-09","std": "Alg I.41","q": "In a class of 30 students, 10 wear glasses, and 4 of those 10 have brown hair. What fraction represents P(brown hair | wears glasses)?","a": "{4/10}","lvl": 1,"choices": ["{4/10}","{4/30}","{10/30}","{6/10}"],"steps": ["Use the given group (wears glasses) as the denominator: 10.","Use glasses-wearers with brown hair as the numerator: 4.","Write that as a fraction."]},{"id": "AlgI.41-10","std": "Alg I.41","q": "A fair 6-sided die is rolled. Event B is rolling an even number {2, 4, 6}, and event A is rolling a number greater than 3 {4, 5, 6}. Why is P(A | B) = {2/3}?","a": "Out of the 3 outcomes in B, exactly 2 of them (4 and 6) also belong to A","lvl": 2,"choices": ["Out of the 3 outcomes in A, 2 of them are odd","Out of the 3 outcomes in B, exactly 2 of them (4 and 6) also belong to A","Out of the 6 outcomes on the die, 4 of them are even or greater than 3","Because P(A) = {1/2} and P(B) = {1/2}"],"steps": ["Restrict to event B = {2, 4, 6}, which has 3 outcomes.","Count how many of those also belong to A = {4, 5, 6}: 4 and 6.","So what fraction of B is also in A?"]},{"id": "AlgI.41-11","std": "Alg I.41","q": "In a survey of 100 pets at a clinic, 60 are dogs, and 45 of the dogs are vaccinated. Interpret P(vaccinated | dog) = {45/60} = 0.75 in context.","a": "75% of the dogs at the clinic are vaccinated","lvl": 2,"choices": ["60% of the pets at the clinic are vaccinated","75% of all vaccinated pets are dogs","75% of all pets at the clinic are vaccinated dogs","75% of the dogs at the clinic are vaccinated"],"steps": ["The condition 'dog' restricts attention to the 60 dogs.","Compute {45/60} = 0.75, or 75%.","What does 0.75 mean for the dogs?"]},{"id": "AlgI.41-12","std": "Alg I.41","q": "In a group of 40 hikers, 25 brought water, 20 brought snacks, and 15 brought both. What is P(snacks | water) and what does it mean?","a": "{15/25} = 60%; 60% of the hikers who brought water also brought snacks","lvl": 2,"choices": ["{15/40} = 37.5%; 37.5% of the hikers who brought water also brought snacks","{15/20} = 75%; 75% of the hikers who brought water also brought snacks","{15/25} = 60%; 60% of the hikers who brought water also brought snacks","{20/25} = 80%; 80% of all hikers brought both"],"steps": ["Restrict to hikers who brought water: 25.","Put those who brought both (15) over 25.","Write it as a percent. What does it mean?"]},{"id": "AlgI.41-13","std": "Alg I.41","q": "Why does the formula P(A | B) = {P(A and B)/P(B)} give the exact same result as counting {number of outcomes in A and B/number of outcomes in B} for equally likely outcomes?","a": "Both the numerator and denominator are divided by the total number of outcomes N, which cancels out","lvl": 3,"choices": ["Because the total number of outcomes N is always 100","Because P(A and B) is always equal to P(A)","Both the numerator and denominator are divided by the total number of outcomes N, which cancels out","Because P(B) is always equal to 1"],"steps": ["Write P(A and B) = n(A and B) ÷ N and P(B) = n(B) ÷ N.","Divide P(A and B) by P(B) to form a complex fraction.","What happens to N when you divide?"]},{"id": "AlgI.41-14","std": "Alg I.41","q": "In a raffle of 50 tickets, 20 are blue and 30 are red. Exactly 5 blue tickets and 10 red tickets are winners. Interpret the difference between P(winner | blue) = {5/20} and P(blue | winner) = {5/15}.","a": "25% of blue tickets are winners, whereas 33.3% of winning tickets are blue","lvl": 3,"choices": ["25% of blue tickets are winners, whereas 33.3% of winning tickets are blue","25% of all tickets are winners, whereas 33.3% of all tickets are blue","Both fractions mean that 5 out of 50 tickets are blue winners","33.3% of blue tickets are winners, whereas 25% of winning tickets are blue"],"steps": ["For P(winner | blue), the blue tickets are the denominator.","For P(blue | winner), the winners are the denominator.","Turn each fraction into a percent and match."]},{"id": "AlgI.41-15","std": "Alg I.41","q": "If event B is a subset of event A (every outcome in B also belongs to A), what must P(A | B) equal, and why?","a": "1, because 100% of B's outcomes also belong to A","lvl": 3,"choices": ["0, because A and B have no overlap","P(A), because A contains B","P(B), because B is smaller than A","1, because 100% of B's outcomes also belong to A"],"steps": ["Because B is a subset of A, every outcome in B is also in A.","Therefore, (A and B) equals B.","What is P(B) ÷ P(B)?"]}]};
